const lessons = [
{num:1,time:"00:00:31,760 --> 00:00:36,820",arabic:"كَمَا تَشَاءِينَ يَا أُمَّ أَحْمَدَ",segs:null,full_uz:"Qanday xohlasangiz, Ahmadning onasi.",note:null},
{num:2,time:"00:00:36,820 --> 00:00:41,960",arabic:"قَدْ عَرَضَ عَلَيَّ عَمِّي الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ نَسَّاخًا لِلْكُتُبِ",segs:[{ar:"قَدْ عَرَضَ عَلَيَّ",uz:"menga taklif qildi"},{ar:"عَمِّي",uz:"amakim"},{ar:"الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ",uz:"Baytul Hikmada ishlashni"},{ar:"نَسَّاخًا لِلْكُتُبِ",uz:"kitoblarni ko‘chiruvchi sifatida"}],full_uz:"Amakim menga Baytul Hikmada kitoblarni ko‘chiruvchi bo‘lib ishlashni taklif qildi.",note:null},
{num:3,time:"00:00:41,960 --> 00:00:47,260",arabic:"وَطَلَبَكَ الْعِلْمَ",segs:null,full_uz:"Va ilm talab qilishingni.",note:null},
{num:4,time:"00:00:47,260 --> 00:00:50,260",arabic:"وَشَيْخُكَ",segs:null,full_uz:"Ustozing-chi?",note:null},
{num:5,time:"00:00:50,260 --> 00:00:54,060",arabic:"سَأُوَفِّقُ إِنْ شَاءَ اللَّهُ بَيْنَ الْعَمَلِ وَطَلَبِ الْعِلْمِ",segs:[{ar:"سَأُوَفِّقُ",uz:"muvofiqlashtiraman"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"},{ar:"بَيْنَ الْعَمَلِ وَطَلَبِ الْعِلْمِ",uz:"ish bilan ilm talab qilishni"}],full_uz:"Alloh xohlasa, ish bilan ilm talab qilishni birga olib boraman.",note:null},
{num:6,time:"00:00:54,060 --> 00:00:56,000",arabic:"وَإِنْ لَمْ تَسْتَطِعْ",segs:null,full_uz:"Agar uddalay olmasang.",note:null},
{num:7,time:"00:00:56,000 --> 00:00:57,620",arabic:"أَقْصِدُ",segs:null,full_uz:"Ya’ni.",note:null},
{num:8,time:"00:00:57,619 --> 00:01:00,419",arabic:"إِنْ شَغَلَكَ الْعَمَلُ عَنْ طَلَبِ الْعِلْمِ",segs:[{ar:"إِنْ شَغَلَكَ الْعَمَلُ",uz:"agar ish seni band qilsa"},{ar:"عَنْ طَلَبِ الْعِلْمِ",uz:"ilm talab qilishdan"}],full_uz:"Agar ish seni ilm talab qilishdan chalg‘itsa.",note:null},
{num:9,time:"00:01:00,419 --> 00:01:02,159",arabic:"أَخْبَرْتُ عَمِّي بِذَلِكَ",segs:[{ar:"أَخْبَرْتُ عَمِّي",uz:"amakimga aytdim"},{ar:"بِذَلِكَ",uz:"buni"}],full_uz:"Bu haqda amakimga aytdim.",note:null},
{num:10,time:"00:01:02,159 --> 00:01:04,060",arabic:"وَوَعَدَنِي بِأَنَّهُ سَيَجِدُ لِي حَلًّا",segs:[{ar:"وَوَعَدَنِي",uz:"u menga va’da berdi"},{ar:"بِأَنَّهُ سَيَجِدُ لِي حَلًّا",uz:"men uchun yechim topishiga"}],full_uz:"U menga men uchun yechim topishga va’da berdi.",note:null},
{num:11,time:"00:01:04,060 --> 00:01:06,340",arabic:"أَنْتَ تَعْرِفُ يَا وَالِدِي",segs:null,full_uz:"Siz bilasiz, otajon.",note:null},
{num:12,time:"00:01:06,340 --> 00:01:08,340",arabic:"أَنَّ طَلَبَكَ الْعِلْمَ",segs:null,full_uz:"Ilm talab qilishing...",note:null},
{num:13,time:"00:01:08,340 --> 00:01:11,099",arabic:"لَيْسَ لِي بِهِ الدُّنْيَا وَمَا عَلَيْهَا",segs:[{ar:"لَيْسَ لِي بِهِ",uz:"uning evaziga men uchun"},{ar:"الدُّنْيَا وَمَا عَلَيْهَا",uz:"dunyo va undagi barcha narsadan"}],full_uz:"Ilm talab qilish men uchun dunyo va undagi barcha narsadan azizdir.",note:null},
{num:14,time:"00:01:11,099 --> 00:01:14,159",arabic:"وَلَنْ يُضَيِّعَنَا اللَّهُ فِي أَرْزَاقِنَا",segs:[{ar:"وَلَنْ يُضَيِّعَنَا اللَّهُ",uz:"Alloh bizni zoye qilmaydi"},{ar:"فِي أَرْزَاقِنَا",uz:"rizqlarimiz borasida"}],full_uz:"Alloh rizqlarimiz borasida bizni zoye qilmaydi.",note:null},
{num:15,time:"00:01:14,159 --> 00:01:18,700",arabic:"لَكِنْ يَا أُمِّي",segs:null,full_uz:"Ammo, onajon.",note:null},
{num:16,time:"00:01:18,700 --> 00:01:21,359",arabic:"نَحْنُ بِحَاجَةٍ لِهَذَا الْمَالِ",segs:[{ar:"نَحْنُ بِحَاجَةٍ",uz:"biz muhtojmiz"},{ar:"لِهَذَا الْمَالِ",uz:"bu pulga"}],full_uz:"Bizga bu pul kerak.",note:null},
{num:17,time:"00:01:21,359 --> 00:01:24,459",arabic:"فَأَنْتِ تَرَيْنَ مَا آلَتْ إِلَيْهِ أَحْوَالُنَا",segs:[{ar:"فَأَنْتِ تَرَيْنَ",uz:"chunki o‘zingiz ko‘rib turibsiz"},{ar:"مَا آلَتْ إِلَيْهِ أَحْوَالُنَا",uz:"ahvolimiz qanday bo‘lib qolganini"}],full_uz:"Axir ahvolimiz qanday bo‘lib qolganini o‘zingiz ko‘rib turibsiz.",note:null},
{num:18,time:"00:01:24,459 --> 00:01:27,099",arabic:"أَنَا أُقَدِّرُ حِرْصَكَ عَلَيَّ يَا وَالِدِي",segs:[{ar:"أَنَا أُقَدِّرُ",uz:"men qadrlayman"},{ar:"حِرْصَكَ عَلَيَّ",uz:"menga bo‘lgan g‘amxo‘rligingizni"}],full_uz:"Menga bo‘lgan g‘amxo‘rligingizni qadrlayman, otajon.",note:null},
{num:19,time:"00:01:27,099 --> 00:01:32,159",arabic:"فَأَنْتَ رَجُلُ الْبَيْتِ وَالْقَيِّمُ عَلَيْهِ",segs:[{ar:"فَأَنْتَ رَجُلُ الْبَيْتِ",uz:"siz xonadonning erkagisiz"},{ar:"وَالْقَيِّمُ عَلَيْهِ",uz:"va uning boshqaruvchisisiz"}],full_uz:"Siz xonadonning erkagi va uning boshqaruvchisisiz.",note:null},
{num:20,time:"00:01:32,159 --> 00:01:37,819",arabic:"وَغِذَائِي فِي غُدُوِّكَ وَرَوَاحِكَ عِنْدَ شَيْخِكَ",segs:[{ar:"وَغِذَائِي",uz:"mening quvonchim"},{ar:"فِي غُدُوِّكَ وَرَوَاحِكَ",uz:"borib-kelishingizdadir"},{ar:"عِنْدَ شَيْخِكَ",uz:"ustozingiz huzuriga"}],full_uz:"Mening quvonchim sizning ustozingiz huzuriga borib-kelishingizdadir.",note:null},
{num:21,time:"00:01:37,819 --> 00:01:43,099",arabic:"وَقُرَّةُ عَيْنِي فِي حَمْلِكَ الْقَرَاطِيسَ وَالْمِحْبَرَةَ",segs:[{ar:"وَقُرَّةُ عَيْنِي",uz:"ko‘z quvonchim"},{ar:"فِي حَمْلِكَ الْقَرَاطِيسَ وَالْمِحْبَرَةَ",uz:"qog‘ozlar va siyohdonni ko‘tarib yurishingizdadir"}],full_uz:"Ko‘z quvonchim esa qog‘ozlar bilan siyohdonni ko‘tarib yurishingizdadir.",note:null},
{num:22,time:"00:01:43,099 --> 00:01:50,199",arabic:"لَا أَدْرِي مَا أَقُولُ لَكَ يَا وَلَدِي",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"مَا أَقُولُ لَكَ",uz:"senga nima deyishni"}],full_uz:"Senga nima deyishni bilmayman, bolam.",note:null},
{num:23,time:"00:01:52,199 --> 00:01:55,840",arabic:"وَلَكِنْ فِي صَدْرِي شَيْءٌ مِنْ هَذَا الْعَمَلِ",segs:[{ar:"وَلَكِنْ",uz:"ammo"},{ar:"فِي صَدْرِي شَيْءٌ",uz:"ko‘nglimda bir xavotir bor"},{ar:"مِنْ هَذَا الْعَمَلِ",uz:"bu ish borasida"}],full_uz:"Ammo bu ish borasida ko‘nglimda bir xavotir bor.",note:null},
{num:24,time:"00:01:55,840 --> 00:02:00,480",arabic:"وَأَخَافُ أَنْ يَأْخُذَ مِنْكَ وَقْتًا طَوِيلًا",segs:[{ar:"وَأَخَافُ",uz:"qo‘rqaman"},{ar:"أَنْ يَأْخُذَ مِنْكَ",uz:"u sendan olib qo‘yishidan"},{ar:"وَقْتًا طَوِيلًا",uz:"ko‘p vaqtni"}],full_uz:"Bu ishdan ko‘p vaqting ketib qolishidan qo‘rqaman.",note:null},
{num:25,time:"00:02:00,480 --> 00:02:02,420",arabic:"فَيَصْرِفَكَ عَنْ طَلَبِ الْعِلْمِ",segs:[{ar:"فَيَصْرِفَكَ",uz:"shunda seni chalg‘itadi"},{ar:"عَنْ طَلَبِ الْعِلْمِ",uz:"ilm talab qilishdan"}],full_uz:"Shunda seni ilm talab qilishdan chalg‘itadi.",note:null},
{num:26,time:"00:02:02,420 --> 00:02:06,200",arabic:"كُونِي عَلَى يَقِينٍ لَنْ أُقَدِّمَ زَائِلًا عَلَى بَاقٍ",segs:[{ar:"كُونِي عَلَى يَقِينٍ",uz:"ishonchingiz komil bo‘lsin"},{ar:"لَنْ أُقَدِّمَ زَائِلًا",uz:"o‘tkinchi narsani ustun qo‘ymayman"},{ar:"عَلَى بَاقٍ",uz:"abadiy narsadan"}],full_uz:"Ishonchingiz komil bo‘lsin, o‘tkinchi narsani abadiy narsadan ustun qo‘ymayman.",note:null},
{num:27,time:"00:02:06,200 --> 00:02:09,480",arabic:"وَلَنْ أَبِيعَ الْعِلْمَ بِعَرَضٍ مِنَ الدُّنْيَا",segs:[{ar:"وَلَنْ أَبِيعَ الْعِلْمَ",uz:"ilmni sotmayman"},{ar:"بِعَرَضٍ مِنَ الدُّنْيَا",uz:"dunyo matosi evaziga"}],full_uz:"Ilmni dunyo matosi evaziga sotmayman.",note:null},
{num:28,time:"00:02:09,480 --> 00:02:10,259",arabic:"فَمَعْقُولٌ",segs:null,full_uz:"Unda ma’qul.",note:null},
{num:29,time:"00:02:21,259 --> 00:02:23,300",arabic:"وَهَذَا مِفْتَاحُ الدُّكَّانِ",segs:[{ar:"وَهَذَا",uz:"mana bu"},{ar:"مِفْتَاحُ الدُّكَّانِ",uz:"do‘konning kaliti"}],full_uz:"Mana bu do‘konning kaliti.",note:null},
{num:30,time:"00:02:23,300 --> 00:02:27,800",arabic:"مِفْتَاحٌ",segs:null,full_uz:"Kalit.",note:null},
{num:31,time:"00:02:27,800 --> 00:02:29,780",arabic:"مِفْتَاحُ الدُّكَّانِ",segs:null,full_uz:"Do‘konning kaliti.",note:null},
{num:32,time:"00:02:31,160 --> 00:02:34,700",arabic:"تَجْمَعُ النِّعَالَةَ وَالْجُلُودَ",segs:[{ar:"تَجْمَعُ",uz:"yig‘asan"},{ar:"النِّعَالَةَ وَالْجُلُودَ",uz:"charm va poyabzal materiallarini"}],full_uz:"Charm va poyabzal uchun terilarni yig‘asan.",note:"النِّعَالَةُ — poyabzal."},
{num:33,time:"00:02:34,700 --> 00:02:36,000",arabic:"وَالصَّمْغَةَ وَالْحِبَالَ",segs:null,full_uz:"Yelim va arqonlarni ham.",note:null},
{num:34,time:"00:02:36,000 --> 00:02:37,560",arabic:"وَتَذْهَبُ فِي الصَّبَاحِ",segs:[{ar:"وَتَذْهَبُ",uz:"va borasan"},{ar:"فِي الصَّبَاحِ",uz:"ertalab"}],full_uz:"Va ertalab borasan.",note:null},
{num:35,time:"00:02:37,560 --> 00:02:41,200",arabic:"وَإِيَّاكَ ثُمَّ إِيَّاكَ ثُمَّ إِيَّاكَ",segs:[{ar:"وَإِيَّاكَ",uz:"ehtiyot bo‘l"},{ar:"ثُمَّ إِيَّاكَ",uz:"yana ehtiyot bo‘l"},{ar:"ثُمَّ إِيَّاكَ",uz:"yana juda ehtiyot bo‘l"}],full_uz:"Va juda-juda ehtiyot bo‘l.",note:null},
{num:36,time:"00:02:41,200 --> 00:02:43,080",arabic:"أَنْ أَجِدَكَ نَائِمًا فِي الدُّكَّانِ",segs:[{ar:"أَنْ أَجِدَكَ",uz:"seni topib qolmay"},{ar:"نَائِمًا فِي الدُّكَّانِ",uz:"do‘konda uxlab yotgan"}],full_uz:"Seni do‘konda uxlab yotgan holda topib qolmay.",note:null},
{num:37,time:"00:02:43,080 --> 00:02:43,720",arabic:"دُونَ عَمَلٍ",segs:null,full_uz:"Ishsiz.",note:null},
{num:38,time:"00:02:43,720 --> 00:02:46,200",arabic:"أَفْتَحُ الدُّكَّانَ",segs:null,full_uz:"Do‘konni ochaman.",note:null},
{num:39,time:"00:02:46,200 --> 00:02:49,380",arabic:"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ",segs:[{ar:"أَصْبَحْنَا",uz:"tong ottirdik"},{ar:"وَأَصْبَحَ الْمُلْكُ لِلَّهِ",uz:"mulk Allohnikidir"}],full_uz:"Tong ottirdik, mulk Allohnikidir.",note:null},
{num:40,time:"00:02:49,380 --> 00:02:51,460",arabic:"وَأَدْخُلُ وَأَعْمَلُ",segs:[{ar:"وَأَدْخُلُ",uz:"kiraman"},{ar:"وَأَعْمَلُ",uz:"va ishlayman"}],full_uz:"Kiraman va ishlayman.",note:null},
{num:41,time:"00:02:52,639 --> 00:02:56,359",arabic:"وَلَكِنْ مِنْ أَيْنَ سَنَدْفَعُ كِرَاءَ الدُّكَّانِ؟",segs:[{ar:"وَلَكِنْ",uz:"ammo"},{ar:"مِنْ أَيْنَ سَنَدْفَعُ",uz:"qayerdan to‘laymiz"},{ar:"كِرَاءَ الدُّكَّانِ",uz:"do‘kon ijarasini"}],full_uz:"Ammo do‘kon ijarasini qayerdan to‘laymiz?",note:null},
{num:42,time:"00:02:56,359 --> 00:02:59,399",arabic:"أَعْطَيْتُ أُمَّ أَحْمَدَ كِرَاءَ هَذَا الشَّهْرِ",segs:[{ar:"أَعْطَيْتُ",uz:"berdim"},{ar:"كِرَاءَ هَذَا الشَّهْرِ",uz:"shu oyning ijara haqini"}],full_uz:"Shu oyning ijara haqini Ahmadning onasiga berdim.",note:null},
{num:43,time:"00:02:59,399 --> 00:03:01,299",arabic:"وَالْأَرْزَاقُ بِيَدِ اللَّهِ يَا بُنَيَّ",segs:[{ar:"وَالْأَرْزَاقُ بِيَدِ اللَّهِ",uz:"rizqlar Allohning qo‘lidadir"},{ar:"يَا بُنَيَّ",uz:"bolam"}],full_uz:"Rizqlar Allohning qo‘lidadir, bolam.",note:null},
{num:44,time:"00:03:01,299 --> 00:03:07,500",arabic:"أُمِّي أَخْشَى أَنَّنِي لَنْ أَسْتَطِيعَ أَنْ أَحْصُلَ عَلَى مَا يَكْفِي",segs:[{ar:"أُمِّي",uz:"onajon"},{ar:"أَخْشَى",uz:"qo‘rqaman"},{ar:"أَنَّنِي لَنْ أَسْتَطِيعَ",uz:"uddalay olmasligimdan"},{ar:"أَنْ أَحْصُلَ عَلَى مَا يَكْفِي",uz:"yetarli miqdorni topa olmasligimdan"}],full_uz:"Onajon, yetarli miqdorda topa olmasligimdan qo‘rqaman.",note:null},
{num:45,time:"00:03:07,500 --> 00:03:09,519",arabic:"لَا تَبْدَأْ بِتَذَمُّرِي مِنَ الْآنِ",segs:[{ar:"لَا تَبْدَأْ",uz:"boshlama"},{ar:"بِتَذَمُّرِي مِنَ الْآنِ",uz:"hozirning o‘zidanoq shikoyat qilishni"}],full_uz:"Hozirning o‘zidanoq shikoyat qilishni boshlama.",note:null},
{num:46,time:"00:03:09,519 --> 00:03:12,419",arabic:"بِإِمْكَانِكَ أَنْ تَجْمَعَ الْكَثِيرَ مِنَ الْمَالِ",segs:[{ar:"بِإِمْكَانِكَ",uz:"qo‘lingdan keladi"},{ar:"أَنْ تَجْمَعَ الْكَثِيرَ مِنَ الْمَالِ",uz:"ko‘p pul yig‘ish"}],full_uz:"Ko‘p pul yig‘ishing mumkin.",note:null},
{num:47,time:"00:03:12,419 --> 00:03:18,419",arabic:"حِينَئِذٍ نَسْتَطِيعُ أَنْ نَجْمَعَ مَا نَجِدُ لَكَ بِهِ عَرُوسًا جَمِيلَةً",segs:[{ar:"حِينَئِذٍ",uz:"shunda"},{ar:"نَسْتَطِيعُ",uz:"biz qila olamiz"},{ar:"أَنْ نَجْمَعَ",uz:"yig‘ishimiz"},{ar:"مَا نَجِدُ لَكَ بِهِ",uz:"sen uchun topishga yetadigan mablag‘ni"},{ar:"عَرُوسًا جَمِيلَةً",uz:"chiroyli kelin"}],full_uz:"Shunda senga chiroyli kelin topish uchun yetadigan pulni yig‘a olamiz.",note:null},
{num:48,time:"00:03:18,419 --> 00:03:23,659",arabic:"عَرُوسٌ؟",segs:null,full_uz:"Kelin?",note:null},
{num:49,time:"00:03:23,659 --> 00:03:25,000",arabic:"أَجَلْ عَرُوسٌ",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"عَرُوسٌ",uz:"kelin"}],full_uz:"Ha, kelin.",note:null},
{num:50,time:"00:03:25,000 --> 00:03:27,859",arabic:"أَلَا تَرَى أَنَّ أَتْرَابَكَ قَدْ تَزَوَّجُوا مُنْذُ سِنِينَ",segs:[{ar:"أَلَا تَرَى",uz:"ko‘rmayapsanmi"},{ar:"أَنَّ أَتْرَابَكَ قَدْ تَزَوَّجُوا",uz:"tengdoshlaring turmush qurib bo‘lganini"},{ar:"مُنْذُ سِنِينَ",uz:"yillar oldin"}],full_uz:"Tengdoshlaring yillar oldin uylanganini ko‘rmayapsanmi?",note:null},
{num:51,time:"00:03:27,859 --> 00:03:31,000",arabic:"وَأَنْتَ قَدْ تَجَاوَزْتَ الثَّلَاثِينَ وَلَمَّا تَتَزَوَّجْ؟",segs:[{ar:"وَأَنْتَ قَدْ تَجَاوَزْتَ الثَّلَاثِينَ",uz:"sen esa o‘ttiz yoshdan oshding"},{ar:"وَلَمَّا تَتَزَوَّجْ",uz:"hali ham uylanmading"}],full_uz:"Sen esa o‘ttiz yoshdan oshding-u, hali ham uylanmading?",note:null},
{num:52,time:"00:03:31,679 --> 00:03:34,000",arabic:"أَعِدُكِ يَا أُمِّي أَنْ أَصِلَ اللَّيْلَ بِالنَّهَارِ",segs:[{ar:"أَعِدُكِ",uz:"senga va’da beraman"},{ar:"أَنْ أَصِلَ اللَّيْلَ بِالنَّهَارِ",uz:"kechani kunduzga ulab ishlashga"}],full_uz:"Senga va’da beraman, kechani kunduzga ulab ishlayman.",note:null},
{num:53,time:"00:03:34,000 --> 00:03:35,799",arabic:"كَيْ أَجْمَعَ صَدَاقَ عَرُوسِي",segs:[{ar:"كَيْ أَجْمَعَ",uz:"yig‘ish uchun"},{ar:"صَدَاقَ عَرُوسِي",uz:"kelinimning mahrini"}],full_uz:"Kelinimning mahrini yig‘ish uchun.",note:null},
{num:54,time:"00:03:35,799 --> 00:03:39,399",arabic:"أَرَاكَ الْآنَ قَدْ تَرَكْتَ التَّذَمُّرَ بَعْدَ أَنْ سَمِعْتَ بِالْعَرُوسِ",segs:[{ar:"أَرَاكَ الْآنَ",uz:"endi seni ko‘ryapmanki"},{ar:"قَدْ تَرَكْتَ التَّذَمُّرَ",uz:"shikoyatni tashlabsan"},{ar:"بَعْدَ أَنْ سَمِعْتَ بِالْعَرُوسِ",uz:"kelin haqida eshitganingdan keyin"}],full_uz:"Kelin haqida eshitganingdan keyin endi shikoyatni tashlaganingni ko‘ryapman.",note:null},
{num:55,time:"00:03:39,399 --> 00:03:42,139",arabic:"وَلَسْتَ بِعَنْتَرَ وَلَا هِيَ بِعَبْلَةَ",segs:[{ar:"وَلَسْتَ بِعَنْتَرَ",uz:"sen Antara emassan"},{ar:"وَلَا هِيَ بِعَبْلَةَ",uz:"u ham Abla emas"}],full_uz:"Sen Antara emassan, u ham Abla emas.",note:null},
{num:56,time:"00:03:42,139 --> 00:03:44,439",arabic:"أُمِّي أَعِدُكِ أَنَّنِي لَنْ أَتَذَمَّرَ",segs:[{ar:"أَعِدُكِ",uz:"va’da beraman"},{ar:"أَنَّنِي لَنْ أَتَذَمَّرَ",uz:"shikoyat qilmasligimni"}],full_uz:"Onajon, shikoyat qilmasligimga va’da beraman.",note:null},
{num:57,time:"00:03:44,439 --> 00:03:45,639",arabic:"سَنَرَى",segs:null,full_uz:"Ko‘ramiz.",note:null},
{num:58,time:"00:03:45,639 --> 00:03:47,079",arabic:"سَتَرَيْنَ يَا أُمَّ عَامِرٍ",segs:null,full_uz:"Ko‘rasiz, Umu Amir.",note:null},
{num:59,time:"00:03:47,079 --> 00:03:48,319",arabic:"إِلَى الْعَمَلِ يَا عَامِرُ",segs:null,full_uz:"Ishga.",note:null},
{num:60,time:"00:03:48,319 --> 00:03:50,479",arabic:"إِلَى الدُّكَّانِ عَرُوسِي",segs:[{ar:"إِلَى الدُّكَّانِ",uz:"do‘konga"},{ar:"عَرُوسِي",uz:"kelinim"}],full_uz:"Do‘konga, kelinim.",note:null},
{num:61,time:"00:03:50,479 --> 00:04:13,979",arabic:"تَبْدُو فَتَاةً طَيِّبَةً",segs:[{ar:"تَبْدُو",uz:"ko‘rinadi"},{ar:"فَتَاةً طَيِّبَةً",uz:"yaxshi qiz"}],full_uz:"Yaxshi qizga o‘xshaydi.",note:null},
{num:62,time:"00:04:13,979 --> 00:04:15,979",arabic:"كَانَ اللَّهُ فِي عَوْنِهَا",segs:null,full_uz:"Alloh unga yordam bersin.",note:null},
{num:63,time:"00:04:15,979 --> 00:04:20,180",arabic:"إِنَّهَا طَيِّبَةٌ إِلَى حَدٍّ أَنَّهَا تُضَيِّعُ وَالِدَهَا فِي السُّوقِ",segs:[{ar:"إِنَّهَا طَيِّبَةٌ",uz:"u juda yaxshi"},{ar:"إِلَى حَدٍّ أَنَّهَا تُضَيِّعُ وَالِدَهَا",uz:"hatto otasini yo‘qotib qo‘yadigan darajada"},{ar:"فِي السُّوقِ",uz:"bozorda"}],full_uz:"U shunchalik yaxshi qizki, bozorda hatto otasini yo‘qotib qo‘yadi.",note:null},
{num:64,time:"00:04:20,180 --> 00:04:23,360",arabic:"كِطِفْلٍ يَخْرُجُ مَعَ وَالِدَيْهِ لِأَوَّلِ مَرَّةٍ",segs:[{ar:"كِطِفْلٍ",uz:"xuddi bola kabi"},{ar:"يَخْرُجُ مَعَ وَالِدَيْهِ",uz:"ota-onasi bilan chiqadigan"},{ar:"لِأَوَّلِ مَرَّةٍ",uz:"birinchi marta"}],full_uz:"Xuddi ota-onasi bilan birinchi marta chiqqan boladek.",note:null},
{num:65,time:"00:04:23,360 --> 00:04:27,219",arabic:"يَجِبُ أَنْ تُسَاعِدَهَا يَا خَالِدُ",segs:null,full_uz:"Unga yordam berishing kerak, Xolid.",note:null},
{num:66,time:"00:04:27,219 --> 00:04:29,399",arabic:"لَنْ آلُوَ مَعَهَا يَا أُمِّي",segs:null,full_uz:"Onajon, unga yordam berishda bor kuchimni sarflayman.",note:"آلَا يَأْلُو — qo‘lidan kelganini ayamaslik."},
{num:67,time:"00:04:29,399 --> 00:04:32,279",arabic:"غَدًا سَأَبْحَثُ فِي السُّوقِ وَأَسْأَلُ الْبَاعَةَ وَالتُّجَّارَ",segs:[{ar:"غَدًا",uz:"ertaga"},{ar:"سَأَبْحَثُ فِي السُّوقِ",uz:"bozordan izlayman"},{ar:"وَأَسْأَلُ الْبَاعَةَ وَالتُّجَّارَ",uz:"sotuvchilar va savdogarlardan so‘rayman"}],full_uz:"Ertaga bozordan izlayman va sotuvchilar hamda savdogarlardan so‘rayman.",note:null},
{num:68,time:"00:04:32,279 --> 00:04:34,740",arabic:"لَعَلَّهُمْ يَعْرِفُونَ وَالِدَهَا",segs:[{ar:"لَعَلَّهُمْ يَعْرِفُونَ",uz:"balki ular bilishar"},{ar:"وَالِدَهَا",uz:"uning otasini"}],full_uz:"Balki ular uning otasini bilishar.",note:null},
{num:69,time:"00:04:34,740 --> 00:04:38,959",arabic:"اذْهَبْ إِلَى النُّزُلِ الَّتِي يَنْزِلُ بِهَا الْقَادِمُونَ",segs:[{ar:"اذْهَبْ إِلَى النُّزُلِ",uz:"mehmonxonalarga bor"},{ar:"الَّتِي يَنْزِلُ بِهَا الْقَادِمُونَ",uz:"kelganlar tushadigan"}],full_uz:"Kelganlar tushadigan mehmonxonalarga bor.",note:null},
{num:70,time:"00:04:38,959 --> 00:04:42,719",arabic:"وَاسْأَلْ عَنْ قَافِلَةٍ أَتَتِ الْيَوْمَ مِنْ خُرَاسَانَ",segs:[{ar:"وَاسْأَلْ عَنْ قَافِلَةٍ",uz:"karvon haqida so‘ra"},{ar:"أَتَتِ الْيَوْمَ",uz:"bugun kelgan"},{ar:"مِنْ خُرَاسَانَ",uz:"Xurosondan"}],full_uz:"Bugun Xurosondan kelgan bir karvon haqida so‘ra.",note:null},
{num:71,time:"00:04:42,719 --> 00:04:45,219",arabic:"هَذَا هُوَ الرَّأْيُ",segs:null,full_uz:"Mana shu fikr.",note:null},
{num:72,time:"00:04:47,100 --> 00:04:54,660",arabic:"يَا أُمِّي الْفَتَاةُ أَمَانَةٌ فِي عُنُقِكِ فَاحْرِصِي عَلَى أَلَّا تَنَامَ جَائِعَةً",segs:[{ar:"الْفَتَاةُ أَمَانَةٌ فِي عُنُقِكِ",uz:"qiz sening zimmandagi omonat"},{ar:"فَاحْرِصِي عَلَى أَلَّا تَنَامَ جَائِعَةً",uz:"uning och holda uxlab qolmasligiga e’tibor ber"}],full_uz:"Onajon, bu qiz sening zimmangdagi omonat. Uning och holda uxlab qolmasligiga e’tibor ber.",note:null},
{num:73,time:"00:04:54,660 --> 00:04:58,860",arabic:"إِنَّهَا تَرْفُضُ الْأَكْلَ وَلَكِنَّنِي سَأُحَاوِلُ",segs:[{ar:"إِنَّهَا تَرْفُضُ الْأَكْلَ",uz:"u ovqat yeyishni rad etyapti"},{ar:"وَلَكِنَّنِي سَأُحَاوِلُ",uz:"ammo men harakat qilaman"}],full_uz:"U ovqat yeyishni rad etyapti, ammo men harakat qilaman.",note:null},
{num:74,time:"00:04:58,860 --> 00:05:01,340",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:75,time:"00:05:01,340 --> 00:05:02,660",arabic:"وَعَلَيْكُمُ السَّلَامُ",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:76,time:"00:05:15,220 --> 00:05:25,760",arabic:"سَأَفُكُّ قَيْدَ يَدَيْكِ وَفَمِكِ لِتَأْكُلِي",segs:[{ar:"سَأَفُكُّ",uz:"yechaman"},{ar:"قَيْدَ يَدَيْكِ وَفَمِكِ",uz:"qo‘llaring va og‘zingdagi bog‘ichni"},{ar:"لِتَأْكُلِي",uz:"ovqat yeyishing uchun"}],full_uz:"Ovqat yeyishing uchun qo‘llaring va og‘zingdagi bog‘ichni yechaman.",note:null},
{num:77,time:"00:05:25,760 --> 00:05:29,560",arabic:"وَإِنْ عُدْتِ لِلصُّرَاخِ سَنَعُودُ لِلْقُيُودِ مِنْ جَدِيدٍ",segs:[{ar:"وَإِنْ عُدْتِ لِلصُّرَاخِ",uz:"agar yana qichqirsang"},{ar:"سَنَعُودُ لِلْقُيُودِ مِنْ جَدِيدٍ",uz:"yana bog‘lab qo‘yamiz"}],full_uz:"Agar yana qichqirsang, yana qaytadan bog‘lab qo‘yamiz.",note:null},
{num:78,time:"00:05:29,560 --> 00:05:31,060",arabic:"فُكَّهَا يَا حَنْظَلَةُ",segs:null,full_uz:"Uni yech, Hanzala.",note:null},
{num:79,time:"00:05:31,060 --> 00:05:35,600",arabic:"مَا الَّذِي اقْتَرَفْتُهُ حَتَّى تَفْعَلَ بِي مَا فَعَلْتَ؟",segs:[{ar:"مَا الَّذِي اقْتَرَفْتُهُ",uz:"men nima ayb qildim"},{ar:"حَتَّى تَفْعَلَ بِي",uz:"menga bunday qilishing uchun"},{ar:"مَا فَعَلْتَ",uz:"qilgan ishingni"}],full_uz:"Men nima ayb qildimki, menga bunday qilding?",note:null},
{num:80,time:"00:05:35,600 --> 00:05:36,840",arabic:"أَلَا تَخَافِينَ اللَّهَ؟",segs:null,full_uz:"Allohdan qo‘rqmaysanmi?",note:null},
{num:81,time:"00:05:36,840 --> 00:05:39,100",arabic:"دَعْكِ مِنْ هَذَا الْكَلَامِ الَّذِي لَا طَائِلَ مِنْهُ",segs:[{ar:"دَعْكِ مِنْ هَذَا الْكَلَامِ",uz:"bu gapni qo‘y"},{ar:"الَّذِي لَا طَائِلَ مِنْهُ",uz:"bundan hech qanday foyda yo‘q"}],full_uz:"Hech qanday foydasi yo‘q bu gaplarni qo‘y.",note:null},
{num:82,time:"00:05:39,100 --> 00:05:42,180",arabic:"وَكُلِي طَعَامَكِ فَالنَّهَارُ طَوِيلٌ وَالْجُوعُ قَارِسٌ",segs:[{ar:"وَكُلِي طَعَامَكِ",uz:"ovqatingni ye"},{ar:"فَالنَّهَارُ طَوِيلٌ",uz:"kun uzun"},{ar:"وَالْجُوعُ قَارِسٌ",uz:"ochlik qattiq"}],full_uz:"Ovqatingni ye, kun uzun, ochlik esa qattiq.",note:null},
{num:83,time:"00:05:42,180 --> 00:05:45,439",arabic:"لَا حَاجَةَ لِي لِطَعَامِكِ هَذَا",segs:[{ar:"لَا حَاجَةَ لِي",uz:"menga kerak emas"},{ar:"لِطَعَامِكِ هَذَا",uz:"bu ovqating"}],full_uz:"Bu ovqating menga kerak emas.",note:null},
{num:84,time:"00:05:45,439 --> 00:05:47,220",arabic:"اسْمَعِي أَيَّتُهَا الْفَتَاةُ",segs:[{ar:"اسْمَعِي",uz:"tingla"},{ar:"أَيَّتُهَا الْفَتَاةُ",uz:"ey qiz"}],full_uz:"Tingla, ey qiz.",note:null},
{num:85,time:"00:05:47,220 --> 00:05:53,879",arabic:"لَنْ تَضُرِّي إِلَّا نَفْسَكِ بِامْتِنَاعِكِ عَنِ الطَّعَامِ",segs:[{ar:"لَنْ تَضُرِّي إِلَّا نَفْسَكِ",uz:"o‘zingdan boshqa hech kimga zarar yetkazmaysan"},{ar:"بِامْتِنَاعِكِ عَنِ الطَّعَامِ",uz:"ovqatdan tiyilishing bilan"}],full_uz:"Ovqatdan tiyilib, o‘zingdan boshqa hech kimga zarar yetkazmaysan.",note:null},
{num:86,time:"00:05:53,879 --> 00:05:58,139",arabic:"مِنْ هَذِهِ الدَّارِ لَنْ تَخْرُجِي إِلَّا إِلَى دَارِ سَيِّدِكِ",segs:[{ar:"مِنْ هَذِهِ الدَّارِ",uz:"bu uydan"},{ar:"لَنْ تَخْرُجِي إِلَّا",uz:"chiqmaysan, faqat"},{ar:"إِلَى دَارِ سَيِّدِكِ",uz:"xo‘jayiningning uyiga"}],full_uz:"Bu uydan faqat xo‘jayiningning uyiga chiqasan.",note:null},
{num:87,time:"00:05:58,139 --> 00:06:01,860",arabic:"وَسَوَاءٌ عِنْدِي أَأَكَلْتِ أَمْ مُتِّ مِنَ الْجُوعِ",segs:[{ar:"وَسَوَاءٌ عِنْدِي",uz:"men uchun baribir"},{ar:"أَأَكَلْتِ أَمْ مُتِّ مِنَ الْجُوعِ",uz:"ovqat yeysanmi yoki ochlikdan o‘lasanmi"}],full_uz:"Ovqat yeysanmi yoki ochlikdan o‘lasanmi, men uchun baribir.",note:null},
{num:88,time:"00:06:01,860 --> 00:06:05,480",arabic:"وَمَا أَمْلِكُ لَكِ وَقَدْ نُزِعَ مِنْ قَلْبِكِ الرَّحْمَةُ",segs:[{ar:"وَمَا أَمْلِكُ لَكِ",uz:"men sen uchun nima ham qila olaman"},{ar:"وَقَدْ نُزِعَ مِنْ قَلْبِكِ الرَّحْمَةُ",uz:"qalbingdan rahm-shafqat sug‘urib olingan bo‘lsa"}],full_uz:"Qalbingdan rahm-shafqat sug‘urib olingan bo‘lsa, men sen uchun nima ham qila olaman?",note:null},
{num:89,time:"00:06:05,480 --> 00:06:07,180",arabic:"أَلَيْسَ فِي قَلْبِكِ ذَرَّةٌ مِنْ شَفَقَةٍ؟",segs:[{ar:"أَلَيْسَ فِي قَلْبِكِ",uz:"qalbingda yo‘qmi"},{ar:"ذَرَّةٌ مِنْ شَفَقَةٍ",uz:"bir zarra rahm-shafqat"}],full_uz:"Qalbingda bir zarra rahm-shafqat ham yo‘qmi?",note:null},
{num:90,time:"00:06:08,720 --> 00:06:11,000",arabic:"ذَرَّةٌ؟ ذَرَّاتٌ",segs:null,full_uz:"Bir zarra? Zarrachalar.",note:null},
{num:91,time:"00:06:11,000 --> 00:06:17,120",arabic:"لَوْ لَمْ تَكُنْ لَدَيَّ ذَرَّةٌ مِنْ شَفَقَةٍ لَمَا أَتَيْتُكِ بِالطَّعَامِ رَغْمَ صَلَاطَةِ لِسَانِكِ",segs:[{ar:"لَوْ لَمْ تَكُنْ لَدَيَّ ذَرَّةٌ مِنْ شَفَقَةٍ",uz:"agar menda bir zarra rahm-shafqat bo‘lmaganida"},{ar:"لَمَا أَتَيْتُكِ بِالطَّعَامِ",uz:"senga ovqat olib kelmagan bo‘lardim"},{ar:"رَغْمَ صَلَاطَةِ لِسَانِكِ",uz:"tilingning achchiqligiga qaramay"}],full_uz:"Agar menda bir zarra rahm-shafqat bo‘lmaganida, tilingning achchiqligiga qaramay senga ovqat olib kelmagan bo‘lardim.",note:null},
{num:92,time:"00:06:17,120 --> 00:06:23,120",arabic:"الَّذِي سَأَحْرِصُ عَلَى تَرْوِيضِهِ لِيُصْبِحَ لَائِقًا بِجَارِيَةٍ مُطِيعَةٍ وَجَمِيلَةٍ",segs:[{ar:"الَّذِي سَأَحْرِصُ عَلَى تَرْوِيضِهِ",uz:"uni tarbiyalashga harakat qilaman"},{ar:"لِيُصْبِحَ لَائِقًا",uz:"munosib bo‘lishi uchun"},{ar:"بِجَارِيَةٍ مُطِيعَةٍ وَجَمِيلَةٍ",uz:"itoatkor va chiroyli cho‘riga"}],full_uz:"Uni itoatkor va chiroyli cho‘riga munosib bo‘lishi uchun tarbiyalashga harakat qilaman.",note:null},
{num:93,time:"00:06:23,120 --> 00:06:26,000",arabic:"أَنَا لَسْتُ جَارِيَةً أَيَّتُهَا الْمَرْأَةُ السَّمِجَةُ",segs:[{ar:"أَنَا لَسْتُ جَارِيَةً",uz:"men cho‘ri emasman"},{ar:"أَيَّتُهَا الْمَرْأَةُ السَّمِجَةُ",uz:"ey befahm ayol"}],full_uz:"Men cho‘ri emasman, ey befahm ayol.",note:null},
{num:94,time:"00:06:26,000 --> 00:06:32,139",arabic:"أَنَا فَتَاةٌ حُرَّةٌ ابْنَةُ تَاجِرٍ حُرٍّ شَرِيفٍ وَسَأَبْقَى حُرَّةً حَتَّى آخِرِ يَوْمٍ فِي عُمْرِي",segs:[{ar:"أَنَا فَتَاةٌ حُرَّةٌ",uz:"men erkin qizman"},{ar:"ابْنَةُ تَاجِرٍ حُرٍّ شَرِيفٍ",uz:"ozod va sharafli savdogarning qiziman"},{ar:"وَسَأَبْقَى حُرَّةً",uz:"va erkinligimcha qolaman"},{ar:"حَتَّى آخِرِ يَوْمٍ فِي عُمْرِي",uz:"umrimning oxirgi kunigacha"}],full_uz:"Men erkin qizman, ozod va sharafli savdogarning qiziman va umrimning oxirgi kunigacha erkin bo‘lib qolaman.",note:null},
{num:95,time:"00:06:32,139 --> 00:06:36,500",arabic:"زَمَنُ الْحُرِّيَّةِ",segs:null,full_uz:"Ozodlik zamoni.",note:null},
{num:96,time:"00:06:36,500 --> 00:06:44,500",arabic:"وَاللَّهِ مِنَ الْأَنْفِ صَاعِدًا أَنْتِ جَارِيَةٌ زُمْرُدَةُ عَلَيْكِ أَنْ تُقَنِّعِي نَفْسَكِ بِذَلِكَ",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"مِنَ الْأَنْفِ صَاعِدًا",uz:"burundan tepaga qarab"},{ar:"أَنْتِ جَارِيَةٌ يَا زُمْرُدَةُ",uz:"sen cho‘risan, Zumruda"},{ar:"عَلَيْكِ أَنْ تُقَنِّعِي نَفْسَكِ بِذَلِكَ",uz:"o‘zingni bunga ishontirishing kerak"}],full_uz:"Allohga qasam, Zumruda, sen cho‘risan. O‘zingni bunga ishontirishing kerak.",note:null},
{num:97,time:"00:06:44,500 --> 00:07:02,500",arabic:"هَلْ سَمِعْتَ عَنْ فَتَاتَيْنِ ضَائِعَتَيْنِ يَا أَخِي؟",segs:[{ar:"هَلْ سَمِعْتَ عَنْ فَتَاتَيْنِ ضَائِعَتَيْنِ",uz:"yo‘qolgan ikki qiz haqida eshitdingmi"},{ar:"يَا أَخِي",uz:"ey birodar"}],full_uz:"Yo‘qolgan ikki qiz haqida eshitdingmi, birodar?",note:null},
{num:98,time:"00:07:02,500 --> 00:07:06,500",arabic:"يَا أَبَا فَوْزٍ أَبَا فَوْزٍ أَيْنَ أَنْتَ يَا رَجُلُ؟",segs:[{ar:"يَا أَبَا فَوْزٍ أَبَا فَوْزٍ",uz:"Ey Abu Favz, Abu Favz"},{ar:"أَيْنَ أَنْتَ",uz:"qayerdasan"},{ar:"يَا رَجُلُ",uz:"ey odam"}],full_uz:"Ey Abu Favz, Abu Favz, qayerdasan, ey odam?",note:null},
{num:99,time:"00:07:06,500 --> 00:07:07,899",arabic:"لَقَدْ تَعِبْتُ وَأَنَا أَبْحَثُ عَنْكَ",segs:[{ar:"لَقَدْ تَعِبْتُ",uz:"juda charchadim"},{ar:"وَأَنَا أَبْحَثُ عَنْكَ",uz:"seni qidirib"}],full_uz:"Seni qidirib juda charchadim.",note:null},
{num:100,time:"00:07:07,899 --> 00:07:09,459",arabic:"يَجِبُ أَنْ تَسِيرَ الْقَافِلَةُ",segs:null,full_uz:"Karvon yo‘lga chiqishi kerak.",note:null},
{num:101,time:"00:07:09,459 --> 00:07:10,860",arabic:"لَقَدْ تَأَخَّرْنَا كَثِيرًا",segs:null,full_uz:"Juda kechikdik.",note:null},
{num:102,time:"00:07:10,860 --> 00:07:11,939",arabic:"يَا أَبَا رُسْتُمٍ",segs:null,full_uz:"Ey Abu Rustam.",note:null},
{num:103,time:"00:07:11,939 --> 00:07:13,500",arabic:"أَلَمْ أَطْلُبْ إِلَيْكَ بِالْأَمْسِ",segs:null,full_uz:"Kecha sendan so‘ramadimmi?",note:null},
{num:104,time:"00:07:13,500 --> 00:07:15,079",arabic:"الِانْتِظَارَ يَوْمًا آخَرَ",segs:null,full_uz:"Yana bir kun kutishni.",note:null},
{num:105,time:"00:07:15,079 --> 00:07:17,279",arabic:"أُقْسِمُ أَنَّنِي حَاوَلْتُ",segs:[{ar:"أُقْسِمُ",uz:"qasam ichaman"},{ar:"أَنَّنِي حَاوَلْتُ",uz:"men harakat qilganimga"}],full_uz:"Qasam ichaman, harakat qildim.",note:null},
{num:106,time:"00:07:17,279 --> 00:07:19,199",arabic:"لَكِنَّ الْقَوْمَ مُصِرُّونَ عَلَى الذَّهَابِ",segs:[{ar:"لَكِنَّ الْقَوْمَ",uz:"ammo odamlar"},{ar:"مُصِرُّونَ عَلَى الذَّهَابِ",uz:"ketishga qat'iy turib olishgan"}],full_uz:"Ammo odamlar ketishga qat'iy turib olishgan.",note:null},
{num:107,time:"00:07:19,199 --> 00:07:20,420",arabic:"إِنْ شِئْتَ رَافَقْنَا",segs:null,full_uz:"Xohlasang, biz bilan yur.",note:null},
{num:108,time:"00:07:20,420 --> 00:07:22,220",arabic:"وَإِلَّا فَابْقَ حَتَّى تَنْتَهِيَ مِنْ عَمَلِكَ",segs:[{ar:"وَإِلَّا فَابْقَ",uz:"aks holda qol"},{ar:"حَتَّى تَنْتَهِيَ مِنْ عَمَلِكَ",uz:"ishingizni tugatguningizcha"}],full_uz:"Aks holda ishingni tugatguningcha qol.",note:null},
{num:109,time:"00:07:22,220 --> 00:07:24,980",arabic:"فَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o‘zga kuch va qudrat yo‘q.",note:null},
{num:110,time:"00:07:24,980 --> 00:07:28,240",arabic:"الرَّحْمَةَ يَا مَوْلَايَ",segs:null,full_uz:"Rahm qiling, ey hazratim.",note:null},
{num:111,time:"00:07:28,240 --> 00:07:33,680",arabic:"قُلْ مَنْ كَانَ مَعَكَ فِي هَذِهِ الْمُؤَامَرَةِ الْخَبِيثَةِ وَانْجُ بِنَفْسِكَ مِنْ مَوْتٍ مُحَقَّقٍ",segs:[{ar:"قُلْ مَنْ كَانَ مَعَكَ",uz:"sening yoningda kim bo‘lganini ayt"},{ar:"فِي هَذِهِ الْمُؤَامَرَةِ الْخَبِيثَةِ",uz:"bu qabih fitnada"},{ar:"وَانْجُ بِنَفْسِكَ",uz:"o‘zingni qutqar"},{ar:"مِنْ مَوْتٍ مُحَقَّقٍ",uz:"muqarrar o‘limdan"}],full_uz:"Bu qabih fitnada sen bilan kim bo‘lganini ayt va o‘zingni muqarrar o‘limdan qutqar.",note:null},
{num:112,time:"00:07:33,680 --> 00:07:35,920",arabic:"لَا أَعْرِفُ أَحَدًا",segs:null,full_uz:"Hech kimni tanimayman.",note:null},
{num:113,time:"00:07:35,920 --> 00:07:41,420",arabic:"أَنْتَ هَالِكٌ إِنْ لَمْ تَتَكَلَّمْ يَا ابْنَ الْأَيْهَمِ",segs:[{ar:"أَنْتَ هَالِكٌ",uz:"sen halok bo'lasan"},{ar:"إِنْ لَمْ تَتَكَلَّمْ",uz:"agar gapirmasang"},{ar:"يَا ابْنَ الْأَيْهَمِ",uz:"ey Ibn al-Ayham"}],full_uz:"Gapirmasang, halok bo'lasan, ey Ibn al-Ayham.",note:null},
{num:114,time:"00:07:41,420 --> 00:07:44,920",arabic:"وَأُقْسِمُ إِنَّنِي لَنْ أَدَعَهُمْ يَكُفُّونَ عَنْ ضَرْبِكَ",segs:[{ar:"وَأُقْسِمُ",uz:"qasam ichaman"},{ar:"إِنَّنِي لَنْ أَدَعَهُمْ",uz:"ularga yo'l qo'ymayman"},{ar:"يَكُفُّونَ عَنْ ضَرْبِكَ",uz:"seni urishni to'xtatishlariga"}],full_uz:"Qasam ichaman, seni urishni to'xtatishlariga yo'l qo'ymayman.",note:null},
{num:115,time:"00:07:44,920 --> 00:07:51,160",arabic:"حَتَّى تُقِرَّ بِأَسْمَاءِ مَنْ مَعَكَ مِنَ الْخُونَةِ الْمَارِقِينَ",segs:[{ar:"حَتَّى تُقِرَّ",uz:"to tan olguningcha"},{ar:"بِأَسْمَاءِ مَنْ مَعَكَ",uz:"sen bilan bo'lganlarning ismlarini"},{ar:"مِنَ الْخُونَةِ الْمَارِقِينَ",uz:"xoin va isyonchilardan"}],full_uz:"Sen bilan bo'lgan xoin va isyonchilarning ismlarini tan olguningcha.",note:null},
{num:116,time:"00:07:51,160 --> 00:07:54,780",arabic:"قُلْتُ لَكُمْ لَا أَعْرِفُ أَحَدًا",segs:[{ar:"قُلْتُ لَكُمْ",uz:"sizlarga aytdim"},{ar:"لَا أَعْرِفُ أَحَدًا",uz:"hech kimni tanimayman"}],full_uz:"Sizlarga aytdim-ku, hech kimni tanimayman.",note:null},
{num:117,time:"00:07:54,780 --> 00:07:59,780",arabic:"سُكُوتُكَ يُعَجِّلُ أَجَلَكَ يَا ابْنَ الْأَيْهَمِ",segs:[{ar:"سُكُوتُكَ يُعَجِّلُ أَجَلَكَ",uz:"sukut qilishing umringni tez tugatadi"},{ar:"يَا ابْنَ الْأَيْهَمِ",uz:"ey Ibn al-Ayham"}],full_uz:"Sukut qilishing umringning tez tugashiga sabab bo'ladi, ey Ibn al-Ayham.",note:null},
{num:118,time:"00:07:59,780 --> 00:08:02,340",arabic:"خُذُوهُ",segs:null,full_uz:"Uni olib keting.",note:null},
{num:119,time:"00:08:02,339 --> 00:08:03,179",arabic:"خُذُوهُ وَلَا تَتْرُكُوهُ قَبْلَ أَنْ يَعْتَرِفَ بِأَسْمَاءِ كُلِّ مَنْ مَعَهُ مِنَ الْخَائِنِينَ",segs:[{ar:"خُذُوهُ وَلَا تَتْرُكُوهُ",uz:"uni olib keting va tashlab qo‘ymang"},{ar:"قَبْلَ أَنْ يَعْتَرِفَ",uz:"tan olmaguncha"},{ar:"بِأَسْمَاءِ كُلِّ مَنْ مَعَهُ",uz:"u bilan bo‘lganlarning barchasi ismlarini"},{ar:"مِنَ الْخَائِنِينَ",uz:"xoinlardan"}],full_uz:"Uni olib keting va u bilan bo‘lgan barcha xoinlarning ismlarini tan olmaguncha qo‘yib yubormang.",note:null},
{num:120,time:"00:08:15,939 --> 00:08:18,479",arabic:"الرَّحْمَةَ يَا مَوْلَايَ",segs:null,full_uz:"Rahm qiling, ey hazratim.",note:null},
{num:121,time:"00:08:25,479 --> 00:08:27,539",arabic:"لَا تَقْلَقْ يَا مَوْلَايَ",segs:[{ar:"لَا تَقْلَقْ",uz:"xavotir olmang"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"}],full_uz:"Xavotir olmang, ey hazratim.",note:null},
{num:122,time:"00:08:27,539 --> 00:08:31,620",arabic:"سَيَعْتَرِفُ هَذَا الْخَائِنُ عَاجِلًا أَمْ آجِلًا",segs:[{ar:"سَيَعْتَرِفُ هَذَا الْخَائِنُ",uz:"bu xoin tan oladi"},{ar:"عَاجِلًا أَمْ آجِلًا",uz:"erta yoki kech"}],full_uz:"Bu xoin erta yoki kech baribir tan oladi.",note:null},
{num:123,time:"00:08:31,620 --> 00:08:33,440",arabic:"لَا لَا لَا لَا يَا يَحْيَى",segs:[{ar:"لَا لَا لَا لَا",uz:"yo'q, yo'q, yo'q, yo'q"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Yo'q, yo'q, yo'q, yo'q, ey Yahyo.",note:null},
{num:124,time:"00:08:33,440 --> 00:08:37,039",arabic:"مِنَ الْأَفْضَلِ أَنْ يَعْتَرِفَ عَاجِلًا",segs:[{ar:"مِنَ الْأَفْضَلِ",uz:"yaxshisi"},{ar:"أَنْ يَعْتَرِفَ عَاجِلًا",uz:"tezroq tan olsin"}],full_uz:"Yaxshisi, u tezroq tan olsin.",note:null},
{num:125,time:"00:08:37,039 --> 00:08:39,419",arabic:"مَا أَدْرَاكَ",segs:null,full_uz:"Qayerdan bilasan?",note:null},
{num:126,time:"00:08:39,419 --> 00:08:44,560",arabic:"قَدْ يَكُونُ وَرَاءَ هَذِهِ الْمُؤَامَرَةِ دُهَاةٌ كُثُرٌ",segs:[{ar:"قَدْ يَكُونُ وَرَاءَ هَذِهِ الْمُؤَامَرَةِ",uz:"bu fitnaning ortida bo'lishi mumkin"},{ar:"دُهَاةٌ كُثُرٌ",uz:"ko'plab ayyor kishilar"}],full_uz:"Bu fitnaning ortida ko'plab ayyor kishilar bo'lishi mumkin.",note:null},
{num:127,time:"00:08:44,560 --> 00:08:48,039",arabic:"وَقَدْ يَكُونُ بَعْضُهُمْ بَيْنَ ظَهْرَانَيْنَا",segs:[{ar:"وَقَدْ يَكُونُ بَعْضُهُمْ",uz:"ularning ba'zilari bo'lishi mumkin"},{ar:"بَيْنَ ظَهْرَانَيْنَا",uz:"bizning oramizda"}],full_uz:"Ularning ba'zilari bizning oramizda bo'lishi mumkin.",note:null},
{num:128,time:"00:08:48,039 --> 00:08:53,539",arabic:"ثَلَاثَةُ أَيَّامٍ يَا يَحْيَى",segs:null,full_uz:"Uch kun, ey Yahyo.",note:null},
{num:129,time:"00:08:53,539 --> 00:08:59,740",arabic:"أَمَامَكُمْ ثَلَاثَةُ أَيَّامٍ حَتَّى تُحْضِرُوا الْمُتَوَرِّطِينَ مَعَهُ",segs:[{ar:"أَمَامَكُمْ ثَلَاثَةُ أَيَّامٍ",uz:"sizlarda uch kun bor"},{ar:"حَتَّى تُحْضِرُوا الْمُتَوَرِّطِينَ مَعَهُ",uz:"u bilan aloqadorlarni olib kelguningizcha"}],full_uz:"U bilan aloqadorlarni olib kelish uchun sizlarda uch kun bor.",note:null},
{num:130,time:"00:08:59,740 --> 00:09:01,000",arabic:"وَإِلَّا فَأَقْسِمُ",segs:null,full_uz:"Aks holda, qasam ichaman.",note:null},
{num:131,time:"00:09:01,000 --> 00:09:04,399",arabic:"إِنِّي سَأَضَعُ الْجَمِيعَ مَعَهُ",segs:[{ar:"إِنِّي سَأَضَعُ",uz:"men joylayman"},{ar:"الْجَمِيعَ مَعَهُ",uz:"hammani u bilan birga"}],full_uz:"Hammani u bilan birga javobgarlikka tortaman.",note:null},
{num:132,time:"00:09:04,399 --> 00:09:06,000",arabic:"أَمْرُ مَوْلَايَ",segs:null,full_uz:"Amrlaringiz bajariladi, hazratim.",note:null},
{num:133,time:"00:09:31,000 --> 00:09:36,000",arabic:"إِلَى مَتَى؟",segs:null,full_uz:"Qachongacha?",note:null},
{num:134,time:"00:09:36,000 --> 00:09:41,000",arabic:"إِلَى مَتَى سَتَصْمُدُ يَدُ الْأَيَّامِ؟",segs:[{ar:"إِلَى مَتَى",uz:"qachongacha"},{ar:"سَتَصْمُدُ يَدُ الْأَيَّامِ",uz:"zamon qo'li bardosh beradi"}],full_uz:"Zamon qo'li qachongacha bardosh beradi?",note:null},
{num:135,time:"00:10:31,000 --> 00:10:43,279",arabic:"ابْنُ أَخِي الْآنَ أَمَانَةٌ فِي عُنُقِكَ يَا زَيْدُ",segs:[{ar:"ابْنُ أَخِي الْآنَ أَمَانَةٌ فِي عُنُقِكَ",uz:"endi akamning o'g'li sening zimmangdagi omonat"},{ar:"يَا زَيْدُ",uz:"ey Zayd"}],full_uz:"Endi akamning o'g'li sening zimmangdagi omonat, ey Zayd.",note:null},
{num:136,time:"00:10:43,279 --> 00:10:46,519",arabic:"بِإِذْنِ اللَّهِ سَأَكُونُ لَهُ سَنَدًا وَعَوْنًا",segs:[{ar:"بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan"},{ar:"سَأَكُونُ لَهُ سَنَدًا وَعَوْنًا",uz:"unga tayanch va yordamchi bo‘laman"}],full_uz:"Allohning izni bilan unga tayanch va yordamchi bo‘laman.",note:null},
{num:137,time:"00:10:46,519 --> 00:10:51,379",arabic:"بَارَكَ اللَّهُ فِيكَ أَتَمَنَّى عَلَيْكَ أَنْ تَكُونَ لَهُ عَوْنًا فِي التَّوْفِيقِ بَيْنَ عِلْمِهِ وَعَمَلِهِ",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh seni barakali qilsin"},{ar:"أَتَمَنَّى عَلَيْكَ",uz:"sendan istayman"},{ar:"أَنْ تَكُونَ لَهُ عَوْنًا",uz:"unga yordamchi bo‘lishingni"},{ar:"فِي التَّوْفِيقِ بَيْنَ عِلْمِهِ وَعَمَلِهِ",uz:"uning ilmi bilan ishini uyg‘unlashtirishda"}],full_uz:"Alloh seni barakali qilsin. Sendan uning ilm bilan ishini uyg‘unlashtirishida unga yordamchi bo‘lishingni istayman.",note:null},
{num:138,time:"00:10:51,379 --> 00:10:53,840",arabic:"لَا عَلَيْكَ يَا أَبَا حَنْبَلٍ لَا عَلَيْكَ",segs:[{ar:"لَا عَلَيْكَ",uz:"hechqisi yo'q"},{ar:"يَا أَبَا حَنْبَلٍ",uz:"ey Abu Hanbal"},{ar:"لَا عَلَيْكَ",uz:"hechqisi yo'q"}],full_uz:"Hechqisi yo'q, ey Abu Hanbal, hechqisi yo'q.",note:null},
{num:139,time:"00:10:53,840 --> 00:10:55,899",arabic:"بَارَكَ اللَّهُ فِيكَ السَّلَامُ عَلَيْكُمْ",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh seni barakali qilsin"},{ar:"السَّلَامُ عَلَيْكُمْ",uz:"assalomu alaykum"}],full_uz:"Alloh seni barakali qilsin. Assalomu alaykum.",note:null},
{num:140,time:"00:10:55,899 --> 00:10:58,519",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"va alaykum assalom"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"Allohning rahmati va barakalari bo‘lsin"}],full_uz:"Va alaykum assalom va Allohning rahmati hamda barakalari bo‘lsin.",note:null},
{num:141,time:"00:11:31,000 --> 00:11:41,580",arabic:"أَحْمَدُ أَلَنْ تَبْدَأَ الْعَمَلَ؟",segs:[{ar:"أَحْمَدُ",uz:"Ahmad"},{ar:"أَلَنْ تَبْدَأَ الْعَمَلَ",uz:"ishni boshlamaysanmi"}],full_uz:"Ahmad, ishni boshlamaysanmi?",note:null},
{num:142,time:"00:11:41,580 --> 00:11:43,200",arabic:"بِكُلِّ تَأْكِيدٍ بِعَوْنِ اللَّهِ",segs:[{ar:"بِكُلِّ تَأْكِيدٍ",uz:"albatta"},{ar:"بِعَوْنِ اللَّهِ",uz:"Allohning yordami bilan"}],full_uz:"Albatta, Allohning yordami bilan.",note:null},
{num:143,time:"00:12:31,000 --> 00:12:35,480",arabic:"أَنَا عَامِرُ الْإِسْكَافِيُّ صَاحِبُ الدُّكَّانِ مَرْقَعُ النِّعَالِ",segs:[{ar:"أَنَا عَامِرُ الْإِسْكَافِيُّ",uz:"men poyabzalchi Amiraman"},{ar:"صَاحِبُ الدُّكَّانِ",uz:"do‘kon egasiman"},{ar:"مَرْقَعُ النِّعَالِ",uz:"poyabzal yamovchi"}],full_uz:"Men poyabzalchi Amiraman, do‘kon egasiman va poyabzal yamayman.",note:null},
{num:144,time:"00:12:35,480 --> 00:12:37,139",arabic:"مُبَارَكٌ يَا عَامِرُ",segs:null,full_uz:"Muborak bo‘lsin, Amir.",note:null},
{num:145,time:"00:12:37,139 --> 00:12:39,220",arabic:"بَارَكَ اللَّهُ فِيكَ بَارَكَ اللَّهُ فِيكُمْ",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh seni barakali qilsin"},{ar:"بَارَكَ اللَّهُ فِيكُمْ",uz:"Alloh sizlarni barakali qilsin"}],full_uz:"Alloh seni barakali qilsin. Alloh sizlarni barakali qilsin.",note:null},
{num:146,time:"00:12:39,220 --> 00:12:41,419",arabic:"جَعَلَهَا اللَّهُ بَابَ رِزْقٍ وَنَعِيمٍ",segs:[{ar:"جَعَلَهَا اللَّهُ",uz:"Alloh uni qilsin"},{ar:"بَابَ رِزْقٍ وَنَعِيمٍ",uz:"rizq va farovonlik eshigi"}],full_uz:"Alloh uni rizq va farovonlik eshigi qilsin.",note:null},
{num:147,time:"00:12:41,419 --> 00:12:43,720",arabic:"إِنْ شَاءَ اللَّهُ تَوَكَّلْنَا عَلَى اللَّهِ",segs:[{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"},{ar:"تَوَكَّلْنَا عَلَى اللَّهِ",uz:"Allohga tavakkal qildik"}],full_uz:"Alloh xohlasa, Allohga tavakkal qildik.",note:null},
{num:148,time:"00:12:43,720 --> 00:12:49,940",arabic:"وَنِعْمَ الِاتِّكَالُ أَوَّلُ نَعْلٍ تَصْنَعُهُ مِنْ جِلْدِ الْبَعِيرِ تُهْدِيهِ لِابْنِ الْوَزِيرِ",segs:[{ar:"وَنِعْمَ الِاتِّكَالُ",uz:"qanday yaxshi tavakkal"},{ar:"أَوَّلُ نَعْلٍ تَصْنَعُهُ",uz:"yasaydigan birinchi poyabzalingni"},{ar:"مِنْ جِلْدِ الْبَعِيرِ",uz:"tuya terisidan"},{ar:"تُهْدِيهِ لِابْنِ الْوَزِيرِ",uz:"vazirning o‘g‘liga sovg‘a qilasan"}],full_uz:"Qanday yaxshi tavakkal. Tuya terisidan yasaydigan birinchi poyabzalingni vazirning o‘g‘liga sovg‘a qilasan.",note:null},
{num:149,time:"00:12:49,940 --> 00:12:57,000",arabic:"وَيْحَكَ يَا أَبَا سَرْعَانَ اخْفِضْ صَوْتَكَ فَعُيُونُ أَمِيرِ الْمُؤْمِنِينَ خَلْفَ كُلِّ زَاوِيَةٍ فِي السُّوقِ",segs:[{ar:"وَيْحَكَ يَا أَبَا سَرْعَانَ",uz:"ey Abu Sar’on, holingga voy"},{ar:"اخْفِضْ صَوْتَكَ",uz:"ovozingni pasaytir"},{ar:"فَعُيُونُ أَمِيرِ الْمُؤْمِنِينَ",uz:"chunki mo‘minlar amirining josuslari"},{ar:"خَلْفَ كُلِّ زَاوِيَةٍ فِي السُّوقِ",uz:"bozorning har bir burchagida"}],full_uz:"Ey Abu Sar’on, holingga voy, ovozingni pasaytir. Chunki mo‘minlar amirining josuslari bozorning har bir burchagida.",note:null},
{num:150,time:"00:13:01,000 --> 00:13:07,919",arabic:"لِمَاذَا كُلُّ هَذَا الْعُبُوسِ الَّذِي لَا يُفَارِقُ وَجْهَكَ نَكِدٌ؟",segs:[{ar:"لِمَاذَا كُلُّ هَذَا الْعُبُوسِ",uz:"nega bunchalik qovog‘ing soliq"},{ar:"الَّذِي لَا يُفَارِقُ وَجْهَكَ",uz:"yuzingdan ketmayapti"},{ar:"نَكِدٌ؟",uz:"g‘amginmisan"}],full_uz:"Nega yuzingdan ketmaydigan bu qadar qovog‘ing soliq? G‘amginmisan?",note:null},
{num:151,time:"00:13:07,919 --> 00:13:10,799",arabic:"نَكِدٌ؟ لَا شَيْءَ لَا شَيْءَ",segs:[{ar:"نَكِدٌ؟",uz:"g‘amginmi?"},{ar:"لَا شَيْءَ لَا شَيْءَ",uz:"hech narsa yo‘q"}],full_uz:"G‘amginmi? Hech narsa yo‘q, hech narsa.",note:null},
{num:152,time:"00:13:10,799 --> 00:13:13,200",arabic:"لَا شَيْءَ؟ حَمِدَ اللَّهُ",segs:[{ar:"لَا شَيْءَ؟",uz:"hech narsa yo‘qmi?"},{ar:"حَمِدَ اللَّهُ",uz:"Xudoga shukur"}],full_uz:"Hech narsa yo‘qmi? Xudoga shukur.",note:null},
{num:153,time:"00:13:13,200 --> 00:13:16,399",arabic:"أَعْرِفُكَ كَمَا أَعْرِفُ رَاحَةَ يَدِي",segs:[{ar:"أَعْرِفُكَ",uz:"seni bilaman"},{ar:"كَمَا أَعْرِفُ رَاحَةَ يَدِي",uz:"kaftimni bilgandek"}],full_uz:"Seni kaftimni bilgandek yaxshi bilaman.",note:null},
{num:154,time:"00:13:16,399 --> 00:13:18,159",arabic:"قُلْ مَا عِنْدَكَ",segs:null,full_uz:"Ayt, nima gap.",note:null},
{num:155,time:"00:13:18,159 --> 00:13:23,500",arabic:"بِصَرَاحَةٍ أَخْشَى أَنْ يَنْكَشِفَ أَمْرُنَا فَيَزْجُبُنَا فِي سِجْنِ بَغْدَادَ",segs:[{ar:"بِصَرَاحَةٍ",uz:"rostini aytsam"},{ar:"أَخْشَى أَنْ يَنْكَشِفَ أَمْرُنَا",uz:"ishimiz fosh bo‘lishidan qo‘rqaman"},{ar:"فَيَزْجُبُنَا فِي سِجْنِ بَغْدَادَ",uz:"shunda bizni Bag‘dod qamoqxonasiga tashlashadi"}],full_uz:"Rostini aytsam, ishimiz fosh bo‘lib, bizni Bag‘dod qamoqxonasiga tashlashlaridan qo‘rqaman.",note:null},
{num:156,time:"00:13:23,500 --> 00:13:25,860",arabic:"بَدَلَ أَنْ نَكْسِبَ الْمَالَ مِنْ بَيْعِ هَذِهِ الْفَتَاةِ",segs:[{ar:"بَدَلَ أَنْ نَكْسِبَ الْمَالَ",uz:"pul topish o‘rniga"},{ar:"مِنْ بَيْعِ هَذِهِ الْفَتَاةِ",uz:"bu qizni sotishdan"}],full_uz:"Bu qizni sotib pul topish o‘rniga.",note:null},
{num:157,time:"00:13:25,860 --> 00:13:32,779",arabic:"يَا رَجُلُ يَا ذَكِيُّ",segs:null,full_uz:"Ey odam, ey aqlli odam.",note:null},
{num:158,time:"00:13:32,779 --> 00:13:37,180",arabic:"أَلَيْسَ لَدَيْنَا صَكٌّ يُثْبِتُ مِلْكِيَّتَنَا لَهَا عَلَى أَنَّهَا جَارِيَةٌ؟",segs:[{ar:"أَلَيْسَ لَدَيْنَا صَكٌّ",uz:"bizda hujjat yo‘qmi"},{ar:"يُثْبِتُ مِلْكِيَّتَنَا لَهَا",uz:"unga egaligimizni isbotlaydigan"},{ar:"عَلَى أَنَّهَا جَارِيَةٌ",uz:"uning cho‘ri ekanini"}],full_uz:"Uning cho‘ri ekanini va unga egaligimizni isbotlaydigan hujjat bizda yo‘qmi?",note:null},
{num:159,time:"00:13:37,180 --> 00:13:38,680",arabic:"أَمْ أَنَّكَ نَسِيتَ؟",segs:null,full_uz:"Yoki unutdingmi?",note:null},
{num:160,time:"00:13:38,680 --> 00:13:39,800",arabic:"لَمْ أَنْسَ",segs:null,full_uz:"Unutmadim.",note:null},
{num:161,time:"00:13:39,800 --> 00:13:43,060",arabic:"وَلَكِنَّ الصَّكَّ الَّذِي وَجَدْنَاهُ فِي السُّوقِ هُوَ لِفَتَاةٍ ثَانِيَةٍ",segs:[{ar:"وَلَكِنَّ الصَّكَّ الَّذِي وَجَدْنَاهُ فِي السُّوقِ",uz:"ammo bozordan topgan hujjatimiz"},{ar:"هُوَ لِفَتَاةٍ ثَانِيَةٍ",uz:"boshqa bir qizniki"}],full_uz:"Ammo bozordan topgan hujjatimiz boshqa bir qizniki.",note:null},
{num:162,time:"00:13:43,060 --> 00:13:44,720",arabic:"وَاسْمُهَا غَيْرُ اسْمِ هَذِهِ الْفَتَاةِ",segs:[{ar:"وَاسْمُهَا",uz:"uning ismi"},{ar:"غَيْرُ اسْمِ هَذِهِ الْفَتَاةِ",uz:"bu qizning ismidan boshqa"}],full_uz:"Uning ismi bu qizning ismidan boshqa.",note:null},
{num:163,time:"00:13:44,720 --> 00:13:49,080",arabic:"ثُمَّ أَخْشَى أَنَّهَا سَتُخْبِرُ مَنْ يُرِيدُ شِرَاءَهَا غَدًا الْحَقِيقَةَ كَامِلَةً",segs:[{ar:"ثُمَّ أَخْشَى",uz:"yana qo‘rqamanki"},{ar:"أَنَّهَا سَتُخْبِرُ مَنْ يُرِيدُ شِرَاءَهَا غَدًا",uz:"ertaga uni sotib olmoqchi bo‘lgan kishiga aytadi"},{ar:"الْحَقِيقَةَ كَامِلَةً",uz:"butun haqiqatni"}],full_uz:"Yana ertaga uni sotib olmoqchi bo‘lgan kishiga butun haqiqatni aytib qo‘yishidan qo‘rqaman.",note:null},
{num:164,time:"00:13:49,080 --> 00:13:53,180",arabic:"وَمَنْ الَّذِي سَيُصَدِّقُ جَارِيَةً وَيُكَذِّبُ مَالِكًا؟",segs:[{ar:"وَمَنْ الَّذِي سَيُصَدِّقُ جَارِيَةً",uz:"kim cho‘riga ishonadi"},{ar:"وَيُكَذِّبُ مَالِكًا",uz:"va egasini yolg‘onchiga chiqaradi"}],full_uz:"Kim cho‘riga ishonib, egasini yolg‘onchiga chiqaradi?",note:null},
{num:165,time:"00:13:53,180 --> 00:13:57,659",arabic:"الصَّكُّ الَّذِي مَعَنَا هُوَ حَقِيقَتُهَا الَّتِي لَنْ يَسْتَطِيعَ أَحَدٌ إِنْكَارَهَا",segs:[{ar:"الصَّكُّ الَّذِي مَعَنَا",uz:"bizdagi hujjat"},{ar:"هُوَ حَقِيقَتُهَا",uz:"uning haqiqatini bildiradi"},{ar:"الَّتِي لَنْ يَسْتَطِيعَ أَحَدٌ إِنْكَارَهَا",uz:"uni hech kim inkor eta olmaydi"}],full_uz:"Bizdagi hujjat uning haqiqatini tasdiqlaydi va uni hech kim inkor eta olmaydi.",note:null},
{num:166,time:"00:13:57,659 --> 00:14:00,759",arabic:"لَا تَخْشَ شَيْئًا وَدَعْ عَنْكَ الْخَوْفَ",segs:[{ar:"لَا تَخْشَ شَيْئًا",uz:"hech narsadan qo‘rqma"},{ar:"وَدَعْ عَنْكَ الْخَوْفَ",uz:"qo‘rquvni qo‘y"}],full_uz:"Hech narsadan qo‘rqma, qo‘rquvni tashla.",note:null},
{num:167,time:"00:14:23,179 --> 00:14:45,399",arabic:"عُذْرًا يَا سَيِّدِي لَقَدْ تَأَخَّرْتُ عَنْ حَلْقَةِ شَيْخِي",segs:[{ar:"عُذْرًا يَا سَيِّدِي",uz:"kechirasiz, janobim"},{ar:"لَقَدْ تَأَخَّرْتُ عَنْ حَلْقَةِ شَيْخِي",uz:"ustozimning darsiga kechikdim"}],full_uz:"Kechirasiz, janobim. Ustozimning darsiga kechikdim.",note:null},
{num:168,time:"00:14:45,399 --> 00:14:52,539",arabic:"أَعْرِفُ وَأَعْرِفُ أَنَّنِي قَدْ قَطَعْتُ عَهْدًا مَعَ عَمِّكَ أَنْ أَضَعَ ذَلِكَ نُصْبَ عَيْنِي وَلَكِنْ",segs:[{ar:"أَعْرِفُ وَأَعْرِفُ",uz:"bilaman, bilaman"},{ar:"أَنَّنِي قَدْ قَطَعْتُ عَهْدًا مَعَ عَمِّكَ",uz:"amakiving bilan ahd qilganimni"},{ar:"أَنْ أَضَعَ ذَلِكَ نُصْبَ عَيْنِي",uz:"buni ko‘z oldimda tutishga"},{ar:"وَلَكِنْ",uz:"ammo"}],full_uz:"Bilaman, bilaman. Amaking bilan buni ko‘z oldimda tutish haqida ahd qilganman, ammo...",note:null},
{num:169,time:"00:14:52,539 --> 00:14:55,079",arabic:"الْمُؤْمِنُونَ عِنْدَ شُرُوطِهِمْ يَا سَيِّدِي",segs:[{ar:"الْمُؤْمِنُونَ عِنْدَ شُرُوطِهِمْ",uz:"mo‘minlar o‘z shartlariga rioya qiladilar"},{ar:"يَا سَيِّدِي",uz:"janobim"}],full_uz:"Mo‘minlar o‘z shartlariga rioya qiladilar, janobim.",note:null},
{num:170,time:"00:14:55,079 --> 00:14:57,379",arabic:"وَأَنَا أُنَفِّذُ مَا وَعَدْتُ يَا أَحْمَدُ",segs:[{ar:"وَأَنَا أُنَفِّذُ مَا وَعَدْتُ",uz:"men va’da qilgan narsamni bajaraman"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Men ham va’da qilgan narsamni bajaraman, Ahmad.",note:null},
{num:171,time:"00:14:57,379 --> 00:15:01,419",arabic:"وَلَكِنْ مَا إِنْ تَنْتَهِي حَلْقَةُ الدَّرْسِ حَتَّى تَعُودَ إِلَى الْعَمَلِ",segs:[{ar:"وَلَكِنْ",uz:"ammo"},{ar:"مَا إِنْ تَنْتَهِي حَلْقَةُ الدَّرْسِ",uz:"dars halqasi tugashi bilan"},{ar:"حَتَّى تَعُودَ إِلَى الْعَمَلِ",uz:"yana ishga qaytasan"}],full_uz:"Ammo dars tugashi bilan yana ishga qaytasan.",note:null},
{num:172,time:"00:15:01,419 --> 00:15:03,519",arabic:"فَلَدَيْنَا عَمَلٌ كَثِيرٌ الْيَوْمَ",segs:[{ar:"فَلَدَيْنَا عَمَلٌ كَثِيرٌ",uz:"bizda ish ko‘p"},{ar:"الْيَوْمَ",uz:"bugun"}],full_uz:"Bugun bizda ish ko‘p.",note:null},
{num:173,time:"00:15:03,519 --> 00:15:05,579",arabic:"وَأَنَا أَفِي بِوَعْدِي إِنْ شَاءَ اللَّهُ",segs:[{ar:"وَأَنَا أَفِي بِوَعْدِي",uz:"men va’damga vafo qilaman"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Men ham va’damga vafo qilaman, Alloh xohlasa.",note:null},
{num:174,time:"00:15:05,579 --> 00:15:07,179",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:175,time:"00:15:07,179 --> 00:15:09,279",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizlarga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga ham salom va Allohning rahmati.",note:null},
{num:176,time:"00:15:16,480 --> 00:15:18,799",arabic:"لَا تَيْأَسِي مِنْ رَحْمَةِ اللَّهِ يَا أَخِي",segs:[{ar:"لَا تَيْأَسِي",uz:"noumid bo'lma"},{ar:"مِنْ رَحْمَةِ اللَّهِ",uz:"Allohning rahmatidan"},{ar:"يَا أَخِي",uz:"ey birodarim"}],full_uz:"Ey birodarim, Allohning rahmatidan noumid bo'lma.",note:null},
{num:177,time:"00:15:18,799 --> 00:15:21,579",arabic:"سَنَبْحَثُ فِي بَغْدَادَ كُلِّهَا",segs:[{ar:"سَنَبْحَثُ",uz:"qidirmiz"},{ar:"فِي بَغْدَادَ كُلِّهَا",uz:"butun Bag'dod bo'ylab"}],full_uz:"Butun Bag'dod bo'ylab qidirmiz.",note:null},
{num:178,time:"00:15:21,580 --> 00:15:24,160",arabic:"بَغْدَادُ كَبِيرَةٌ جِدًّا يَا شَهْنَازُ",segs:[{ar:"بَغْدَادُ",uz:"Bag'dod"},{ar:"كَبِيرَةٌ جِدًّا",uz:"juda katta"},{ar:"يَا شَهْنَازُ",uz:"ey Shahnoz"}],full_uz:"Bag'dod juda katta, ey Shahnoz.",note:null},
{num:179,time:"00:15:24,160 --> 00:15:25,940",arabic:"وَلَكِنْ",segs:null,full_uz:"Ammo.",note:null},
{num:180,time:"00:15:25,940 --> 00:15:29,120",arabic:"لَقَدْ أَخْبَرَنَا صَاحِبُ النُّزُلِ",segs:[{ar:"لَقَدْ أَخْبَرَنَا",uz:"bizga aytdi"},{ar:"صَاحِبُ النُّزُلِ",uz:"mehmonxona egasi"}],full_uz:"Mehmonxona egasi bizga aytdi.",note:null},
{num:181,time:"00:15:29,120 --> 00:15:30,520",arabic:"أَنَّ قَافِلَةَ خُرَسَانَ",segs:null,full_uz:"Xuroson karvoni...",note:"قَافِلَةٌ — karvon."},
{num:182,time:"00:15:30,520 --> 00:15:32,000",arabic:"قَدْ غَادَرَتْ بَغْدَادَ",segs:[{ar:"قَدْ غَادَرَتْ",uz:"jo'nab ketgan"},{ar:"بَغْدَادَ",uz:"Bag'doddan"}],full_uz:"Bag'doddan jo'nab ketgan.",note:null},
{num:183,time:"00:15:32,000 --> 00:15:34,139",arabic:"رُبَّمَا يَكُونُ أَبُوكِ قَدْ تَخَلَّفَ عَنْهَا",segs:[{ar:"رُبَّمَا",uz:"ehtimol"},{ar:"يَكُونُ أَبُوكِ",uz:"otang"},{ar:"قَدْ تَخَلَّفَ عَنْهَا",uz:"undan qolib ketgandir"}],full_uz:"Ehtimol, otang undan qolib ketgandir.",note:null},
{num:184,time:"00:15:34,139 --> 00:15:36,940",arabic:"لِمَاذَا تَسْتَعْجِلِينَ السَّيِّئَةَ؟",segs:[{ar:"لِمَاذَا",uz:"nega"},{ar:"تَسْتَعْجِلِينَ",uz:"shoshilyapsan"},{ar:"السَّيِّئَةَ",uz:"yomon xabarni"}],full_uz:"Nega yomon xabarni shoshilib kutyapsan?",note:null},
{num:185,time:"00:15:36,940 --> 00:15:37,879",arabic:"اطْمَئِنِّي يَا شَهْنَازُ",segs:[{ar:"اطْمَئِنِّي",uz:"xotirjam bo'l"},{ar:"يَا شَهْنَازُ",uz:"ey Shahnoz"}],full_uz:"Xotirjam bo'l, ey Shahnoz.",note:"اطْمَأَنَّ — xotirjam bo'lmoq."},
{num:186,time:"00:15:37,879 --> 00:15:39,600",arabic:"سَآخُذُكِ إِلَى الدَّارِ",segs:[{ar:"سَآخُذُكِ",uz:"seni olib boraman"},{ar:"إِلَى الدَّارِ",uz:"uyga"}],full_uz:"Seni uyga olib boraman.",note:null},
{num:187,time:"00:15:39,600 --> 00:15:42,540",arabic:"وَأَعِدُكِ بِأَنَّنِي لَنْ أَكُفَّ عَنِ الْبَحْثِ عَنْهُمَا",segs:[{ar:"وَأَعِدُكِ",uz:"va senga va'da beraman"},{ar:"بِأَنَّنِي",uz:"men"},{ar:"لَنْ أَكُفَّ",uz:"to'xtamayman"},{ar:"عَنِ الْبَحْثِ عَنْهُمَا",uz:"ikkalasini qidirishdan"}],full_uz:"Va senga va'da beraman: ikkalasini qidirishdan to'xtamayman.",note:null},
{num:188,time:"00:15:43,500 --> 00:15:46,020",arabic:"لَنْ تَقَرَّ لِي عَيْنٌ",segs:[{ar:"لَنْ تَقَرَّ لِي",uz:"ko'nglim tinchimaydi"},{ar:"عَيْنٌ",uz:"ko'zim"}],full_uz:"Ko'nglim tinchimaydi.",note:null},
{num:189,time:"00:15:46,020 --> 00:15:47,840",arabic:"حَتَّى أَعْثُرَ عَلَيْهِمَا",segs:null,full_uz:"Ikkalasini topmagunimcha.",note:null},
{num:190,time:"00:15:47,840 --> 00:15:49,879",arabic:"أَجَلْ أَجَلْ",segs:null,full_uz:"Ha, ha.",note:null},
{num:191,time:"00:15:49,879 --> 00:15:50,540",arabic:"خَالِدُ",segs:null,full_uz:"Xolid.",note:null},
{num:192,time:"00:15:50,539 --> 00:15:56,559",arabic:"لِمَاذَا لَمْ تَفْتَحْ دُكَّانَكَ حَتَّى الْآنَ؟ لَقَدْ سَأَلَ عَنْكَ الْبَعْضُ",segs:[{ar:"لِمَاذَا لَمْ تَفْتَحْ دُكَّانَكَ",uz:"nega do'koningni ochmading"},{ar:"حَتَّى الْآنَ",uz:"hali-hanuz"},{ar:"لَقَدْ سَأَلَ عَنْكَ الْبَعْضُ",uz:"ba'zilar seni so'rashdi"}],full_uz:"Nega hali-hanuz do'koningni ochmading? Ba'zilar seni so'rashdi.",note:null},
{num:193,time:"00:15:56,559 --> 00:15:58,319",arabic:"كُنْتُ فِي شَأْنٍ مَا",segs:[{ar:"كُنْتُ",uz:"edim"},{ar:"فِي شَأْنٍ مَا",uz:"biror ish bilan"}],full_uz:"Biror ish bilan band edim.",note:null},
{num:194,time:"00:15:58,319 --> 00:16:02,219",arabic:"مَا بِهَا وَلِمَاذَا تَبْكِي؟",segs:[{ar:"مَا بِهَا",uz:"unga nima bo'ldi"},{ar:"وَلِمَاذَا تَبْكِي؟",uz:"nega yig'layapti"}],full_uz:"Unga nima bo'ldi, nega yig'layapti?",note:null},
{num:195,time:"00:16:02,219 --> 00:16:03,679",arabic:"مِسْكِينَةٌ لَقَدْ أَضَاعَتْ أَهْلَهَا",segs:[{ar:"مِسْكِينَةٌ",uz:"bechora"},{ar:"لَقَدْ أَضَاعَتْ أَهْلَهَا",uz:"o'z yaqinlarini yo'qotib qo'ygan"}],full_uz:"Bechora, o'z yaqinlarini yo'qotib qo'ygan.",note:null},
{num:196,time:"00:16:03,679 --> 00:16:06,459",arabic:"أَضَاعَتْ أَهْلَهَا؟ كَيْفَ؟",segs:[{ar:"أَضَاعَتْ أَهْلَهَا؟",uz:"yaqinlarini yo'qotibdimi?"},{ar:"كَيْفَ؟",uz:"qanday?"}],full_uz:"Yaqinlarini yo'qotibdimi? Qanday?",note:null},
{num:197,time:"00:16:06,459 --> 00:16:07,519",arabic:"سَأُخْبِرُكَ فِيمَا بَعْدُ",segs:[{ar:"سَأُخْبِرُكَ",uz:"senga aytaman"},{ar:"فِيمَا بَعْدُ",uz:"keyinroq"}],full_uz:"Keyinroq senga aytaman.",note:null},
{num:198,time:"00:16:07,519 --> 00:16:09,299",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:199,time:"00:16:09,299 --> 00:16:10,279",arabic:"وَعَلَيْكُمُ السَّلَامُ",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:200,time:"00:16:10,279 --> 00:16:11,919",arabic:"هَيَّا يَا شَهْنَازُ هَيَّا",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"يَا شَهْنَازُ",uz:"ey Shahnoz"},{ar:"هَيَّا",uz:"qani"}],full_uz:"Qani, ey Shahnoz, qani.",note:null},
{num:201,time:"00:16:20,539 --> 00:16:40,539",arabic:"مُوسِيقَى",segs:null,full_uz:null,note:null},
{num:202,time:"00:16:40,539 --> 00:16:44,679",arabic:"مُرَّ كَاتِبُكَ فِي الْمَدِينَةِ الْمُنَوَّرَةِ نُرْسِلْهُ كِتَابًا مِثْلَ هَذَا الْكِتَابِ",segs:[{ar:"مُرَّ كَاتِبُكَ",uz:"kotibingga buyur"},{ar:"فِي الْمَدِينَةِ الْمُنَوَّرَةِ",uz:"Madina shahrida"},{ar:"نُرْسِلْهُ كِتَابًا",uz:"unga bir maktub yuboramiz"},{ar:"مِثْلَ هَذَا الْكِتَابِ",uz:"xuddi shu maktub kabi"}],full_uz:"Kotibingga Madinadan xuddi shu kabi bir maktub yuborishni buyur.",note:null},
{num:203,time:"00:16:44,679 --> 00:16:46,539",arabic:"أَسْمُو وَطْعَهُ",segs:null,full_uz:"",note:null},
{num:204,time:"00:16:46,539 --> 00:16:50,219",arabic:"يَحْيَى",segs:null,full_uz:"Yahyo.",note:null},
{num:205,time:"00:16:50,219 --> 00:16:52,679",arabic:"أَمْرُ مَوْلَايَ",segs:null,full_uz:"Amringiz, hazratim.",note:null},
{num:206,time:"00:16:52,679 --> 00:16:56,740",arabic:"إِلَى أَيْنَ وَصَلْتُمْ مَعَ ابْنِ الْأَيْهَمِ",segs:[{ar:"إِلَى أَيْنَ وَصَلْتُمْ",uz:"qayergacha yetib keldingiz"},{ar:"مَعَ ابْنِ الْأَيْهَمِ",uz:"Ibn al-Ayham bilan"}],full_uz:"Ibn al-Ayham bilan ish qayergacha yetdi?",note:null},
{num:207,time:"00:16:56,740 --> 00:17:03,919",arabic:"كَأَنِّي بِهِ يَا مَوْلَايَ",segs:[{ar:"كَأَنِّي بِهِ",uz:"menimcha u"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Menimcha, hazratim, u...",note:null},
{num:208,time:"00:17:03,919 --> 00:17:06,339",arabic:"قَدْ بَدَأَ يَتَخَلَّى عَنْ غُرُورِهِ",segs:[{ar:"قَدْ بَدَأَ",uz:"boshladi"},{ar:"يَتَخَلَّى عَنْ غُرُورِهِ",uz:"kibridan voz kechishga"}],full_uz:"U kibridan voz kecha boshladi.",note:"غُرُورٌ — kibr, mag'rurlik."},
{num:209,time:"00:17:06,339 --> 00:17:08,000",arabic:"وَتَلِينُ مَقْنَاتُهُ",segs:[{ar:"وَتَلِينُ",uz:"yumshamoqda"},{ar:"مَقْنَاتُهُ",uz:"bo'yni"}],full_uz:"Bo'yni ham yumshamoqda.",note:null},
{num:210,time:"00:17:08,000 --> 00:17:10,960",arabic:"كَأَنَّكَ",segs:null,full_uz:"Go'yo sen...",note:null},
{num:211,time:"00:17:10,960 --> 00:17:12,819",arabic:"فَلْيَطْمَئِنَّ قَلْبُ مَوْلَايَ",segs:[{ar:"فَلْيَطْمَئِنَّ",uz:"xotirjam bo'lsin"},{ar:"قَلْبُ مَوْلَايَ",uz:"hazratimning qalbi"}],full_uz:"Hazratimning qalbi xotirjam bo'lsin.",note:null},
{num:212,time:"00:17:12,819 --> 00:17:15,000",arabic:"غَدًا أَوْ بَعْدَ غَدٍ",segs:null,full_uz:"Ertaga yoki indinga.",note:null},
{num:213,time:"00:17:15,000 --> 00:17:17,859",arabic:"سَتَسْمَعُونَ بُقْيَةَ مَا تَنْتَظِرُ",segs:[{ar:"سَتَسْمَعُونَ",uz:"eshitasiz"},{ar:"بُقْيَةَ مَا تَنْتَظِرُ",uz:"kutayotgan narsangizning qolganini"}],full_uz:"Ertaga yoki indinga kutayotgan narsangizning qolganini eshitasiz.",note:null},
{num:214,time:"00:17:17,859 --> 00:17:19,039",arabic:"لَنْ يَطْمَئِنَّ قَلْبِي",segs:[{ar:"لَنْ يَطْمَئِنَّ",uz:"xotirjam bo'lmaydi"},{ar:"قَلْبِي",uz:"qalbim"}],full_uz:"Qalbim xotirjam bo'lmaydi.",note:null},
{num:215,time:"00:17:19,039 --> 00:17:24,039",arabic:"وَلَنْ يَقَرَّ لِي قَرَارٌ حَتَّى أُمْسِكَ بِنَاصِيَةِ هَؤُلَاءِ الْمَارِقِينَ",segs:[{ar:"وَلَنْ يَقَرَّ لِي قَرَارٌ",uz:"ko'nglim tinchimaydi"},{ar:"حَتَّى أُمْسِكَ بِنَاصِيَةِ",uz:"qo'lga olmagunimcha"},{ar:"هَؤُلَاءِ الْمَارِقِينَ",uz:"bu isyonchilarni"}],full_uz:"Bu isyonchilarni qo'lga olmagunimcha ko'nglim tinchimaydi.",note:"الْمَارِقُونَ — itoatdan chiqqanlar, isyonchilar."},
{num:216,time:"00:17:24,039 --> 00:17:26,940",arabic:"وَأَجْعَلَهُمْ آيَةً لِمَنْ شَقَّ عَصَا الطَّاعَةِ",segs:[{ar:"وَأَجْعَلَهُمْ آيَةً",uz:"ularni ibrat qilaman"},{ar:"لِمَنْ شَقَّ عَصَا الطَّاعَةِ",uz:"itoat hassasini sindirganlarga"}],full_uz:"Ularni itoatdan chiqqanlar uchun ibrat qilaman.",note:"شَقَّ عَصَا الطَّاعَةِ — itoatdan bosh tortmoq, bo'ysunmaslik."},
{num:217,time:"00:17:26,940 --> 00:17:29,599",arabic:"لَكَ مَا تُرِيدُ يَا مَوْلَايَ",segs:[{ar:"لَكَ مَا تُرِيدُ",uz:"xohlaganingiz bo'ladi"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Xohlaganingiz bo'ladi, hazratim.",note:null},
{num:218,time:"00:17:45,000 --> 00:17:51,920",arabic:"سَيَكُونُ لِي مَا أُرِيدُ",segs:[{ar:"سَيَكُونُ لِي",uz:"meniki bo'ladi"},{ar:"مَا أُرِيدُ",uz:"xohlaganim"}],full_uz:"Xohlaganim meniki bo'ladi.",note:null},
{num:219,time:"00:17:51,920 --> 00:17:56,599",arabic:"سَيَكُونُ لِي مَا أُرِيدُ وَإِلَّا",segs:[{ar:"سَيَكُونُ لِي",uz:"meniki bo'ladi"},{ar:"مَا أُرِيدُ",uz:"xohlaganim"},{ar:"وَإِلَّا",uz:"aks holda"}],full_uz:"Xohlaganim meniki bo'ladi, aks holda...",note:null},
{num:220,time:"00:17:56,599 --> 00:18:01,660",arabic:"فِي حَلَقَةِ شَيْخِي لَوْمٌ عَلَى التَّأَخُّرِ",segs:[{ar:"فِي حَلَقَةِ شَيْخِي",uz:"shayximning darsida"},{ar:"لَوْمٌ عَلَى التَّأَخُّرِ",uz:"kechikkanim uchun tanbeh bor"}],full_uz:"Shayximning darsida kechikkanim uchun tanbeh bor.",note:null},
{num:221,time:"00:18:01,660 --> 00:18:04,680",arabic:"وَفِي دَارِ الْحِكْمَةِ لَوْمٌ عَلَى التَّأَخُّرِ",segs:[{ar:"وَفِي دَارِ الْحِكْمَةِ",uz:"Hikmat uyida ham"},{ar:"لَوْمٌ عَلَى التَّأَخُّرِ",uz:"kechikkanim uchun tanbeh bor"}],full_uz:"Hikmat uyida ham kechikkanim uchun tanbeh bor.",note:"دَارُ الْحِكْمَةِ — Hikmat uyi."},
{num:222,time:"00:18:04,680 --> 00:18:08,099",arabic:"مَاذَا يَفْعَلُ بِنَفْسِهِ أَحْمَدُ بْنُ حَنْبَلٍ",segs:[{ar:"مَاذَا يَفْعَلُ بِنَفْسِهِ",uz:"o'zini nima bilan band qiladi"},{ar:"أَحْمَدُ بْنُ حَنْبَلٍ",uz:"Ahmad ibn Hanbal"}],full_uz:"Ahmad ibn Hanbal o'zini nima bilan band qiladi?",note:null},
{num:223,time:"00:18:08,099 --> 00:18:10,859",arabic:"حَتَّى يُوَفِّقَ بَيْنَ الْعِلْمِ وَالْعَمَلِ",segs:[{ar:"حَتَّى يُوَفِّقَ",uz:"muvofiqlashtirish uchun"},{ar:"بَيْنَ الْعِلْمِ وَالْعَمَلِ",uz:"ilm bilan amalni"}],full_uz:"Ilm bilan amalni muvofiqlashtirish uchun.",note:null},
{num:224,time:"00:18:10,859 --> 00:18:17,000",arabic:"يَقُولُ لَكَ الْوَالِي يُرِيدُ أَخْبَارَ السُّوقِ",segs:[{ar:"يَقُولُ لَكَ الْوَالِي",uz:"voliy senga aytadi"},{ar:"يُرِيدُ أَخْبَارَ السُّوقِ",uz:"bozor haqidagi xabarlarni xohlaydi"}],full_uz:"Voliy senga bozor haqidagi xabarlarni xohlayotganini aytadi.",note:null},
{num:225,time:"00:18:17,000 --> 00:18:20,379",arabic:"فَلَا تُفَوِّتْ صَغِيرَةً وَلَا كَبِيرَةً",segs:[{ar:"فَلَا تُفَوِّتْ",uz:"hech narsani o'tkazib yuborma"},{ar:"صَغِيرَةً وَلَا كَبِيرَةً",uz:"kichigini ham kattasini ham"}],full_uz:"Shuning uchun kichigini ham, kattasini ham o'tkazib yuborma.",note:null},
{num:226,time:"00:18:20,379 --> 00:18:24,719",arabic:"وَرَكِّزْ جُلَّ اهْتِمَامِكَ عَلَى مَا يَقُولُهُ الْعُلَمَاءُ",segs:[{ar:"وَرَكِّزْ جُلَّ اهْتِمَامِكَ",uz:"butun e'tiboringni qarat"},{ar:"عَلَى مَا يَقُولُهُ الْعُلَمَاءُ",uz:"ulamolar aytayotgan narsaga"}],full_uz:"Butun e'tiboringni ulamolar aytayotgan narsalarga qarat.",note:"جُلُّ — aksariyat qism, katta qismi."},
{num:227,time:"00:18:24,719 --> 00:18:31,479",arabic:"صَدَقَ الْوَالِي فِي تَخَوُّفِهِ مِنْ أُولَئِكَ الْعُلَمَاءِ الَّذِينَ حَادُوا عَنْ طَرِيقِ الصَّوَابِ",segs:[{ar:"صَدَقَ الْوَالِي",uz:"voliy haq"},{ar:"فِي تَخَوُّفِهِ",uz:"o'z xavotirida"},{ar:"مِنْ أُولَئِكَ الْعُلَمَاءِ",uz:"o'sha ulamolardan"},{ar:"الَّذِينَ حَادُوا عَنْ طَرِيقِ الصَّوَابِ",uz:"to'g'ri yo'ldan og'gan"}],full_uz:"Voliy to'g'ri yo'ldan og'gan o'sha ulamolardan xavotirlanishida haq.",note:"حَادَ عَنْ — chetga chiqmoq, og'moq."},
{num:228,time:"00:18:31,479 --> 00:18:32,639",arabic:"فِعْلًا",segs:null,full_uz:"Haqiqatan.",note:null},
{num:229,time:"00:18:32,639 --> 00:18:37,119",arabic:"فَهُمْ الْأَقْدَرُ عَلَى تَجْنِيدِ الشَّبَابِ لِلنَّيْلِ مِنَ الْخَلِيفَةِ وَالْبِلَادِ",segs:[{ar:"فَهُمْ الْأَقْدَرُ",uz:"ular eng qodir"},{ar:"عَلَى تَجْنِيدِ الشَّبَابِ",uz:"yoshlarni safarbar etishga"},{ar:"لِلنَّيْلِ مِنَ الْخَلِيفَةِ وَالْبِلَادِ",uz:"xalifa va mamlakatga qarshi chiqish uchun"}],full_uz:"Chunki xalifa va mamlakatga qarshi chiqish uchun yoshlarni safarbar etishga ular eng qodir.",note:"النَّيْلُ مِنْ — zarar yetkazish, qarshi chiqish."},
{num:230,time:"00:18:37,119 --> 00:18:41,459",arabic:"وَالْأَقْدَرُ أَيْضًا عَلَى زَرْعِ الْفِتْنَةِ بَيْنَ النَّاسِ بِطَرِيقَةٍ أَوْ بِأُخْرَى",segs:[{ar:"وَالْأَقْدَرُ أَيْضًا",uz:"yana eng qodirlar"},{ar:"عَلَى زَرْعِ الْفِتْنَةِ",uz:"fitna qo'zg'atishga"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"},{ar:"بِطَرِيقَةٍ أَوْ بِأُخْرَى",uz:"u yoki bu yo'l bilan"}],full_uz:"Yana odamlar orasida u yoki bu yo'l bilan fitna qo'zg'atishga ham eng qodirlar.",note:"زَرْعُ الْفِتْنَةِ — fitna qo'zg'atish."},
{num:231,time:"00:18:41,459 --> 00:18:43,059",arabic:"عَلَى كُلِّ حَالٍ",segs:null,full_uz:"Har holda.",note:null},
{num:232,time:"00:18:43,059 --> 00:18:45,419",arabic:"مَادَامَ فِي الْأَمْرِ خَيْرٌ لِلْأُمَّةِ",segs:[{ar:"مَادَامَ",uz:"modomiki"},{ar:"فِي الْأَمْرِ",uz:"bu ishda"},{ar:"خَيْرٌ لِلْأُمَّةِ",uz:"ummat uchun yaxshilik bor ekan"}],full_uz:"Modomiki bu ishda ummat uchun yaxshilik bor ekan...",note:null},
{num:233,time:"00:18:45,419 --> 00:18:47,979",arabic:"فَلَنْ أَدَّخِرَ جُهْدًا فِيمَا طُلِبَ مِنِّي",segs:[{ar:"فَلَنْ أَدَّخِرَ جُهْدًا",uz:"hech qanday kuchimni ayamayman"},{ar:"فِيمَا طُلِبَ مِنِّي",uz:"mendan so'ralgan ishda"}],full_uz:"Mendan so'ralgan ishda hech qanday kuchimni ayamayman.",note:"أَدَّخَرَ جُهْدًا — kuchini ayamoq."},
{num:234,time:"00:19:07,119 --> 00:19:37,099",arabic:"الْمُتَرْجِمُ لِلْقَنَاةِ",segs:null,full_uz:null,note:null},
{num:235,time:"00:19:37,119 --> 00:19:49,639",arabic:"أَنَا لَسْتُ خَائِفَةً عَلَيْهِ",segs:null,full_uz:"Men uning uchun qo'rqayotganim yo'q.",note:null},
{num:236,time:"00:19:49,639 --> 00:19:53,439",arabic:"بِسَبَبِ تَأَخُّرِهِ فِي الرُّجُوعِ إِلَى الْمَنْزِلِ يَا أُمَّ خَالِدٍ",segs:[{ar:"بِسَبَبِ تَأَخُّرِهِ",uz:"uning kechikgani sababli"},{ar:"فِي الرُّجُوعِ إِلَى الْمَنْزِلِ",uz:"uyga qaytishda"},{ar:"يَا أُمَّ خَالِدٍ",uz:"ey Xolidning onasi"}],full_uz:"Uning uyga qaytishda kechikgani sababli emas, ey Xolidning onasi.",note:null},
{num:237,time:"00:19:53,439 --> 00:19:57,219",arabic:"كُلُّ مَا أَخْشَاهُ أَنْ يَسْتَهْوِيَهُ الْعَمَلُ",segs:[{ar:"كُلُّ مَا أَخْشَاهُ",uz:"men qo'rqayotgan yagona narsa"},{ar:"أَنْ يَسْتَهْوِيَهُ الْعَمَلُ",uz:"uni ish o'ziga berib qo'yishi"}],full_uz:"Men qo'rqayotgan yagona narsa — ish uni o'ziga berib qo'yishi.",note:"اسْتَهْوَى — o'ziga rom etmoq."},
{num:238,time:"00:19:57,219 --> 00:19:58,819",arabic:"فَيَنْسَى دُرُوسَهُ",segs:[{ar:"فَيَنْسَى",uz:"shunda unutadi"},{ar:"دُرُوسَهُ",uz:"darslarini"}],full_uz:"Shunda darslarini unutib qo'yadi.",note:null},
{num:239,time:"00:19:58,819 --> 00:20:01,259",arabic:"وَيَصْرِفَهُ تَحْصِيلُ الرِّزْقِ",segs:[{ar:"وَيَصْرِفَهُ",uz:"va uni chalg'itadi"},{ar:"تَحْصِيلُ الرِّزْقِ",uz:"rizq topish"}],full_uz:"Rizq topish uni chalg'itib...",note:null},
{num:240,time:"00:20:01,259 --> 00:20:04,199",arabic:"عَنْ طَلَبِ الْعِلْمِ بِحُجَّةِ حَاجَتِنَا إِلَى الْمَالِ",segs:[{ar:"عَنْ طَلَبِ الْعِلْمِ",uz:"ilm talab qilishdan"},{ar:"بِحُجَّةِ",uz:"bahonasida"},{ar:"حَاجَتِنَا إِلَى الْمَالِ",uz:"pulga muhtojligimizni"}],full_uz:"Pulga muhtojligimiz bahonasida uni ilm talab qilishdan chalg'itib qo'yishidan qo'rqaman.",note:null},
{num:241,time:"00:20:04,199 --> 00:20:06,659",arabic:"لَنْ يَكُونَ ذَلِكَ بِإِذْنِ اللَّهِ",segs:[{ar:"لَنْ يَكُونَ ذَلِكَ",uz:"bunday bo'lmaydi"},{ar:"بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan"}],full_uz:"Allohning izni bilan bunday bo'lmaydi.",note:null},
{num:242,time:"00:20:06,660 --> 00:20:10,220",arabic:"فَكُلُّنَا يَعْلَمُ مَا فَعَلْتِهِ مِنْ أَجْلِهِ",segs:[{ar:"فَكُلُّنَا يَعْلَمُ",uz:"chunki hammamiz bilamiz"},{ar:"مَا فَعَلْتِهِ مِنْ أَجْلِهِ",uz:"uning uchun nimalar qilganingni"}],full_uz:"Chunki hammamiz uning uchun nimalar qilganingni bilamiz.",note:null},
{num:243,time:"00:20:10,220 --> 00:20:14,000",arabic:"تَهُونُ عَلَيْنَا فِي الْمَعَالِي نُفُوسُنَا يَا أُمَّ خَالِدٍ",segs:[{ar:"تَهُونُ عَلَيْنَا",uz:"biz uchun arzimas bo'ladi"},{ar:"فِي الْمَعَالِي",uz:"oliy maqsadlar yo'lida"},{ar:"نُفُوسُنَا",uz:"jonlarimiz"},{ar:"يَا أُمَّ خَالِدٍ",uz:"ey Xolidning onasi"}],full_uz:"Ey Xolidning onasi, oliy maqsadlar yo'lida jonlarimiz biz uchun arzimas bo'ladi.",note:null},
{num:244,time:"00:20:14,000 --> 00:20:16,600",arabic:"وَأَحْمَدُ مَا زَالَ فِي نِصْفِ الطَّرِيقِ",segs:[{ar:"وَأَحْمَدُ",uz:"Ahmad esa"},{ar:"مَا زَالَ فِي نِصْفِ الطَّرِيقِ",uz:"hali yo'lning yarmida"}],full_uz:"Ahmad esa hali yo'lning yarmida.",note:null},
{num:245,time:"00:20:16,600 --> 00:20:21,360",arabic:"وَهُوَ بِحَاجَةٍ دَائِمَةٍ إِلَى مَنْ يُعِينُهُ عَلَى نَائِبَاتِ الدَّهْرِ",segs:[{ar:"وَهُوَ بِحَاجَةٍ دَائِمَةٍ",uz:"u doimo muhtoj"},{ar:"إِلَى مَنْ يُعِينُهُ",uz:"unga yordam beradigan kishiga"},{ar:"عَلَى نَائِبَاتِ الدَّهْرِ",uz:"zamonning og'ir sinovlarida"}],full_uz:"U zamonning og'ir sinovlarida unga yordam beradigan kishiga doimo muhtoj.",note:"نَائِبَاتُ الدَّهْرِ — zamonning og'ir sinovlari."},
{num:246,time:"00:20:21,360 --> 00:20:23,640",arabic:"وَيُزِيلُ عَنْهُ عَقَبَاتِ الطَّرِيقِ",segs:[{ar:"وَيُزِيلُ عَنْهُ",uz:"undan ketkazadigan"},{ar:"عَقَبَاتِ الطَّرِيقِ",uz:"yo'l to'siqlarini"}],full_uz:"Va undan yo'l to'siqlarini ketkazadigan kishiga.",note:"عَقَبَاتٌ — to'siqlar."},
{num:247,time:"00:20:23,640 --> 00:20:26,560",arabic:"حَتَّى يَصِلَ إِلَى مَا يَصْبُو إِلَيْهِ",segs:[{ar:"حَتَّى يَصِلَ",uz:"yetib borishi uchun"},{ar:"إِلَى مَا يَصْبُو إِلَيْهِ",uz:"intilayotgan maqsadiga"}],full_uz:"Intilayotgan maqsadiga yetib borishi uchun.",note:"يَصْبُو إِلَى — intilmoq, orzu qilmoq."},
{num:248,time:"00:20:26,560 --> 00:20:29,300",arabic:"وَلَا أَشَدَّ مَا أَطْمَحُ يَا أُمَّ خَالِدٍ",segs:[{ar:"وَلَا أَشَدَّ مَا أَطْمَحُ",uz:"mening eng katta orzum"},{ar:"يَا أُمَّ خَالِدٍ",uz:"ey Xolidning onasi"}],full_uz:"Ey Xolidning onasi, mening eng katta orzum...",note:null},
{num:249,time:"00:20:29,300 --> 00:20:33,800",arabic:"أَنْ أَرَاهُ عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ",segs:[{ar:"أَنْ أَرَاهُ",uz:"uni ko'rishim"},{ar:"عَلَمًا مِنْ أَعْلَامِ",uz:"buyuk allomalardan biri sifatida"},{ar:"هَذِهِ الْأُمَّةِ",uz:"bu ummatning"}],full_uz:"Uni bu ummatning buyuk allomalaridan biri sifatida ko'rish.",note:"عَلَمٌ — mashhur, buyuk shaxs; عَلَمٌ مِنْ أَعْلَامِ — buyuk namoyandalardan biri."},
{num:250,time:"00:20:33,799 --> 00:20:37,220",arabic:"أَنْتِ لَسْتِ مُقَصِّرَةً فِي حَقِّهِ يَا أُمَّ أَحْمَدَ",segs:[{ar:"أَنْتِ لَسْتِ مُقَصِّرَةً فِي حَقِّهِ",uz:"sen uning haqqida kamchilik qilmayapsan"},{ar:"يَا أُمَّ أَحْمَدَ",uz:"ey Ahmadning onasi"}],full_uz:"Ey Ahmadning onasi, sen uning haqqida hech qanday kamchilik qilmayapsan.",note:"مُقَصِّرٌ — kamchilik qiluvchi, e'tiborsiz."},
{num:251,time:"00:20:37,220 --> 00:20:39,619",arabic:"مَا تَفْعَلِينَهُ مِنْ أَجْلِهِ",segs:[{ar:"مَا تَفْعَلِينَهُ",uz:"qilayotgan ishlaring"},{ar:"مِنْ أَجْلِهِ",uz:"uning uchun"}],full_uz:"Uning uchun qilayotgan ishlaring...",note:null},
{num:252,time:"00:20:39,619 --> 00:20:43,399",arabic:"يَصْعُبُ عَلَى الرِّجَالِ الشِّدَادِ فِي فِعْلِهِ",segs:[{ar:"يَصْعُبُ عَلَى الرِّجَالِ الشِّدَادِ",uz:"hatto kuchli erkaklarga ham qiyin"},{ar:"فِي فِعْلِهِ",uz:"uni qilish"}],full_uz:"Bunday ishni qilish hatto kuchli erkaklarga ham qiyin.",note:null},
{num:253,time:"00:20:43,399 --> 00:20:47,720",arabic:"لَقَدْ نَذَرْتِ عُمْرَكِ وَحَيَاتَكِ وَكُلَّ مَا تَمْلِكِينَ",segs:[{ar:"لَقَدْ نَذَرْتِ",uz:"sen bag'ishlading"},{ar:"عُمْرَكِ وَحَيَاتَكِ",uz:"umring va hayotingni"},{ar:"وَكُلَّ مَا تَمْلِكِينَ",uz:"va bor-budingni"}],full_uz:"Sen umringni, hayotingni va bor-budingni unga bag'ishlading.",note:"نَذَرَ — bag'ishlamoq, nazr qilmoq."},
{num:254,time:"00:20:47,720 --> 00:20:51,659",arabic:"حَتَّى أَصْبَحَ رَجُلًا مَلَأَ السَّمْعَ وَالْبَصَرَ",segs:[{ar:"حَتَّى أَصْبَحَ رَجُلًا",uz:"u shunday bir odam bo'lguniga qadar"},{ar:"مَلَأَ السَّمْعَ وَالْبَصَرَ",uz:"el orasida dong taratgan"}],full_uz:"U el orasida dong taratgan bir odam bo'lguniga qadar.",note:"مَلَأَ السَّمْعَ وَالْبَصَرَ — juda mashhur bo'lmoq."},
{num:255,time:"00:20:51,659 --> 00:20:53,500",arabic:"وَمَعَ ذَلِكَ يَا أُمَّ خَالِدٍ",segs:[{ar:"وَمَعَ ذَلِكَ",uz:"shunga qaramay"},{ar:"يَا أُمَّ خَالِدٍ",uz:"ey Xolidning onasi"}],full_uz:"Shunga qaramay, ey Xolidning onasi...",note:null},
{num:256,time:"00:20:53,500 --> 00:20:57,559",arabic:"أَجِدُ نَفْسِي سَبَبًا فِي عَدَمِ تَحْصِيلِهِ الْعِلْمَ",segs:[{ar:"أَجِدُ نَفْسِي سَبَبًا",uz:"o'zimni sababchi deb bilaman"},{ar:"فِي عَدَمِ تَحْصِيلِهِ الْعِلْمَ",uz:"uning ilm ololmayotganiga"}],full_uz:"Men o'zimni uning ilm ololmayotganiga sababchi deb bilaman.",note:"تَحْصِيلُ الْعِلْمِ — ilm olish."},
{num:257,time:"00:20:57,559 --> 00:21:01,839",arabic:"أَنَا مَنْ لَمْ يَنْفَطِرْ قَلْبُهَا عَلَى وَحِيدِهَا",segs:[{ar:"أَنَا مَنْ",uz:"men shunday kishiman-ki"},{ar:"لَمْ يَنْفَطِرْ قَلْبُهَا",uz:"uning qalbi yorilmadi"},{ar:"عَلَى وَحِيدِهَا",uz:"yolg'iz farzandi uchun"}],full_uz:"Men yolg'iz farzandi uchun qalbi ezilmagan kishiman.",note:"اِنْفَطَرَ الْقَلْبُ — qalbi ezilmoq, yorilmoq."},
{num:258,time:"00:21:01,839 --> 00:21:05,319",arabic:"فَتَرَكْتُهُ مُمَزَّقًا بَيْنَ عَمَلِهِ وَعِلْمِهِ",segs:[{ar:"فَتَرَكْتُهُ مُمَزَّقًا",uz:"uni ikkilanib qoldirdim"},{ar:"بَيْنَ عَمَلِهِ وَعِلْمِهِ",uz:"ishi bilan ilmi o'rtasida"}],full_uz:"Uni ishi bilan ilmi o'rtasida ikkilanib qoldirdim.",note:"مُمَزَّقٌ — bo'linib ketgan, ikkilanib qolgan."},
{num:259,time:"00:21:05,319 --> 00:21:07,679",arabic:"هَوِّنِي عَلَيْكِ يَا أُمَّ أَحْمَدَ",segs:[{ar:"هَوِّنِي عَلَيْكِ",uz:"o'zingni buncha qiynamagin"},{ar:"يَا أُمَّ أَحْمَدَ",uz:"ey Ahmadning onasi"}],full_uz:"O'zingni buncha qiynamagin, ey Ahmadning onasi.",note:"هَوَّنَ عَلَى — yengil qilmoq, taskin bermoq."},
{num:260,time:"00:21:07,679 --> 00:21:10,059",arabic:"فَالْأَمْرُ أَبْسَطُ مِمَّا تَتَخَيَّلِينَ",segs:[{ar:"فَالْأَمْرُ أَبْسَطُ",uz:"ish bundan osonroq"},{ar:"مِمَّا تَتَخَيَّلِينَ",uz:"sen tasavvur qilganingdan"}],full_uz:"Ish sen tasavvur qilganingdan osonroq.",note:null},
{num:261,time:"00:21:26,000 --> 00:21:28,599",arabic:"السَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ",segs:[{ar:"السَّلَامُ عَلَى مَوْلَايَ",uz:"salom hazratimga"},{ar:"أَمِيرِ الْمُؤْمِنِينَ",uz:"mo'minlar amiriga"}],full_uz:"Mo'minlar amiri hazratimga salom.",note:null},
{num:262,time:"00:21:28,599 --> 00:21:30,720",arabic:"عَلَيْكَ السَّلَامُ يَا يَحْيَى",segs:[{ar:"عَلَيْكَ السَّلَامُ",uz:"senga salom"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Senga salom, ey Yahyo.",note:null},
{num:263,time:"00:21:30,720 --> 00:21:45,100",arabic:"هَذِهِ قَائِمَةٌ بِأَسْمَاءِ الْمُتَآمِرِينَ يَا مَوْلَايَ",segs:[{ar:"هَذِهِ قَائِمَةٌ",uz:"bu ro'yxat"},{ar:"بِأَسْمَاءِ الْمُتَآمِرِينَ",uz:"fitna uyushtirayotganlarning ismlari"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Bu fitna uyushtirayotganlarning ismlari ro'yxati, hazratim.",note:"الْمُتَآمِرُونَ — fitna uyushtiruvchilar, til biriktiruvchilar."},
{num:264,time:"00:21:45,100 --> 00:21:52,299",arabic:"أَنَا حَصَلْتُ عَلَيْهَا يَا يَحْيَى",segs:[{ar:"أَنَا حَصَلْتُ عَلَيْهَا",uz:"men uni qo'lga kiritdim"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Men uni qo'lga kiritdim, ey Yahyo.",note:null},
{num:265,time:"00:21:52,299 --> 00:21:56,180",arabic:"أَلَمْ أَقُلْ لَكَ يَا مَوْلَايَ إِنَّهَا مَسْأَلَةُ وَقْتٍ",segs:[{ar:"أَلَمْ أَقُلْ لَكَ",uz:"sizga aytmaganmidi"},{ar:"يَا مَوْلَايَ",uz:"hazratim"},{ar:"إِنَّهَا مَسْأَلَةُ وَقْتٍ",uz:"bu faqat vaqt masalasi ekanini"}],full_uz:"Sizga aytmaganmidi, hazratim, bu faqat vaqt masalasi deb.",note:"مَسْأَلَةُ وَقْتٍ — vaqt masalasi."},
{num:266,time:"00:21:56,180 --> 00:21:59,839",arabic:"وَسَيَعْتَرِفُ ذَلِكَ الْخَائِنُ بِجُرْمِهِ وَشُرَكَائِهِ",segs:[{ar:"وَسَيَعْتَرِفُ ذَلِكَ الْخَائِنُ",uz:"va o'sha xoin tan oladi"},{ar:"بِجُرْمِهِ وَشُرَكَائِهِ",uz:"o'z jinoyati va sheriklarini"}],full_uz:"Va o'sha xoin o'z jinoyati va sheriklarini tan oladi.",note:null},
{num:267,time:"00:21:59,839 --> 00:22:13,639",arabic:"أَوَاثِقٌ أَنْتَ أَنَّهُ لَمْ يُضْمِرْ شَيْئًا وَلَمْ يَكْتُمْ سِرًّا",segs:[{ar:"أَوَاثِقٌ أَنْتَ",uz:"sen ishonching komilmi"},{ar:"أَنَّهُ لَمْ يُضْمِرْ شَيْئًا",uz:"u hech narsani yashirmaganiga"},{ar:"وَلَمْ يَكْتُمْ سِرًّا",uz:"va hech qanday sirni yashirmaganiga"}],full_uz:"U hech narsani yashirmaganiga va hech qanday sirni yashirmaganiga ishonching komilmi?",note:"أَضْمَرَ — yashirmoq, ichida saqlamoq."},
{num:268,time:"00:22:13,639 --> 00:22:17,159",arabic:"أَمَّا عَنِ ابْنِ الْأَيْهَمِ فَأَنَا وَاثِقٌ يَا مَوْلَايَ",segs:[{ar:"أَمَّا عَنِ ابْنِ الْأَيْهَمِ",uz:"Ibn al-Ayhamga kelsak"},{ar:"فَأَنَا وَاثِقٌ",uz:"men ishonchim komil"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ibn al-Ayhamga kelsak, ishonchim komil, hazratim.",note:null},
{num:269,time:"00:22:17,159 --> 00:22:20,199",arabic:"أَنَّهُ لَمْ يَعْرِفْ أَحَدًا إِلَّا وَأَخْبَرَنَا عَنْهُ",segs:[{ar:"أَنَّهُ لَمْ يَعْرِفْ أَحَدًا",uz:"u hech kimni tanimaganiga"},{ar:"إِلَّا وَأَخْبَرَنَا عَنْهُ",uz:"darhol bizga u haqida xabar berganiga"}],full_uz:"U tanigan har bir kishi haqida bizga xabar bergan.",note:null},
{num:270,time:"00:22:20,199 --> 00:22:27,039",arabic:"هَلْ تَخْشَى أَنَّ هُنَاكَ مَنْ اشْتَرَكَ مَعَهُمْ فِي الْمُؤَامَرَةِ",segs:[{ar:"هَلْ تَخْشَى",uz:"qo'rqyapsanmi"},{ar:"أَنَّ هُنَاكَ مَنْ اشْتَرَكَ مَعَهُمْ",uz:"ular bilan birga qatnashgan yana kimdir borligidan"},{ar:"فِي الْمُؤَامَرَةِ",uz:"fitnada"}],full_uz:"Ular bilan birga fitnada qatnashgan yana kimdir borligidan qo'rqyapsanmi?",note:null},
{num:271,time:"00:22:27,039 --> 00:22:29,639",arabic:"وَلَا يَعْرِفُهُ ابْنُ الْأَيْهَمِ",segs:[{ar:"وَلَا يَعْرِفُهُ",uz:"uni tanimaydi"},{ar:"ابْنُ الْأَيْهَمِ",uz:"Ibn al-Ayham"}],full_uz:"Ibn al-Ayham uni tanimaydi.",note:null},
{num:272,time:"00:22:29,640 --> 00:22:32,540",arabic:"حَدَسْتَ مَا فِي نَفْسِي يَا مَوْلَايَ",segs:[{ar:"حَدَسْتَ مَا فِي نَفْسِي",uz:"ko'nglimdagini topdingiz"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ko'nglimdagini topdingiz, hazratim.",note:"حَدَسَ — ichidan sezmoq, taxmin qilmoq."},
{num:273,time:"00:22:32,540 --> 00:22:35,880",arabic:"وَمَا تَرَى؟",segs:null,full_uz:"Xo'sh, nima deb o'ylaysan?",note:null},
{num:274,time:"00:22:35,880 --> 00:22:37,280",arabic:"هُمَا أَمْرَانِ يَا مَوْلَايَ",segs:[{ar:"هُمَا أَمْرَانِ",uz:"ikki masala bor"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ikki masala bor, hazratim.",note:null},
{num:275,time:"00:22:37,280 --> 00:22:45,540",arabic:"أَوَّلُهُمَا أَنْ نَأْتِيَ بِمَنْ أَقْرَبُهُمْ ابْنُ الْأَيْهَمِ وَنَضَعَهُمْ أَمَامَ أَعْيُنِنَا",segs:[{ar:"أَوَّلُهُمَا",uz:"birinchisi"},{ar:"أَنْ نَأْتِيَ بِمَنْ أَقْرَبُهُمْ ابْنُ الْأَيْهَمِ",uz:"Ibn al-Ayhamga eng yaqin bo'lganlarini olib kelishimiz"},{ar:"وَنَضَعَهُمْ أَمَامَ أَعْيُنِنَا",uz:"va ularni ko'z o'ngimizda saqlashimiz"}],full_uz:"Birinchisi, Ibn al-Ayhamga eng yaqin bo'lganlarini olib kelib, ularni ko'z o'ngimizda saqlashimiz.",note:null},
{num:276,time:"00:22:45,540 --> 00:22:50,220",arabic:"لَعَلَّنَا نَعْرِفُ مِنْهُمْ مَا لَمْ يَعْرِفْهُ ابْنُ الْأَيْهَمِ",segs:[{ar:"لَعَلَّنَا نَعْرِفُ مِنْهُمْ",uz:"balki ulardan bilib olarimiz"},{ar:"مَا لَمْ يَعْرِفْهُ ابْنُ الْأَيْهَمِ",uz:"Ibn al-Ayham bilmagan narsani"}],full_uz:"Balki ulardan Ibn al-Ayham bilmagan narsani bilib olarmiz.",note:null},
{num:277,time:"00:22:50,220 --> 00:22:53,180",arabic:"أَمَّا الْأَمْرُ الثَّانِي يَا مَوْلَايَ",segs:[{ar:"أَمَّا الْأَمْرُ الثَّانِي",uz:"ikkinchi masalaga kelsak"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ikkinchi masalaga kelsak, hazratim...",note:null},
{num:278,time:"00:22:53,180 --> 00:22:57,580",arabic:"فَهُوَ أَنْ نَأْتِيَ بِهَيْهِ ابْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ",segs:[{ar:"فَهُوَ أَنْ نَأْتِيَ بِهَيْهِ",uz:"u esa Hayh ibn Abdulloh Talibiyni olib kelish"},{ar:"ابْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ",uz:"ibn Abdulloh at-Tolibiy"}],full_uz:"Ikkinchisi, Hayh ibn Abdulloh at-Tolibiyni olib kelish.",note:null},
{num:279,time:"00:22:57,580 --> 00:22:59,779",arabic:"وَنَضَعَهُ أَمَامَ أَعْيُنِنَا",segs:[{ar:"وَنَضَعَهُ",uz:"va uni joylashtiramiz"},{ar:"أَمَامَ أَعْيُنِنَا",uz:"ko'z o'ngimizda"}],full_uz:"Va uni ko'z o'ngimizda saqlaymiz.",note:null},
{num:280,time:"00:22:59,779 --> 00:23:05,259",arabic:"فَهُوَ كَبِيرُهُمْ وَمِنْ دُونِهِ لَا يَعْرِفُونَ سَبِيلًا وَلَا يَعْرِفُونَ كَيْفَ يَتَصَرَّفُونَ",segs:[{ar:"فَهُوَ كَبِيرُهُمْ",uz:"u ularning kattasi"},{ar:"وَمِنْ دُونِهِ",uz:"usiz"},{ar:"لَا يَعْرِفُونَ سَبِيلًا",uz:"ular yo'l topa olmaydilar"},{ar:"وَلَا يَعْرِفُونَ كَيْفَ يَتَصَرَّفُونَ",uz:"nima qilishni ham bilmaydilar"}],full_uz:"U ularning kattasi; usiz ular na yo'l topa oladilar, na nima qilishni biladilar.",note:null},
{num:281,time:"00:23:05,259 --> 00:23:16,220",arabic:"هَذَا رَأْيُ الْحَاذِقِ يَا يَحْيَى",segs:[{ar:"هَذَا رَأْيُ الْحَاذِقِ",uz:"bu zukko kishining fikri"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Bu zukko kishining fikri, ey Yahyo.",note:"حَاذِقٌ — zukko, mohir."},
{num:282,time:"00:23:16,220 --> 00:23:20,680",arabic:"دَعِ الطَّالِبِيَّةَ تَحْتَ عَيْنِ ابْنِكَ",segs:[{ar:"دَعِ الطَّالِبِيَّةَ",uz:"Tolibiylarni qoldir"},{ar:"تَحْتَ عَيْنِ ابْنِكَ",uz:"o'g'lingning nazorati ostida"}],full_uz:"Tolibiylarni o'g'lingning nazorati ostida qoldir.",note:null},
{num:283,time:"00:23:20,680 --> 00:23:25,400",arabic:"وَلْتُسْتَأْصَلْ شَأْفَةُ هَؤُلَاءِ الْمَارِقِينَ",segs:null,full_uz:"Bu isyonchilarning ildizi quritilsin.",note:"اسْتَأْصَلَ شَأْفَةَ — ildizini quritmoq, butunlay yo'q qilmoq."},
{num:284,time:"00:23:25,400 --> 00:23:31,140",arabic:"الْغَفْلَةُ مَقْتَلُ اللَّبِيبِ يَا يَحْيَى",segs:[{ar:"الْغَفْلَةُ مَقْتَلُ اللَّبِيبِ",uz:"g'aflat zukko kishining halokatidir"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"G'aflat zukko kishining halokatidir, ey Yahyo.",note:"مَقْتَلٌ — halokat joyi, halokat sababi; اللَّبِيبُ — zukko kishi."},
{num:285,time:"00:23:31,140 --> 00:23:34,100",arabic:"جَعْفَرٌ وَأَبُو جَعْفَرٍ",segs:null,full_uz:"Ja'far va Abu Ja'far.",note:null},
{num:286,time:"00:23:34,100 --> 00:23:36,900",arabic:"طَوْعُ بَنَانِكَ يَا مَوْلَايَ",segs:[{ar:"طَوْعُ بَنَانِكَ",uz:"barmog'ingiz ishorasida"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ja'far va Abu Ja'far barmog'ingiz ishorasida, hazratim.",note:"طَوْعُ بَنَانِهِ — uning amriga to'liq bo'ysunish."},
{num:287,time:"00:23:36,900 --> 00:23:42,560",arabic:"تَأَخَّرْتَ يَا وَلَدِي",segs:[{ar:"تَأَخَّرْتَ",uz:"kechikding"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Kechikding, ey bolam.",note:null},
{num:288,time:"00:23:42,560 --> 00:23:45,980",arabic:"أَعْتَذِرُ عَنِ التَّأَخُّرِ يَا أُمِّي",segs:[{ar:"أَعْتَذِرُ عَنِ التَّأَخُّرِ",uz:"kechikkanim uchun uzr so'rayman"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Kechikkanim uchun uzr so'rayman, onajon.",note:null},
{num:289,time:"00:23:45,980 --> 00:23:46,799",arabic:"لَا عَلَيْكَ",segs:null,full_uz:"Mayli, hechqisi yo'q.",note:null},
{num:290,time:"00:23:46,799 --> 00:23:48,779",arabic:"مَا بِكَ يَا وَلَدِي",segs:[{ar:"مَا بِكَ",uz:"senga nima bo'ldi"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Senga nima bo'ldi, ey bolam?",note:null},
{num:291,time:"00:23:48,779 --> 00:23:51,480",arabic:"لِمَ أَنْتَ جَهْمُ الْوَجْهِ؟",segs:null,full_uz:"Nega yuzing tund?",note:"جَهْمُ الْوَجْهِ — yuzi tund, qovog'i soliq."},
{num:292,time:"00:23:51,480 --> 00:23:52,639",arabic:"لَا شَيْءَ",segs:null,full_uz:"Hech narsa.",note:null},
{num:293,time:"00:23:52,639 --> 00:23:54,420",arabic:"عُذْرًا قَطَعْتُ عَلَيْكَ نَوْمَكَ",segs:[{ar:"عُذْرًا",uz:"uzr"},{ar:"قَطَعْتُ عَلَيْكَ نَوْمَكَ",uz:"uyqungni bo'lib yubordim"}],full_uz:"Uzr, uyqungni bo'lib yubordim.",note:null},
{num:294,time:"00:23:54,420 --> 00:23:56,519",arabic:"وَأَنَّ لِيَ النَّوْمَ وَأَنْتَ غَائِبٌ",segs:[{ar:"وَأَنَّ لِيَ النَّوْمَ",uz:"qanday uxlay olaman"},{ar:"وَأَنْتَ غَائِبٌ",uz:"sen yo'q bo'lsang"}],full_uz:"Sen yo'q bo'lsang, qanday uxlay olaman?",note:null},
{num:295,time:"00:23:56,519 --> 00:23:59,980",arabic:"لَمْ تَقُلْ لِي لِمَاذَا تَأَخَّرْتَ؟",segs:[{ar:"لَمْ تَقُلْ لِي",uz:"menga aytmading"},{ar:"لِمَاذَا تَأَخَّرْتَ؟",uz:"nega kechikkaningni"}],full_uz:"Nega kechikkaningni menga aytmading?",note:null},
{num:296,time:"00:23:59,980 --> 00:24:01,980",arabic:"سَأُخْبِرُكِ بِذَلِكَ لَاحِقًا",segs:[{ar:"سَأُخْبِرُكِ بِذَلِكَ",uz:"buni senga aytaman"},{ar:"لَاحِقًا",uz:"keyinroq"}],full_uz:"Buni senga keyinroq aytaman.",note:null},
{num:297,time:"00:24:01,980 --> 00:24:04,920",arabic:"إِذَنْ دَعِينِي فَأَنَا مُتْعَبٌ وَأُرِيدُ أَنْ أَخْلُدَ إِلَى النَّوْمِ",segs:[{ar:"إِذَنْ دَعِينِي",uz:"unda meni qo'yib yubor"},{ar:"فَأَنَا مُتْعَبٌ",uz:"chunki men charchadim"},{ar:"وَأُرِيدُ أَنْ أَخْلُدَ إِلَى النَّوْمِ",uz:"va uxlamoqchiman"}],full_uz:"Unda meni qo'yib yubor, chunki charchadim va uxlamoqchiman.",note:"خَلَدَ إِلَى النَّوْمِ — uyquga ketmoq."},
{num:298,time:"00:24:18,779 --> 00:24:22,000",arabic:"مَا بِكَ يَا وَلَدِي؟",segs:[{ar:"مَا بِكَ",uz:"senga nima bo'ldi"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Senga nima bo'ldi, ey bolam?",note:null},
{num:299,time:"00:24:22,000 --> 00:24:23,960",arabic:"أَتَشْكُو مِنْ شَيْءٍ؟",segs:[{ar:"أَتَشْكُو",uz:"shikoyating bormi"},{ar:"مِنْ شَيْءٍ",uz:"biror narsadan"}],full_uz:"Biror narsadan shikoyating bormi?",note:null},
{num:300,time:"00:24:23,960 --> 00:24:25,240",arabic:"لَا يَا أُمِّي",segs:[{ar:"لَا",uz:"yo'q"},{ar:"يَا أُمِّي",uz:"onajon"}],full_uz:"Yo'q, onajon.",note:null},
{num:301,time:"00:24:25,240 --> 00:24:29,119",arabic:"إِنَّمَا هُوَ أَمْرٌ أُرِيدُ أَنْ أَتَثَبَّتَ مِنْهُ أَوَّلًا",segs:[{ar:"إِنَّمَا هُوَ أَمْرٌ",uz:"bu shunchaki bir masala"},{ar:"أُرِيدُ أَنْ أَتَثَبَّتَ مِنْهُ",uz:"men avval uni aniqlab olmoqchiman"}],full_uz:"Bu shunchaki bir masala, avval uni aniqlab olmoqchiman.",note:null},
{num:302,time:"00:24:29,119 --> 00:24:30,619",arabic:"وَسَأُخْبِرُكِ بِهِ إِنْ شَاءَ اللَّهُ",segs:[{ar:"وَسَأُخْبِرُكِ بِهِ",uz:"va buni senga aytaman"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"inshaalloh"}],full_uz:"Inshaalloh, buni senga aytaman.",note:null},
{num:303,time:"00:24:30,619 --> 00:24:31,720",arabic:"لَا تَقْلَقْ",segs:null,full_uz:"Xavotir olma.",note:null},
{num:304,time:"00:24:31,720 --> 00:24:35,079",arabic:"الْآنَ أَنَا مُتْعَبٌ قَلِيلًا",segs:[{ar:"الْآنَ",uz:"hozir"},{ar:"أَنَا مُتْعَبٌ قَلِيلًا",uz:"biroz charchadim"}],full_uz:"Hozir biroz charchadim.",note:null},
{num:305,time:"00:24:35,079 --> 00:24:36,740",arabic:"تُصْبِحِينَ عَلَى خَيْرٍ",segs:null,full_uz:"Xayrli tun.",note:null},
{num:306,time:"00:24:36,740 --> 00:24:41,480",arabic:"تُصْبِحُ عَلَى خَيْرٍ",segs:null,full_uz:"Xayrli tun.",note:null},
{num:307,time:"00:24:48,779 --> 00:25:18,759",arabic:"اشْتَرِكُوا فِي الْقَنَاةِ",segs:null,full_uz:null,note:null},
{num:308,time:"00:25:18,779 --> 00:25:21,960",arabic:"فَوْزٌ",segs:null,full_uz:"Fawz.",note:null},
{num:309,time:"00:25:21,960 --> 00:25:24,339",arabic:"هُوَ اسْمُكِ عَلَى مَا أَظُنُّ",segs:[{ar:"هُوَ اسْمُكِ",uz:"bu isming"},{ar:"عَلَى مَا أَظُنُّ",uz:"menimcha"}],full_uz:"Menimcha, bu sening isming.",note:null},
{num:310,time:"00:25:24,339 --> 00:25:26,940",arabic:"هَا قَدْ عَرَفْنَا عَنْكِ شَيْئًا",segs:[{ar:"هَا قَدْ عَرَفْنَا",uz:"mana bilib oldik"},{ar:"عَنْكِ شَيْئًا",uz:"sen haqingda bir narsani"}],full_uz:"Mana, sen haqingda bir narsani bilib oldik.",note:null},
{num:311,time:"00:25:26,940 --> 00:25:29,460",arabic:"هَذَا الْمُشْطُ لِي وَمِنْ حُرِّ مَالِي",segs:[{ar:"هَذَا الْمُشْطُ لِي",uz:"bu taroq meniki"},{ar:"وَمِنْ حُرِّ مَالِي",uz:"o'z halol molimdan"}],full_uz:"Bu taroq meniki va uni o'z halol molimga sotib olganman.",note:null},
{num:312,time:"00:25:29,460 --> 00:25:33,480",arabic:"أَنْتِ وَكُلُّ مَا تَمْلِكِينَ مِلْكًا لِي",segs:[{ar:"أَنْتِ",uz:"sen"},{ar:"وَكُلُّ مَا تَمْلِكِينَ",uz:"va bor-buding"},{ar:"مِلْكًا لِي",uz:"meniki"}],full_uz:"Sen ham, bor-buding ham meniki.",note:null},
{num:313,time:"00:25:33,480 --> 00:25:34,779",arabic:"فَهِمْتِ؟",segs:null,full_uz:"Tushundingmi?",note:null},
{num:314,time:"00:25:36,680 --> 00:25:37,779",arabic:"مَا قِصَّةُ هَذَا الْمُشْطِ؟",segs:null,full_uz:"Bu taroqning tarixi nima?",note:null},
{num:315,time:"00:25:38,779 --> 00:25:40,099",arabic:"وَمَا تُعْنِيكَ قِصَّتُهُ؟",segs:[{ar:"وَمَا تُعْنِيكَ",uz:"senga nima"},{ar:"قِصَّتُهُ",uz:"uning tarixidan"}],full_uz:"Uning tarixidan senga nima?",note:null},
{num:316,time:"00:25:40,099 --> 00:25:41,960",arabic:"جَاوِبِي عَلَى قَدْرِ السُّؤَالِ",segs:[{ar:"جَاوِبِي",uz:"javob ber"},{ar:"عَلَى قَدْرِ السُّؤَالِ",uz:"savolga yarasha"}],full_uz:"Savolga yarasha javob ber.",note:"عَلَى قَدْرِ — miqdoriga, darajasiga yarasha."},
{num:317,time:"00:25:41,960 --> 00:25:43,779",arabic:"مَا قِصَّةُ هَذَا الْمُشْطِ؟",segs:null,full_uz:"Bu taroqning tarixi nima?",note:null},
{num:318,time:"00:25:45,920 --> 00:25:47,019",arabic:"هَدِيَّةٌ مِنْ أَبِي",segs:null,full_uz:"Otamdan sovg'a.",note:null},
{num:319,time:"00:25:48,779 --> 00:25:49,899",arabic:"قَدْ صَنَعَهُ بِيَدِهِ",segs:[{ar:"قَدْ صَنَعَهُ",uz:"uni yasagan"},{ar:"بِيَدِهِ",uz:"o'z qo'li bilan"}],full_uz:"Uni o'z qo'li bilan yasagan.",note:null},
{num:320,time:"00:25:49,899 --> 00:25:53,779",arabic:"أَعْطِنِيهِ",segs:null,full_uz:"Uni menga ber.",note:null},
{num:321,time:"00:25:54,720 --> 00:25:57,779",arabic:"سَأَحْتَفِظُ بِهِ إِلَى أَنْ تَلِينَ رَأْسُكِ",segs:[{ar:"سَأَحْتَفِظُ بِهِ",uz:"uni saqlab turaman"},{ar:"إِلَى أَنْ تَلِينَ رَأْسُكِ",uz:"boshing egilguncha"}],full_uz:"Boshing egilguncha uni saqlab turaman.",note:"لَانَ رَأْسُهُ — bo'ysunmoq, bosh egmoq."},
{num:322,time:"00:25:58,299 --> 00:26:03,619",arabic:"وَإِنْ أَحْسَنْتِ التَّصَرُّفَ سَأُعِيدُهُ إِلَيْكِ",segs:[{ar:"وَإِنْ أَحْسَنْتِ التَّصَرُّفَ",uz:"agar o'zingni yaxshi tutsang"},{ar:"سَأُعِيدُهُ إِلَيْكِ",uz:"uni senga qaytaraman"}],full_uz:"Agar o'zingni yaxshi tutsang, uni senga qaytaraman.",note:null},
{num:323,time:"00:26:03,619 --> 00:26:04,839",arabic:"لَيْسَ هَذَا فَقَطْ",segs:null,full_uz:"Faqat bu emas.",note:null},
{num:324,time:"00:26:04,839 --> 00:26:08,680",arabic:"بَلْ سَأَجْعَلُكِ تَعِيشِينَ نَعِيمًا لَمْ تَعْرِفِيهِ مِنْ قَبْلُ",segs:[{ar:"بَلْ سَأَجْعَلُكِ تَعِيشِينَ نَعِيمًا",uz:"balki seni farovon hayotda yashataman"},{ar:"لَمْ تَعْرِفِيهِ مِنْ قَبْلُ",uz:"ilgari bilmagan"}],full_uz:"Balki seni ilgari bilmagan farovon hayotda yashataman.",note:"نَعِيمٌ — farovonlik, rohat-farog'at."},
{num:325,time:"00:26:08,680 --> 00:26:12,759",arabic:"الْمُهِمُّ أَنْ تُحْسِنِي سُلُوكَكِ أَمَامَ مَنْ سَيَشْتَرِيكِ",segs:[{ar:"الْمُهِمُّ",uz:"muhimi"},{ar:"أَنْ تُحْسِنِي سُلُوكَكِ",uz:"o'zingni yaxshi tutishing"},{ar:"أَمَامَ مَنْ سَيَشْتَرِيكِ",uz:"seni sotib oladigan odam oldida"}],full_uz:"Muhimi, seni sotib oladigan odam oldida o'zingni yaxshi tutishing.",note:null},
{num:326,time:"00:26:12,759 --> 00:26:15,039",arabic:"أَنَا لَسْتُ جَارِيَةً",segs:null,full_uz:"Men cho'ri emasman.",note:"جَارِيَةٌ — cho'ri, qul qiz."},
{num:327,time:"00:26:15,039 --> 00:26:15,920",arabic:"أَنَا حُرَّةٌ",segs:null,full_uz:"Men hurman.",note:null},
{num:328,time:"00:26:15,920 --> 00:26:19,519",arabic:"وَالْحُرُّ لَا يُبَاعُ وَلَا يُشْتَرَى بِكُنُوزِ الدُّنْيَا كُلِّهَا",segs:[{ar:"وَالْحُرُّ لَا يُبَاعُ وَلَا يُشْتَرَى",uz:"hur odam sotilmaydi ham sotib olinmaydi"},{ar:"بِكُنُوزِ الدُّنْيَا كُلِّهَا",uz:"butun dunyo xazinalariga ham"}],full_uz:"Hur odam butun dunyo xazinalariga ham sotilmaydi va sotib olinmaydi.",note:null},
{num:329,time:"00:26:19,519 --> 00:26:21,960",arabic:"هَلْ فَهِمْتِ؟ سَأَبْقَى حُرَّةً",segs:[{ar:"هَلْ فَهِمْتِ؟",uz:"tushundingmi?"},{ar:"سَأَبْقَى حُرَّةً",uz:"men hur bo'lib qolaman"}],full_uz:"Tushundingmi? Men hur bo'lib qolaman.",note:null},
{num:330,time:"00:26:21,960 --> 00:26:24,279",arabic:"الْأَيَّامُ بَيْنَنَا يَا فَوْزُ",segs:[{ar:"الْأَيَّامُ بَيْنَنَا",uz:"hali kunlar oldinda"},{ar:"يَا فَوْزُ",uz:"ey Fawz"}],full_uz:"Hali kunlar oldinda, ey Fawz.",note:null},
{num:331,time:"00:26:24,279 --> 00:26:26,120",arabic:"الْأَيَّامُ بَيْنَنَا",segs:null,full_uz:"Hali kunlar oldinda.",note:null},
{num:332,time:"00:26:26,120 --> 00:26:29,200",arabic:"مَا زِلْتُ إِلَى هَذِهِ اللَّحْظَةِ أُعَامِلُكِ بِلِينٍ",segs:[{ar:"مَا زِلْتُ إِلَى هَذِهِ اللَّحْظَةِ",uz:"shu paytgacha hamon"},{ar:"أُعَامِلُكِ بِلِينٍ",uz:"senga yumshoqlik bilan muomala qilyapman"}],full_uz:"Shu paytgacha hamon senga yumshoqlik bilan muomala qilyapman.",note:"بِلِينٍ — yumshoqlik bilan, muloyimlik bilan."},
{num:333,time:"00:26:29,200 --> 00:26:32,620",arabic:"وَلَكِنَّ الْأَيَّامَ الْقَادِمَةَ سَتَرَيْنَ مِنِّي مَا لَمْ تَعْرِفِيهِ",segs:[{ar:"وَلَكِنَّ الْأَيَّامَ الْقَادِمَةَ",uz:"ammo kelgusi kunlarda"},{ar:"سَتَرَيْنَ مِنِّي",uz:"mendan ko'rasan"},{ar:"مَا لَمْ تَعْرِفِيهِ",uz:"ilgari bilmagan narsalaringni"}],full_uz:"Ammo kelgusi kunlarda mendan ilgari bilmagan narsalaringni ko'rasan.",note:null},
{num:334,time:"00:26:32,620 --> 00:26:33,279",arabic:"تَعَالَ",segs:null,full_uz:"Kel.",note:null},
{num:335,time:"00:26:33,279 --> 00:26:36,320",arabic:"افْعَلْ بِي مَا تَشَاءُ",segs:[{ar:"افْعَلْ بِي",uz:"menga qil"},{ar:"مَا تَشَاءُ",uz:"xohlaganingni"}],full_uz:"Menga xohlaganingni qil.",note:null},
{num:336,time:"00:26:36,320 --> 00:26:38,320",arabic:"أَنَا حُرَّةٌ",segs:null,full_uz:"Men hurman.",note:null},
{num:337,time:"00:26:38,320 --> 00:26:40,000",arabic:"حُرَّةٌ",segs:null,full_uz:"Hurman.",note:null},
{num:338,time:"00:26:45,920 --> 00:26:49,080",arabic:"وَمَا الْمُشْكِلُ فِيمَا سَمِعْتَ يَا أَحْمَدُ",segs:[{ar:"وَمَا الْمُشْكِلُ فِيمَا سَمِعْتَ",uz:"eshitgan narsangda nima muammo bor"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Eshitgan narsangda nima muammo bor, ey Ahmad?",note:null},
{num:339,time:"00:26:49,080 --> 00:26:53,759",arabic:"أَلَيْسَ مِنْ مَهَامِّ الْوُلَاةِ وَالْعُمَّالِ مَعْرِفَةُ كُلِّ كَبِيرَةٍ وَصَغِيرَةٍ",segs:[{ar:"أَلَيْسَ مِنْ مَهَامِّ الْوُلَاةِ وَالْعُمَّالِ",uz:"voliylar va amaldorlarning vazifalaridan biri emasmi"},{ar:"مَعْرِفَةُ كُلِّ كَبِيرَةٍ وَصَغِيرَةٍ",uz:"har bir katta-kichik narsani bilish"}],full_uz:"Voliylar va amaldorlarning vazifalaridan biri har bir katta-kichik narsani bilish emasmi?",note:null},
{num:340,time:"00:26:53,759 --> 00:26:58,519",arabic:"فِي دَوْلَةِ الْخِلَافَةِ الَّتِي يَتَرَبَّصُ بِهَا الْخَارِجُونَ وَالْمَارِقُونَ مِنْ كُلِّ حَدَبٍ وَصَوْبٍ",segs:[{ar:"فِي دَوْلَةِ الْخِلَافَةِ",uz:"xalifalik davlatida"},{ar:"الَّتِي يَتَرَبَّصُ بِهَا الْخَارِجُونَ وَالْمَارِقُونَ",uz:"unga isyonchilar va itoatdan chiqqanlar poylab turgan"},{ar:"مِنْ كُلِّ حَدَبٍ وَصَوْبٍ",uz:"har tomondan"}],full_uz:"Isyonchilar va itoatdan chiqqanlar har tomondan poylab turgan xalifalik davlatida.",note:"مِنْ كُلِّ حَدَبٍ وَصَوْبٍ — har tomondan, turli taraflardan."},
{num:341,time:"00:26:58,519 --> 00:27:03,240",arabic:"وَمَا فَعَلَ ذَلِكَ إِلَّا لِحِفْظِ الدِّينِ وَالدُّنْيَا مِنَ الْحَاقِدِينَ وَأَهْلِ الْفِتَنِ",segs:[{ar:"وَمَا فَعَلَ ذَلِكَ إِلَّا",uz:"u buni faqat"},{ar:"لِحِفْظِ الدِّينِ وَالدُّنْيَا",uz:"din va dunyoni asrash uchun"},{ar:"مِنَ الْحَاقِدِينَ وَأَهْلِ الْفِتَنِ",uz:"adovatli kimsalar va fitnachilardan"}],full_uz:"U buni faqat din va dunyoni adovatli kimsalar hamda fitnachilardan asrash uchun qildi.",note:null},
{num:342,time:"00:27:03,240 --> 00:27:09,240",arabic:"ثُمَّ أَنَا مِنْ وَاجِبِي وَوَاجِبُ غَيْرِي أَيْضًا أَنْ نُسَاعِدَهُمْ عَلَى حِفْظِ أَمْنِ وَأَمَانِ الْبِلَادِ",segs:[{ar:"ثُمَّ أَنَا",uz:"bundan tashqari, men"},{ar:"مِنْ وَاجِبِي وَوَاجِبُ غَيْرِي أَيْضًا",uz:"va boshqalarning ham burchi"},{ar:"أَنْ نُسَاعِدَهُمْ",uz:"ularga yordam berish"},{ar:"عَلَى حِفْظِ أَمْنِ وَأَمَانِ الْبِلَادِ",uz:"mamlakatning tinchligi va xavfsizligini saqlashda"}],full_uz:"Bundan tashqari, men va boshqalarning ham burchi — mamlakatning tinchligi va xavfsizligini saqlashda ularga yordam berish.",note:null},
{num:343,time:"00:27:09,240 --> 00:27:14,940",arabic:"لَا أَدْرِي، عَمَّا رُبَّمَا كَانَ كَلَامُكَ صَحِيحًا",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"رُبَّمَا كَانَ كَلَامُكَ صَحِيحًا",uz:"ehtimol gaping to'g'ridir"}],full_uz:"Bilmayman, ehtimol gaping to'g'ridir.",note:null},
{num:344,time:"00:27:14,940 --> 00:27:18,160",arabic:"لَا عَلَيْكَ أَنْتَ يَا أَحْمَدُ",segs:[{ar:"لَا عَلَيْكَ",uz:"xavotir olma"},{ar:"أَنْتَ يَا أَحْمَدُ",uz:"sen, ey Ahmad"}],full_uz:"Xavotir olma, ey Ahmad.",note:null},
{num:345,time:"00:27:18,160 --> 00:27:20,460",arabic:"دَعْ أُمُورَ الدَّوْلَةِ لِرِجَالِهَا",segs:[{ar:"دَعْ أُمُورَ الدَّوْلَةِ",uz:"davlat ishlarini qo'yib ber"},{ar:"لِرِجَالِهَا",uz:"uning odamlariga"}],full_uz:"Davlat ishlarini uning mas'ul odamlariga qo'yib ber.",note:null},
{num:346,time:"00:27:20,460 --> 00:27:23,480",arabic:"أَمْرُ الدَّوْلَةِ بَعْضُ أُمُورِنَا يَا عَمَاهُ",segs:[{ar:"أَمْرُ الدَّوْلَةِ",uz:"davlat ishi"},{ar:"بَعْضُ أُمُورِنَا",uz:"bizning ham ishlarimizdan biri"},{ar:"يَا عَمَاهُ",uz:"ey amakim"}],full_uz:"Davlat ishi bizning ham ishlarimizdan biri, ey amakim.",note:null},
{num:347,time:"00:27:23,480 --> 00:27:24,519",arabic:"أَحْمَدُ",segs:null,full_uz:"Ahmad.",note:null},
{num:348,time:"00:27:24,519 --> 00:27:27,519",arabic:"لَا أَقْدِرُ عَلَى حِجَاجِكَ",segs:[{ar:"لَا أَقْدِرُ",uz:"qodir emasman"},{ar:"عَلَى حِجَاجِكَ",uz:"sen bilan bahslashishga"}],full_uz:"Sen bilan bahslashishga qodir emasman.",note:"حِجَاجٌ — bahslashish, dalil keltirish."},
{num:349,time:"00:27:27,519 --> 00:27:28,799",arabic:"قَبْلَ أَنْ تَفْهَمَ",segs:null,full_uz:"Tushunishingdan oldin.",note:null},
{num:350,time:"00:27:28,799 --> 00:27:35,200",arabic:"خُذْ كِتَابِي هَذَا وَأَوْدِعْهُ فِي طَرِيقِكَ دِيوَانَ الْوَالِي",segs:[{ar:"خُذْ كِتَابِي هَذَا",uz:"mana bu maktubimni ol"},{ar:"وَأَوْدِعْهُ",uz:"va uni topshir"},{ar:"فِي طَرِيقِكَ دِيوَانَ الْوَالِي",uz:"yo'lingda voliy devoniga"}],full_uz:"Mana bu maktubimni ol va yo'lingda voliy devoniga topshir.",note:"دِيوَانُ الْوَالِي — voliy devoni, idorasi."},
{num:351,time:"00:27:35,200 --> 00:27:37,240",arabic:"خَيْرًا إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Yaxshilik bo'lsin, inshaalloh.",note:null},
{num:352,time:"00:27:37,240 --> 00:27:38,320",arabic:"مَا الْأَمْرُ؟",segs:null,full_uz:"Nima bo'ldi?",note:null},
{num:353,time:"00:27:38,320 --> 00:27:39,120",arabic:"لَا عَلَيْكَ أَمَتْ",segs:null,full_uz:"Hechqisi yo'q, xizmatchi.",note:null},
{num:354,time:"00:27:39,120 --> 00:27:40,940",arabic:"أَوْدِعْهُ فِي الدِّيوَانِ وَحَسْبُ",segs:[{ar:"أَوْدِعْهُ فِي الدِّيوَانِ",uz:"uni devonga topshir"},{ar:"وَحَسْبُ",uz:"shuning o'zi kifoya"}],full_uz:"Uni devonga topshir, shuning o'zi kifoya.",note:null},
{num:355,time:"00:27:40,940 --> 00:27:44,320",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:356,time:"00:27:44,319 --> 00:27:45,679",arabic:"وَعَلَيْكَ السَّلَامُ",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:357,time:"00:27:45,680 --> 00:28:15,660",arabic:"الْمُتَرْجِمُ لِلْقَنَاةِ",segs:null,full_uz:null,note:null},
{num:358,time:"00:28:15,680 --> 00:28:18,920",arabic:"غَفَرَ اللَّهُ لَكَ يَا عَمَّ",segs:[{ar:"غَفَرَ اللَّهُ لَكَ",uz:"Alloh seni kechirsin"},{ar:"يَا عَمَّ",uz:"ey amaki"}],full_uz:"Alloh seni kechirsin, ey amaki.",note:null},
{num:359,time:"00:28:18,920 --> 00:28:22,560",arabic:"مَا شَأْنِي أَنَا بِالْوَالِي",segs:[{ar:"مَا شَأْنِي أَنَا",uz:"mening nima aloqam bor"},{ar:"بِالْوَالِي",uz:"voliy bilan"}],full_uz:"Mening voliy bilan nima aloqam bor?",note:null},
{num:360,time:"00:28:22,560 --> 00:28:37,880",arabic:"أَتَعْلَمُ أَنَّ مَنْ يُعِينُ الظَّالِمَ",segs:[{ar:"أَتَعْلَمُ",uz:"bilasizmi"},{ar:"أَنَّ مَنْ يُعِينُ الظَّالِمَ",uz:"zolimga yordam bergan kishi"}],full_uz:"Zolimga yordam bergan kishi...",note:null},
{num:361,time:"00:28:37,880 --> 00:28:40,640",arabic:"فَهُوَ ظَالِمٌ مِثْلُهُ؟",segs:null,full_uz:"Uning o'zi ham unga o'xshash zolim bo'ladi, bilasizmi?",note:null},
{num:362,time:"00:28:40,640 --> 00:28:40,980",arabic:"أَعْلَمُ",segs:null,full_uz:"Bilaman.",note:null},
{num:363,time:"00:28:40,980 --> 00:28:44,920",arabic:"حَسِبْتُكَ لَا تَعْلَمُ",segs:[{ar:"حَسِبْتُكَ",uz:"men seni deb o'ylagandim"},{ar:"لَا تَعْلَمُ",uz:"bilmaydi"}],full_uz:"Men seni bilmaydi deb o'ylagandim.",note:null},
{num:364,time:"00:28:44,920 --> 00:29:11,740",arabic:"رُبَّمَا كَانَ لِعَمِّكَ الْعُذْرُ فِيمَا يَفْعَلُهُ",segs:[{ar:"رُبَّمَا كَانَ لِعَمِّكَ الْعُذْرُ",uz:"ehtimol amakingning uzri bordir"},{ar:"فِيمَا يَفْعَلُهُ",uz:"qilayotgan ishida"}],full_uz:"Ehtimol, amaking qilayotgan ishida uzri bordir.",note:null},
{num:365,time:"00:29:11,740 --> 00:29:18,579",arabic:"إِذْ يَرَى أَنَّهُ بِذَلِكَ يَنْصَحُ الْوُلَاةَ وَيُنَبِّهُهُمْ إِلَى خَطَرٍ هُوَ يَرَى",segs:[{ar:"إِذْ يَرَى",uz:"chunki u shunday deb hisoblaydi"},{ar:"أَنَّهُ بِذَلِكَ يَنْصَحُ الْوُلَاةَ",uz:"shu bilan voliylarga nasihat qilayotganini"},{ar:"وَيُنَبِّهُهُمْ إِلَى خَطَرٍ",uz:"va ularni bir xavfdan ogohlantirayotganini"},{ar:"هُوَ يَرَى",uz:"u deb biladigan"}],full_uz:"Chunki u shu bilan voliylarga nasihat qilayotganini va ularni o'zi xavf deb bilgan narsadan ogohlantirayotganini o'ylaydi.",note:null},
{num:366,time:"00:29:18,579 --> 00:29:23,220",arabic:"وَلَكِنْ أَنْتَ لَا شَأْنَ لَكَ بِذَلِكَ يَا وَالِدِي",segs:[{ar:"وَلَكِنْ أَنْتَ لَا شَأْنَ لَكَ بِذَلِكَ",uz:"ammo buning senga aloqasi yo'q"},{ar:"يَا وَالِدِي",uz:"ey otajon"}],full_uz:"Ammo buning senga aloqasi yo'q, ey otajon.",note:null},
{num:367,time:"00:29:23,220 --> 00:29:27,039",arabic:"أَجَلْ يَا أُمِّي وَلَوْلَا كَرَاهِيَةٌ فِي نَفْسِي أَجِدُهَا",segs:[{ar:"أَجَلْ يَا أُمِّي",uz:"ha, onajon"},{ar:"وَلَوْلَا كَرَاهِيَةٌ فِي نَفْسِي أَجِدُهَا",uz:"ichimdagi norozilik bo'lmaganida"}],full_uz:"Ha, onajon. Ichimdagi norozilik bo'lmaganida...",note:null},
{num:368,time:"00:29:27,039 --> 00:29:30,319",arabic:"لَمَا تَرَكْتُ الْكِتَابَ عِنْدِي وَلَمْ أُوصِلْهُ إِلَى الْوَالِي كَمَا طَلَبَ عَمِّي",segs:[{ar:"لَمَا تَرَكْتُ الْكِتَابَ عِنْدِي",uz:"maktubni o'zimda qoldirmagan bo'lardim"},{ar:"وَلَمْ أُوصِلْهُ إِلَى الْوَالِي",uz:"va uni voliyga yetkazgan bo'lardim"},{ar:"كَمَا طَلَبَ عَمِّي",uz:"amakim so'raganidek"}],full_uz:"Maktubni o'zimda qoldirib, amakim so'raganidek voliyga yetkazmay qo'ymasdim.",note:null},
{num:369,time:"00:29:37,319 --> 00:29:39,579",arabic:"هَلْ قَرَأْتَ مَا فِي الْكِتَابِ؟",segs:[{ar:"هَلْ قَرَأْتَ",uz:"o'qidingmi"},{ar:"مَا فِي الْكِتَابِ",uz:"maktub ichidagi narsani"}],full_uz:"Maktub ichidagi narsani o'qidingmi?",note:null},
{num:370,time:"00:29:39,579 --> 00:29:41,319",arabic:"أَعُوذُ بِاللَّهِ أَنْ أَفْعَلَ ذَلِكَ",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so'rayman"},{ar:"أَنْ أَفْعَلَ ذَلِكَ",uz:"bunday qilishdan"}],full_uz:"Bunday qilishdan Allohdan panoh so'rayman.",note:null},
{num:371,time:"00:29:41,319 --> 00:29:43,899",arabic:"إِنَّهُ أَمَانَةٌ وَلَا يَجُوزُ فَتْحُهَا",segs:[{ar:"إِنَّهُ أَمَانَةٌ",uz:"u omonat"},{ar:"وَلَا يَجُوزُ فَتْحُهَا",uz:"uni ochish mumkin emas"}],full_uz:"U omonat, uni ochish mumkin emas.",note:"أَمَانَةٌ — omonat."},
{num:372,time:"00:29:43,899 --> 00:29:46,119",arabic:"أَحْسَنْتَ",segs:null,full_uz:"Barakalla.",note:null},
{num:373,time:"00:29:46,119 --> 00:29:49,179",arabic:"وَبَارَكَ اللَّهُ بِكَ يَا وَلَدِي",segs:[{ar:"وَبَارَكَ اللَّهُ بِكَ",uz:"Alloh seni ham barakotli qilsin"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Alloh seni ham barakotli qilsin, ey bolam.",note:null},
{num:374,time:"00:29:49,179 --> 00:29:52,319",arabic:"وَلَكِنْ قَدْ يُعْرَفُ الْكِتَابُ مِنْ عُنْوَانِهِ",segs:[{ar:"وَلَكِنْ قَدْ يُعْرَفُ الْكِتَابُ",uz:"ammo maktubni bilib olish mumkin"},{ar:"مِنْ عُنْوَانِهِ",uz:"uning sarlavhasidan"}],full_uz:"Ammo maktubning o'zini sarlavhasidan bilib olish mumkin.",note:null},
{num:375,time:"00:29:52,319 --> 00:29:56,319",arabic:"لَا بُدَّ أَنَّ فِي الْكِتَابِ أَخْبَارَ السُّوقِ وَالْعُلَمَاءِ أَرْسَلَهَا عَمِّي إِلَى الْوَالِي",segs:[{ar:"لَا بُدَّ أَنَّ فِي الْكِتَابِ",uz:"shubhasiz maktubda"},{ar:"أَخْبَارَ السُّوقِ وَالْعُلَمَاءِ",uz:"bozor va ulamolar haqidagi xabarlar bor"},{ar:"أَرْسَلَهَا عَمِّي إِلَى الْوَالِي",uz:"amakim ularni voliyga yuborgan"}],full_uz:"Shubhasiz, maktubda bozor va ulamolar haqidagi xabarlar bor, amakim ularni voliyga yuborgan.",note:null},
{num:376,time:"00:29:56,319 --> 00:30:02,319",arabic:"وَمَا تَرَى بِشَأْنِ الْكِتَابِ؟",segs:[{ar:"وَمَا تَرَى",uz:"nima deb o'ylaysan"},{ar:"بِشَأْنِ الْكِتَابِ؟",uz:"maktub haqida"}],full_uz:"Maktub haqida nima deb o'ylaysan?",note:null},
{num:377,time:"00:30:05,879 --> 00:30:09,539",arabic:"أَرَى أَنْ أُعِيدَهُ إِلَى عَمِّي وَأُخْبِرَهُ أَنْ لَا شَأْنَ لِي بِذَلِكَ",segs:[{ar:"أَرَى أَنْ أُعِيدَهُ إِلَى عَمِّي",uz:"uni amakimga qaytarishim kerak deb o'ylayman"},{ar:"وَأُخْبِرَهُ أَنْ لَا شَأْنَ لِي بِذَلِكَ",uz:"va unga buning menga aloqasi yo'qligini aytaman"}],full_uz:"Uni amakimga qaytarib, unga buning menga aloqasi yo'qligini aytaman deb o'ylayman.",note:null},
{num:378,time:"00:30:09,539 --> 00:30:13,500",arabic:"كَمَا أَنَّنِي سَأَتْرُكُ الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ",segs:[{ar:"كَمَا أَنَّنِي سَأَتْرُكُ الْعَمَلَ",uz:"bundan tashqari, ishni tashlayman"},{ar:"فِي بَيْتِ الْحِكْمَةِ",uz:"Hikmat uyidagi"}],full_uz:"Bundan tashqari, Hikmat uyidagi ishimni tashlayman.",note:null},
{num:379,time:"00:30:13,500 --> 00:30:16,960",arabic:"لِأَنَّنِي لَنْ أَسْتَطِيعَ أَنْ أُوَفِّقَ بَيْنَ الْعَمَلِ وَطَلَبِي لِلْعِلْمِ",segs:[{ar:"لِأَنَّنِي لَنْ أَسْتَطِيعَ",uz:"chunki men qodir bo'lmayman"},{ar:"أَنْ أُوَفِّقَ بَيْنَ الْعَمَلِ",uz:"ish bilan uyg'unlashtirishga"},{ar:"وَطَلَبِي لِلْعِلْمِ",uz:"ilm talab qilishimni"}],full_uz:"Chunki ish bilan ilm talab qilishimni birga olib borishga qodir bo'lmayman.",note:null},
{num:380,time:"00:30:16,960 --> 00:30:18,139",arabic:"أَمَّا أَنَا",segs:null,full_uz:"Menga kelsak.",note:null},
{num:381,time:"00:30:18,139 --> 00:30:21,619",arabic:"فَلِي رَأْيٌ آخَرُ بِشَأْنِهِ",segs:[{ar:"فَلِي رَأْيٌ آخَرُ",uz:"mening boshqa fikrim bor"},{ar:"بِشَأْنِهِ",uz:"bu haqda"}],full_uz:"Bu haqda mening boshqa fikrim bor.",note:null},
{num:382,time:"00:30:21,619 --> 00:30:24,500",arabic:"مَا هُوَ؟",segs:null,full_uz:"Qanday?",note:null},
{num:383,time:"00:30:39,539 --> 00:31:02,299",arabic:"إِلَى مَتَى سَتَبْقَى هَكَذَا يَا فَرَجُ؟",segs:[{ar:"إِلَى مَتَى سَتَبْقَى هَكَذَا",uz:"qachongacha shunday qolasan"},{ar:"يَا فَرَجُ",uz:"ey Faraj"}],full_uz:"Qachongacha shunday qolasan, ey Faraj?",note:null},
{num:384,time:"00:31:02,299 --> 00:31:05,440",arabic:"الْخَوْفُ يَسْكُنُكَ وَالْعَوَزُ لَا يُفَارِقُكَ أَبَدًا",segs:[{ar:"الْخَوْفُ يَسْكُنُكَ",uz:"qo'rquv seni tark etmaydi"},{ar:"وَالْعَوَزُ لَا يُفَارِقُكَ أَبَدًا",uz:"muhtojlik esa seni hech qachon tark etmaydi"}],full_uz:"Qo'rquv seni tark etmaydi, muhtojlik esa seni hech qachon qo'yib yubormaydi.",note:"الْعَوَزُ — muhtojlik, nochorlik."},
{num:385,time:"00:31:05,440 --> 00:31:08,440",arabic:"أَلَيْسَ مِنْ أَمَلٍ فِي تَغْيِيرِ حَالِكَ؟",segs:[{ar:"أَلَيْسَ مِنْ أَمَلٍ",uz:"umid yo'qmi"},{ar:"فِي تَغْيِيرِ حَالِكَ؟",uz:"ahvolingni o'zgartirishga"}],full_uz:"Ahvolingni o'zgartirishga umid yo'qmi?",note:null},
{num:386,time:"00:31:16,440 --> 00:31:17,440",arabic:"مَنْ هَذَا؟",segs:null,full_uz:"Bu kim?",note:null},
{num:387,time:"00:31:19,440 --> 00:31:20,440",arabic:"بَهْلُولٌ",segs:null,full_uz:"Bahlul.",note:null},
{num:388,time:"00:31:21,440 --> 00:31:22,440",arabic:"أَهْلًا أَهْلًا",segs:null,full_uz:"Xush kelibsan, xush kelibsan.",note:null},
{num:389,time:"00:31:23,440 --> 00:31:25,440",arabic:"تَعَالَ إِلَى النَّارِ اسْتَدْفِئْ",segs:[{ar:"تَعَالَ إِلَى النَّارِ",uz:"olov yoniga kel"},{ar:"اسْتَدْفِئْ",uz:"isin"}],full_uz:"Olov yoniga kel, isin.",note:"اسْتَدْفَأَ — isinmoq."},
{num:390,time:"00:31:26,440 --> 00:31:28,440",arabic:"هَيْ هَاتِ يَا ابْنَ أُمِّي فَرَجُ",segs:[{ar:"هَيْ هَاتِ",uz:"qani ber"},{ar:"يَا ابْنَ أُمِّي فَرَجُ",uz:"ey onamning o'g'li Faraj"}],full_uz:"Qani, ber-chi, ey onamning o'g'li Faraj.",note:null},
{num:391,time:"00:31:28,440 --> 00:31:30,440",arabic:"تَدْعُونِي إِلَى النَّارِ؟",segs:null,full_uz:"Meni olovga chorlayapsanmi?",note:null},
{num:392,time:"00:31:32,440 --> 00:31:33,440",arabic:"هَذَا هُوَ بَهْلُولٌ",segs:[{ar:"هَذَا هُوَ",uz:"mana bu"},{ar:"بَهْلُولٌ",uz:"Bahlul"}],full_uz:"Mana bu Bahlul.",note:null},
{num:393,time:"00:31:33,440 --> 00:31:34,820",arabic:"هَذَا هُوَ بَهْنُونُ",segs:[{ar:"هَذَا هُوَ",uz:"mana bu"},{ar:"بَهْنُونُ",uz:"Bahnun"}],full_uz:"Mana bu Bahnun.",note:null},
{num:394,time:"00:31:34,820 --> 00:31:37,340",arabic:"يَا بَهْنُونُ",segs:null,full_uz:"Ey Bahnun.",note:null},
{num:395,time:"00:31:37,340 --> 00:31:40,440",arabic:"وَهَلْ نَحْنُ فِي يَوْمِ الْقِيَامَةِ حَتَّى تَخْشَى دَعْوَتِي؟",segs:[{ar:"وَهَلْ نَحْنُ فِي يَوْمِ الْقِيَامَةِ",uz:"nahotki biz qiyomat kunidamiz"},{ar:"حَتَّى تَخْشَى دَعْوَتِي؟",uz:"meni da'vat qilishimdan qo'rqadigan darajada"}],full_uz:"Nahotki biz qiyomat kunidamiz, meni chaqirishimdan qo'rqyapsan?",note:null},
{num:396,time:"00:31:42,080 --> 00:31:44,539",arabic:"مَنْ يَنْظُرْ إِلَى مَوْطِئِ قَدَمَيْهِ",segs:[{ar:"مَنْ يَنْظُرْ",uz:"kim qarasa"},{ar:"إِلَى مَوْطِئِ قَدَمَيْهِ",uz:"oyoqlari qo'yiladigan joyga"}],full_uz:"Kim oyoqlari ostiga qarab yursa...",note:"مَوْطِئُ الْقَدَمِ — oyoq qo'yiladigan joy, oyoq osti."},
{num:397,time:"00:31:44,539 --> 00:31:46,860",arabic:"يَخِرْ سَاقِطًا",segs:null,full_uz:"yiqilib tushadi.",note:null},
{num:398,time:"00:31:48,580 --> 00:31:50,440",arabic:"وَمَنْ يَنْظُرْ إِلَى الْأَمَامِ",segs:[{ar:"وَمَنْ يَنْظُرْ",uz:"kim qarasa"},{ar:"إِلَى الْأَمَامِ",uz:"oldinga"}],full_uz:"Kim oldinga qarab yursa...",note:null},
{num:399,time:"00:31:50,440 --> 00:31:51,660",arabic:"يَصِلْ سَالِمًا",segs:null,full_uz:"salomat yetib boradi.",note:null},
{num:400,time:"00:31:51,660 --> 00:31:54,279",arabic:"لَمْ أَفْهَمْ",segs:null,full_uz:"Tushunmadim.",note:null},
{num:401,time:"00:31:54,279 --> 00:31:56,440",arabic:"مَاذَا تَقْصِدُ؟",segs:null,full_uz:"Nimani nazarda tutyapsan?",note:null},
{num:402,time:"00:31:57,480 --> 00:31:59,440",arabic:"لِأَنَّكَ تُحِبُّ النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ",segs:[{ar:"لِأَنَّكَ تُحِبُّ",uz:"chunki sen yoqtirasan"},{ar:"النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ",uz:"oyoqlaring ostiga qarashni"}],full_uz:"Chunki sen oyoqlaring ostiga qarashni yaxshi ko'rasan.",note:null},
{num:403,time:"00:31:59,440 --> 00:32:03,440",arabic:"اللَّهُمَّ ثَبِّتْنَا عَلَى الْعَقْلِ وَالدِّينِ",segs:[{ar:"اللَّهُمَّ ثَبِّتْنَا",uz:"Ey Alloh, bizni sobit qil"},{ar:"عَلَى الْعَقْلِ وَالدِّينِ",uz:"aql va din yo'lida"}],full_uz:"Ey Alloh, bizni aql va din yo'lida sobit qil.",note:null},
{num:404,time:"00:32:03,440 --> 00:32:05,440",arabic:"آمِينَ",segs:null,full_uz:"Omin.",note:null},
{num:405,time:"00:32:29,440 --> 00:32:38,259",arabic:"مَنْ يَنْظُرْ إِلَى مَوْطِئِ قَدَمَيْهِ يَقَعْ",segs:[{ar:"مَنْ يَنْظُرْ إِلَى مَوْطِئِ قَدَمَيْهِ",uz:"kim oyoqlari ostiga qarasa"},{ar:"يَقَعْ",uz:"yiqiladi"}],full_uz:"Kim oyoqlari ostiga qarasa, yiqiladi.",note:null},
{num:406,time:"00:32:38,259 --> 00:32:47,460",arabic:"وَأَنْتَ يَا فَرَجُ تُحِبُّ النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ",segs:[{ar:"وَأَنْتَ يَا فَرَجُ",uz:"sen esa, ey Faraj"},{ar:"تُحِبُّ النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ",uz:"oyoqlaring ostiga qarashni yaxshi ko'rasan"}],full_uz:"Sen esa, ey Faraj, oyoqlaring ostiga qarashni yaxshi ko'rasan.",note:null},
{num:407,time:"00:32:50,700 --> 00:32:52,840",arabic:"لَعَلَّكَ عَلَى حَقٍّ يَا بَهْلُولُ",segs:[{ar:"لَعَلَّكَ عَلَى حَقٍّ",uz:"ehtimol sen haqsandir"},{ar:"يَا بَهْلُولُ",uz:"ey Bahlul"}],full_uz:"Ehtimol sen haqdirsan, ey Bahlul.",note:null},
{num:408,time:"00:32:52,840 --> 00:32:56,779",arabic:"أَيْنَ الْكِتَابُ يَا أَحْمَدُ؟",segs:[{ar:"أَيْنَ الْكِتَابُ",uz:"maktub qayerda"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Maktub qayerda, ey Ahmad?",note:null},
{num:409,time:"00:32:56,779 --> 00:32:58,220",arabic:"قَدْ أَلْقَيْتُهُ فِي النَّهْرِ",segs:[{ar:"قَدْ أَلْقَيْتُهُ",uz:"uni tashladim"},{ar:"فِي النَّهْرِ",uz:"daryoga"}],full_uz:"Uni daryoga tashladim.",note:null},
{num:410,time:"00:32:59,960 --> 00:33:01,480",arabic:"أَلْقَيْتُهُ فِي النَّهْرِ يَا عَمِّ",segs:[{ar:"أَلْقَيْتُهُ فِي النَّهْرِ",uz:"uni daryoga tashladim"},{ar:"يَا عَمِّ",uz:"ey amaki"}],full_uz:"Uni daryoga tashladim, ey amaki.",note:null},
{num:411,time:"00:33:01,480 --> 00:33:06,220",arabic:"مَا الَّذِي حَمَلَكَ عَلَى فِعْلِ ذَلِكَ؟",segs:[{ar:"مَا الَّذِي حَمَلَكَ",uz:"seni nima undadi"},{ar:"عَلَى فِعْلِ ذَلِكَ؟",uz:"bunday qilishga"}],full_uz:"Seni bunday qilishga nima undadi?",note:null},
{num:412,time:"00:33:07,480 --> 00:33:10,220",arabic:"أَمْ لَعَلَّكَ ظَنَنْتَ أَنِّي أَبِيعُ دِينِي بِدُنْيَايَ؟",segs:[{ar:"أَمْ لَعَلَّكَ ظَنَنْتَ",uz:"yoki sen shunday deb o'yladingmi"},{ar:"أَنِّي أَبِيعُ دِينِي بِدُنْيَايَ؟",uz:"men dinimni dunyoyimga sotaman deb"}],full_uz:"Yoki men dinimni dunyoyimga sotaman deb o'yladingmi?",note:null},
{num:413,time:"00:33:10,220 --> 00:33:11,819",arabic:"إِنَّمَا أَنَا أَسْعَى يَا أَحْمَدُ",segs:[{ar:"إِنَّمَا أَنَا أَسْعَى",uz:"men faqat harakat qilyapman"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Men faqat harakat qilyapman, ey Ahmad.",note:null},
{num:414,time:"00:33:11,819 --> 00:33:13,299",arabic:"أَعْرِفُ غَايَاتِكَ يَا عَمِّ",segs:[{ar:"أَعْرِفُ غَايَاتِكَ",uz:"maqsadlaringizni bilaman"},{ar:"يَا عَمِّ",uz:"ey amaki"}],full_uz:"Maqsadlaringizni bilaman, ey amaki.",note:null},
{num:415,time:"00:33:13,299 --> 00:33:15,420",arabic:"اغْفِرْ لِي مَا قَدَّمْتُ",segs:[{ar:"اغْفِرْ لِي",uz:"meni kechiring"},{ar:"مَا قَدَّمْتُ",uz:"qilgan ishim uchun"}],full_uz:"Qilgan ishim uchun meni kechiring.",note:null},
{num:416,time:"00:33:15,420 --> 00:33:19,079",arabic:"وَلَكِنِّي أَرَى أَسْبَابًا لِخِدْمَةِ الرَّعِيَّةِ سِوَى مَا تَرَى أَنْتَ",segs:[{ar:"وَلَكِنِّي أَرَى أَسْبَابًا",uz:"ammo men sabablarni ko'raman"},{ar:"لِخِدْمَةِ الرَّعِيَّةِ",uz:"xalq xizmatida"},{ar:"سِوَى مَا تَرَى أَنْتَ",uz:"siz ko'rayotganingizdan boshqa"}],full_uz:"Ammo men xalq xizmat qilishning siz ko'rayotganingizdan boshqa yo'llari ham bor deb bilaman.",note:"الرَّعِيَّةُ — xalq, fuqarolar."},
{num:417,time:"00:33:28,220 --> 00:33:40,220",arabic:"هَلْ يَلْزَمُكَ عَامِلٌ؟",segs:[{ar:"هَلْ يَلْزَمُكَ",uz:"senga kerakmi"},{ar:"عَامِلٌ",uz:"ishchi"}],full_uz:"Senga ishchi kerakmi?",note:"عَامِلٌ — ishchi, xodim."},
{num:418,time:"00:33:40,220 --> 00:33:42,740",arabic:"لَيْسَ لَدَيَّ عَمَلٌ لِلُّصُوصِيِّ مِنْ أَمْثَالِكَ",segs:[{ar:"لَيْسَ لَدَيَّ عَمَلٌ",uz:"menda ish yo'q"},{ar:"لِلُّصُوصِيِّ مِنْ أَمْثَالِكَ",uz:"senga o'xshagan o'g'rilarga"}],full_uz:"Senga o'xshagan o'g'rilarga menda ish yo'q.",note:null},
{num:419,time:"00:33:42,740 --> 00:33:43,779",arabic:"انْصَرِفْ مِنْ هُنَا",segs:null,full_uz:"Bu yerdan ket.",note:null},
{num:420,time:"00:33:43,779 --> 00:33:45,140",arabic:"انْصَرِفْ مِنْ هُنَا",segs:null,full_uz:"Bu yerdan ket.",note:null},
{num:421,time:"00:33:45,140 --> 00:33:57,900",arabic:"أَخْشَى أَنَّ هَارُونَ الرَّشِيدَ لَمْ يَعُدْ كَسَابِقِ عَهْدِهِ",segs:[{ar:"أَخْشَى أَنَّ هَارُونَ الرَّشِيدَ",uz:"men Xorun ar-Rashid"},{ar:"لَمْ يَعُدْ كَسَابِقِ عَهْدِهِ",uz:"avvalgidek emasligidan qo'rqaman"}],full_uz:"Men Xorun ar-Rashid avvalgidek emasligidan qo'rqaman.",note:null},
{num:422,time:"00:33:57,900 --> 00:34:02,660",arabic:"وَإِنِّي لَا أَلْمَحُ حِرْصَهُ شَدِيدًا",segs:[{ar:"وَإِنِّي لَا أَلْمَحُ",uz:"men ko'rmayapman"},{ar:"حِرْصَهُ شَدِيدًا",uz:"uning kuchli intilishini"}],full_uz:"Men uning kuchli intilishini ko'rmayapman.",note:null},
{num:423,time:"00:34:02,660 --> 00:34:07,460",arabic:"عَلَى إِبْعَادِ وَلَدَيْهِ عَنْ كُلِّ مَا يَمَتُّ لِلْفُرْسِ بِصِلَةٍ",segs:[{ar:"عَلَى إِبْعَادِ وَلَدَيْهِ",uz:"ikki o'g'lini uzoqlashtirishga"},{ar:"عَنْ كُلِّ مَا يَمَتُّ لِلْفُرْسِ بِصِلَةٍ",uz:"forslarga aloqador har qanday narsadan"}],full_uz:"U ikki o'g'lini forslar bilan bog'liq har qanday narsadan uzoqlashtirishga intilmoqda.",note:"يَمَتُّ بِصِلَةٍ — aloqador bo'lmoq."},
{num:424,time:"00:34:07,460 --> 00:34:12,059",arabic:"إِنَّهُ يَنْتَقِي الشُّيُوخَ وَالْمُعَلِّمِينَ لَهُمَا",segs:[{ar:"إِنَّهُ يَنْتَقِي",uz:"u tanlaydi"},{ar:"الشُّيُوخَ وَالْمُعَلِّمِينَ لَهُمَا",uz:"ikkalasi uchun shayxlar va muallimlarni"}],full_uz:"U ikkalasi uchun shayxlar va muallimlarni tanlaydi.",note:null},
{num:425,time:"00:34:12,059 --> 00:34:15,840",arabic:"مِنَ الْعَرَبِ الْأَقْحَاحِ دُونَ غَيْرِهِمْ",segs:[{ar:"مِنَ الْعَرَبِ الْأَقْحَاحِ",uz:"sof arablar orasidan"},{ar:"دُونَ غَيْرِهِمْ",uz:"boshqalardan emas"}],full_uz:"Boshqalardan emas, sof arablar orasidan tanlaydi.",note:"الْأَقْحَاحُ — sof, asl."},
{num:426,time:"00:34:15,840 --> 00:34:22,099",arabic:"وَإِنْ كَانَ يَتَذَرَّعُ بِأَنَّهُ يُرِيدُ لَهُمَا لُغَةً عَرَبِيَّةً سَلِيمَةً",segs:[{ar:"وَإِنْ كَانَ يَتَذَرَّعُ",uz:"garchi u bahona qilsa ham"},{ar:"بِأَنَّهُ يُرِيدُ لَهُمَا",uz:"ikkalasi uchun xohlashini"},{ar:"لُغَةً عَرَبِيَّةً سَلِيمَةً",uz:"toza arab tilini"}],full_uz:"Garchi u bunga ikkalasi uchun toza arab tilini xohlayotganini bahona qilsa ham.",note:"يَتَذَرَّعُ بِـ — bahona qilmoq, vaj qilmoq."},
{num:427,time:"00:34:22,099 --> 00:34:25,200",arabic:"فَإِنَّ حُجَجَهُ هِيَ",segs:null,full_uz:"Aslida uning dalillari shuki...",note:null},
{num:428,time:"00:34:25,199 --> 00:34:30,460",arabic:"رُبَّمَا يَظْفَرُ بِمَا يُرِيدُ مَعَ الْأَمِينِ بْنِ زُبَيْدَةَ إِذَا أَخَذَهُ مِنْ عُيُونٍ عَرَبِيَّةٍ",segs:[{ar:"رُبَّمَا يَظْفَرُ بِمَا يُرِيدُ",uz:"ehtimol xohlaganiga erishadi"},{ar:"مَعَ الْأَمِينِ بْنِ زُبَيْدَةَ",uz:"Amin ibn Zubayda bilan"},{ar:"إِذَا أَخَذَهُ مِنْ عُيُونٍ عَرَبِيَّةٍ",uz:"agar uni sof arab manbalaridan olsa"}],full_uz:"Ehtimol Amin ibn Zubayda bilan xohlaganiga erishadi, agar uni sof arab manbalaridan olsa.",note:null},
{num:429,time:"00:34:30,460 --> 00:34:33,919",arabic:"أَمَّا ابْنُ أُخْتِنَا الْمَأْمُونُ أَبْقَاهُ اللَّهُ فَتِلْكَ الْمَسْأَلَةُ",segs:[{ar:"أَمَّا ابْنُ أُخْتِنَا الْمَأْمُونُ",uz:"ammo singlimizning o'g'li Ma'munga kelsak"},{ar:"أَبْقَاهُ اللَّهُ",uz:"Alloh uni asrasin"},{ar:"فَتِلْكَ الْمَسْأَلَةُ",uz:"masala boshqacha"}],full_uz:"Ammo singlimizning o'g'li Ma'munga kelsak, Alloh uni asrasin, masala boshqacha.",note:null},
{num:430,time:"00:34:33,919 --> 00:34:39,399",arabic:"لَنْ يَنَالَ بُغْيَتَهُ مَعَ فَتًى تَجْرِي فِي عُرُوقِهِ دِمَاءُ أُمِّهِ الْفَارِسِيَّةِ",segs:[{ar:"لَنْ يَنَالَ بُغْيَتَهُ",uz:"u maqsadiga erisha olmaydi"},{ar:"مَعَ فَتًى",uz:"shunday yigit bilan"},{ar:"تَجْرِي فِي عُرُوقِهِ دِمَاءُ أُمِّهِ الْفَارِسِيَّةِ",uz:"uning tomirlarida fors onasining qoni oqadigan"}],full_uz:"Tomirlarida fors onasining qoni oqadigan shunday yigit bilan u maqsadiga erisha olmaydi.",note:null},
{num:431,time:"00:34:39,399 --> 00:34:45,319",arabic:"إِنَّمَا خَشْيَتِي مِنَ الْمَأْمُونِ أَشَدُّ مِنْ خَشْيَتِي مِنَ الْأَمِينِ أَيُّهَا الْفَضْلُ",segs:[{ar:"إِنَّمَا خَشْيَتِي مِنَ الْمَأْمُونِ",uz:"mening Ma'mundan qo'rquvim"},{ar:"أَشَدُّ مِنْ خَشْيَتِي مِنَ الْأَمِينِ",uz:"Aminidan qo'rquvimdan kuchliroq"},{ar:"أَيُّهَا الْفَضْلُ",uz:"ey Fazl"}],full_uz:"Ey Fazl, mening Ma'mundan qo'rquvim Aminidan qo'rquvimdan kuchliroq.",note:null},
{num:432,time:"00:34:45,319 --> 00:34:51,000",arabic:"وَكَيْفَ ذَلِكَ يَا أَبِي وَالْمَأْمُونُ ابْنُ أُخْتِنَا",segs:[{ar:"وَكَيْفَ ذَلِكَ",uz:"qanday qilib"},{ar:"يَا أَبِي",uz:"ey otajon"},{ar:"وَالْمَأْمُونُ ابْنُ أُخْتِنَا",uz:"Ma'mun esa singlimizning o'g'li-ku"}],full_uz:"Qanday qilib, otajon? Ma'mun singlimizning o'g'li-ku.",note:null},
{num:433,time:"00:34:51,000 --> 00:34:52,719",arabic:"وَمِنْ بَنِي جِلْدَتِنَا",segs:null,full_uz:"U bizning urug'imizdan.",note:null},
{num:434,time:"00:34:52,719 --> 00:34:57,319",arabic:"نَسِيتَ أَنَّ الْمَأْمُونَ نَفْسَهُ يُعَانِي مِنْ كَوْنِهِ ابْنَ جَارِيَةٍ فَارِسِيَّةٍ",segs:[{ar:"نَسِيتَ",uz:"unutding"},{ar:"أَنَّ الْمَأْمُونَ نَفْسَهُ يُعَانِي",uz:"Ma'munning o'zi qiynalayotganini"},{ar:"مِنْ كَوْنِهِ ابْنَ جَارِيَةٍ فَارِسِيَّةٍ",uz:"fors cho'rining o'g'li bo'lgani sababli"}],full_uz:"Ma'munning o'zi ham fors cho'risining o'g'li bo'lgani sababli qiynalayotganini unutding.",note:null},
{num:435,time:"00:34:57,319 --> 00:35:00,839",arabic:"وَهُوَ يَرَى حَظَّةَ ابْنِ زُبَيْدَةَ الْأَمِينِ",segs:[{ar:"وَهُوَ يَرَى حَظَّ",uz:"u nasibani ko'rmoqda"},{ar:"ابْنِ زُبَيْدَةَ الْأَمِينِ",uz:"Zubaydaning o'g'li Aminning"}],full_uz:"U Zubaydaning o'g'li Aminning nasibasini ko'rmoqda.",note:"حَظٌّ — nasiba, ulush, mavqe."},
{num:436,time:"00:35:00,839 --> 00:35:03,919",arabic:"أَنْتَ بَنِي هَاشِمٍ وَالْعَرَبُ دُونَهُ",segs:[{ar:"أَنْتَ بَنِي هَاشِمٍ",uz:"sen Banu Hoshimdan"},{ar:"وَالْعَرَبُ دُونَهُ",uz:"arablar esa undan pastda"}],full_uz:"Sen Banu Hoshimdandirsan, arablar esa undan pastda.",note:null},
{num:437,time:"00:35:03,919 --> 00:35:05,199",arabic:"وَإِذَنْ يَا أَبِي",segs:null,full_uz:"Unda, otajon.",note:null},
{num:438,time:"00:35:05,199 --> 00:35:07,819",arabic:"مَا أَخْشَاهُ",segs:null,full_uz:"Men qo'rqayotgan narsa...",note:null},
{num:439,time:"00:35:07,819 --> 00:35:13,299",arabic:"أَنْ يَسْعَى الْمَأْمُونُ لِإِثْبَاتِ وَلَائِهِ لِنِصْفِهِ الْعَرَبِيِّ",segs:[{ar:"أَنْ يَسْعَى الْمَأْمُونُ",uz:"Ma'munning intilishi"},{ar:"لِإِثْبَاتِ وَلَائِهِ",uz:"o'z sadoqatini isbotlashga"},{ar:"لِنِصْفِهِ الْعَرَبِيِّ",uz:"arabiy tomoniga"}],full_uz:"Men qo'rqayotgan narsa — Ma'munning arabiy tomoniga sadoqatini isbotlashga intilishi.",note:null},
{num:440,time:"00:35:13,299 --> 00:35:16,959",arabic:"مُضَحِّيًا بِنَا نَحْنُ أَخْوَالَهُ الْفُرْسِ",segs:[{ar:"مُضَحِّيًا بِنَا",uz:"bizni qurbon qilib"},{ar:"نَحْنُ أَخْوَالَهُ الْفُرْسِ",uz:"biz uning fors tog'alari bo'lsak-da"}],full_uz:"Biz uning fors tog'alari bo'lsak-da, bizni qurbon qilib.",note:null},
{num:441,time:"00:35:16,959 --> 00:35:22,519",arabic:"جِئْنَا نَبْحَثُ عَنْ حَلٍّ لِمُشْكِلَتِنَا",segs:[{ar:"جِئْنَا",uz:"biz keldik"},{ar:"نَبْحَثُ عَنْ حَلٍّ لِمُشْكِلَتِنَا",uz:"muammomizga yechim izlab"}],full_uz:"Muammomizga yechim izlab keldik.",note:null},
{num:442,time:"00:35:22,519 --> 00:35:25,759",arabic:"عِنْدَ فَتًى مُغْرَقٍ فِي مَشَاكِلِهِ الْخَاصَّةِ",segs:[{ar:"عِنْدَ فَتًى",uz:"bir yigit huzuriga"},{ar:"مُغْرَقٍ فِي مَشَاكِلِهِ الْخَاصَّةِ",uz:"o'zining shaxsiy muammolariga botib ketgan"}],full_uz:"O'zining shaxsiy muammolariga botib ketgan bir yigit huzuriga.",note:null},
{num:443,time:"00:35:25,759 --> 00:35:31,519",arabic:"أَدْرَكْتُمْ مَكْمَنَ الْخَطَرِ يَا ابْنَ أَبْرَكٍ؟",segs:[{ar:"أَدْرَكْتُمْ مَكْمَنَ الْخَطَرِ",uz:"xavfning manbasini angladingizmi"},{ar:"يَا ابْنَ أَبْرَكٍ؟",uz:"ey Ibn Abrak"}],full_uz:"Xavfning manbasini angladingizmi, ey Ibn Abrak?",note:"مَكْمَنُ الْخَطَرِ — xavfning manbai, yashirin xavf joyi."},
{num:444,time:"00:35:33,179 --> 00:35:34,159",arabic:"أَدْرَكْنَا يَا أَبِي",segs:[{ar:"أَدْرَكْنَا",uz:"angladik"},{ar:"يَا أَبِي",uz:"otajon"}],full_uz:"Angladik, otajon.",note:null},
{num:445,time:"00:35:34,159 --> 00:35:35,519",arabic:"وَلَكِنْ مَا الْحَلُّ؟",segs:[{ar:"وَلَكِنْ",uz:"ammo"},{ar:"مَا الْحَلُّ؟",uz:"yechim nima?"}],full_uz:"Ammo yechim nima?",note:null},
{num:446,time:"00:35:38,259 --> 00:35:39,019",arabic:"لَا تَقْلَقْ",segs:null,full_uz:"Xavotir olma.",note:null},
{num:447,time:"00:35:39,019 --> 00:35:44,519",arabic:"سَأَجِدُ حَلًّا",segs:null,full_uz:"Yechim topaman.",note:null},
{num:448,time:"00:35:52,519 --> 00:36:21,519",arabic:"مُوسِيقَى",segs:null,full_uz:null,note:null},
{num:449,time:"00:36:21,519 --> 00:36:22,980",arabic:"هَلْ يَلْزَمُهُ كَعَامِلٍ؟",segs:null,full_uz:"Unga ishchi kerakmi?",note:null},
{num:450,time:"00:36:22,980 --> 00:36:23,739",arabic:"اذْهَبْ مِنْ هُنَا",segs:null,full_uz:"Bu yerdan ket.",note:null},
{num:451,time:"00:36:23,739 --> 00:36:38,280",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:452,time:"00:36:38,280 --> 00:36:40,059",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizlarga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga ham salom va Allohning rahmati.",note:null},
{num:453,time:"00:36:40,059 --> 00:36:41,420",arabic:"مَاذَا تُرِيدُ؟",segs:null,full_uz:"Nima istaysan?",note:null},
{num:454,time:"00:36:41,420 --> 00:36:42,219",arabic:"أَبْحَثُ عَنْ عَمَلٍ",segs:[{ar:"أَبْحَثُ",uz:"izlayapman"},{ar:"عَنْ عَمَلٍ",uz:"ish"}],full_uz:"Ish izlayapman.",note:null},
{num:455,time:"00:36:42,219 --> 00:36:45,519",arabic:"وَهَلْ تُجِيدُ صِنَاعَةَ الْقَرَابِيسِ وَالسُّرُوجِ؟",segs:[{ar:"وَهَلْ تُجِيدُ",uz:"eplay olasanmi"},{ar:"صِنَاعَةَ الْقَرَابِيسِ وَالسُّرُوجِ؟",uz:"qalpoq va egar yasashni"}],full_uz:"Qalpoq va egar yasashni eplay olasanmi?",note:"الْقَرَابِيسُ وَالسُّرُوجُ — ot anjomlari: qalpoq va egar."},
{num:456,time:"00:36:47,059 --> 00:36:49,460",arabic:"إِذَنْ اسْتَأْنِفْ بَحْثَكَ",segs:[{ar:"إِذَنْ",uz:"unda"},{ar:"اسْتَأْنِفْ بَحْثَكَ",uz:"qidiruvingni davom ettir"}],full_uz:"Unda qidiruvingni davom ettir.",note:"اسْتَأْنَفَ — qayta boshlamoq, davom ettirmoq."},
{num:457,time:"00:36:49,460 --> 00:36:52,059",arabic:"فَلَا مَكَانَ هُنَا إِلَّا لِمُتْقِنٍ",segs:[{ar:"فَلَا مَكَانَ هُنَا",uz:"bu yerda joy yo'q"},{ar:"إِلَّا لِمُتْقِنٍ",uz:"faqat hunarini puxta biladigan odamga"}],full_uz:"Bu yerda hunarini puxta biladigan odamdan boshqasiga joy yo'q.",note:"مُتْقِنٌ — ishini puxta biladigan, mohir."},
{num:458,time:"00:36:52,059 --> 00:36:59,800",arabic:"فَقَدْ بَحَثْتُ فِي السُّوقِ كُلِّهَا وَلَمْ أَجِدْ عَمَلًا حَتَّى وَرِمَتْ قَدَمَايَ",segs:[{ar:"فَقَدْ بَحَثْتُ فِي السُّوقِ كُلِّهَا",uz:"butun bozorda qidirdim"},{ar:"وَلَمْ أَجِدْ عَمَلًا",uz:"ammo ish topmadim"},{ar:"حَتَّى وَرِمَتْ قَدَمَايَ",uz:"hatto oyoqlarim shishib ketdi"}],full_uz:"Butun bozorda qidirdim, ammo ish topmadim, hatto oyoqlarim shishib ketdi.",note:"وَرِمَ — shishmoq."},
{num:459,time:"00:36:59,800 --> 00:37:02,079",arabic:"أُرِيدُ أَنْ أَعْمَلَ عِنْدَكَ",segs:[{ar:"أُرِيدُ أَنْ أَعْمَلَ",uz:"ishlamoqchiman"},{ar:"عِنْدَكَ",uz:"sening huzuringda"}],full_uz:"Sening huzuringda ishlamoqchiman.",note:null},
{num:460,time:"00:37:02,079 --> 00:37:06,199",arabic:"وَمَاذَا أَصْنَعُ بِكَ إِنْ لَمْ تُحْسِنْ صَنْعَتَنَا؟",segs:[{ar:"وَمَاذَا أَصْنَعُ بِكَ",uz:"seni nima qilaman"},{ar:"إِنْ لَمْ تُحْسِنْ صَنْعَتَنَا؟",uz:"agar hunarimizni bilmasang"}],full_uz:"Agar hunarimizni bilmasang, seni nima qilaman?",note:null},
{num:461,time:"00:37:06,199 --> 00:37:08,940",arabic:"وَهَلْ بَلَدٌ جَمِيعُ النَّاسِ يُحْسِنُونَ مَا يَصْنَعُونَ؟",segs:[{ar:"وَهَلْ بَلَدٌ",uz:"qaysi yurtda"},{ar:"جَمِيعُ النَّاسِ يُحْسِنُونَ مَا يَصْنَعُونَ؟",uz:"hamma odam qiladigan ishini yaxshi biladi?"}],full_uz:"Qaysi yurtda hamma odam qiladigan ishini yaxshi biladi?",note:null},
{num:462,time:"00:37:08,940 --> 00:37:11,780",arabic:"أَرْجُوكَ سَتَجِدُنِي أَتْقَنُ صَنْعَةً بِسُرْعَةٍ",segs:[{ar:"أَرْجُوكَ",uz:"iltimos"},{ar:"سَتَجِدُنِي أَتْقَنُ صَنْعَةً بِسُرْعَةٍ",uz:"meni tezda hunarni o'zlashtirgan holda ko'rasan"}],full_uz:"Iltimos, meni bu hunarni tezda o'zlashtirgan holda ko'rasan.",note:null},
{num:463,time:"00:37:11,780 --> 00:37:15,639",arabic:"إِنَّمَا أُرِيدُ أَجِيرًا يُسَاعِدُنِي لَا أُسَاعِدُهُ",segs:[{ar:"إِنَّمَا أُرِيدُ أَجِيرًا",uz:"men faqat ishchi istayman"},{ar:"يُسَاعِدُنِي",uz:"menga yordam beradigan"},{ar:"لَا أُسَاعِدُهُ",uz:"men unga yordam beradigan emas"}],full_uz:"Men faqat menga yordam beradigan ishchi istayman, men unga yordam beradigan emas.",note:"أَجِيرٌ — yollanma ishchi."},
{num:464,time:"00:37:15,639 --> 00:37:18,840",arabic:"وَأَنَا ذَلِكَ الْأَجِيرُ",segs:null,full_uz:"Men o'sha ishchiman.",note:null},
{num:465,time:"00:37:18,840 --> 00:37:20,640",arabic:"نَحْنُ بِضْعَةَ أَيَّامٍ فَقَطْ",segs:null,full_uz:"Faqat bir necha kun.",note:null},
{num:466,time:"00:37:20,640 --> 00:37:24,000",arabic:"لَا وَقْتَ لَدَيَّ أُضَيِّعُهُ مَعَكَ",segs:[{ar:"لَا وَقْتَ لَدَيَّ",uz:"menda vaqt yo'q"},{ar:"أُضَيِّعُهُ مَعَكَ",uz:"uni sen bilan sarflashga"}],full_uz:"Seni bilan sarflaydigan vaqtim yo'q.",note:null},
{num:467,time:"00:37:24,000 --> 00:37:26,019",arabic:"اذْهَبْ وَابْحَثْ عَنْ عَمَلٍ فِي مَكَانٍ آخَرَ",segs:[{ar:"اذْهَبْ",uz:"bor"},{ar:"وَابْحَثْ عَنْ عَمَلٍ فِي مَكَانٍ آخَرَ",uz:"va boshqa joydan ish izla"}],full_uz:"Bor, boshqa joydan ish izla.",note:null},
{num:468,time:"00:37:26,019 --> 00:37:29,559",arabic:"سَيِّدِي أَرْجُوكَ لَا تَكْدِرْ خَاطِرِي",segs:[{ar:"سَيِّدِي",uz:"janobim"},{ar:"أَرْجُوكَ",uz:"iltimos"},{ar:"لَا تَكْدِرْ خَاطِرِي",uz:"ko'nglimni og'ritma"}],full_uz:"Janobim, iltimos, ko'nglimni og'ritmang.",note:"كَدَّرَ خَاطِرَ — ko'nglini og'ritmoq."},
{num:469,time:"00:37:29,559 --> 00:37:33,760",arabic:"أَنَا أَعُولُ أُمِّي وَمُنْذُ أَيَّامٍ أَبْحَثُ عَنْ عَمَلٍ أَقْتَاتُ مِنْهُ وَلَمْ أَجِدْ",segs:[{ar:"أَنَا أَعُولُ أُمِّي",uz:"men onamni boqaman"},{ar:"وَمُنْذُ أَيَّامٍ أَبْحَثُ عَنْ عَمَلٍ",uz:"bir necha kundan beri ish izlayapman"},{ar:"أَقْتَاتُ مِنْهُ",uz:"undan kun kechirish uchun"},{ar:"وَلَمْ أَجِدْ",uz:"ammo topmadim"}],full_uz:"Men onamni boqaman. Bir necha kundan beri kun kechirishim uchun ish izlayapman, ammo topmadim.",note:"أَعَالَ — boqmoq, ta'minlamoq; أَقْتَاتُ — kun kechirmoq, rizq topmoq."},
{num:470,time:"00:37:33,760 --> 00:37:35,880",arabic:"لَا تُعَنِّ عَلَيَّ نَوَائِبَ دَهْرِي",segs:[{ar:"لَا تُعَنِّ عَلَيَّ",uz:"menga yanada og'irlik qilma"},{ar:"نَوَائِبَ دَهْرِي",uz:"hayotimdagi kulfatlar bilan"}],full_uz:"Hayotimdagi kulfatlarni yanada og'irlashtirma.",note:"نَوَائِبُ الدَّهْرِ — zamonning kulfatlari, hayot sinovlari."},
{num:471,time:"00:37:35,880 --> 00:37:38,480",arabic:"كَمْ أَنْتَ لَحُوحٌ يَا فَتَى",segs:[{ar:"كَمْ أَنْتَ لَحُوحٌ",uz:"sen naqadar qaysarsan"},{ar:"يَا فَتَى",uz:"ey yigit"}],full_uz:"Sen naqadar qaysarsan, ey yigit.",note:"لَحُوحٌ — qaysar, tinmay turib oladigan."},
{num:472,time:"00:37:38,480 --> 00:37:39,980",arabic:"أَرْجُوكَ",segs:null,full_uz:"Iltimos.",note:null},
{num:473,time:"00:37:41,740 --> 00:37:46,300",arabic:"وَلَكِنْ سَأَضَعُكَ قَيْدَ الاخْتِبَارِ لِأَيَّامٍ مَعْدُودَاتٍ",segs:[{ar:"وَلَكِنْ",uz:"ammo"},{ar:"سَأَضَعُكَ قَيْدَ الاخْتِبَارِ",uz:"seni sinovga qo'yaman"},{ar:"لِأَيَّامٍ مَعْدُودَاتٍ",uz:"bir necha kun"}],full_uz:"Ammo seni bir necha kun sinovdan o'tkazaman.",note:"قَيْدَ الاخْتِبَارِ — sinov muddatida, sinov ostida."},
{num:474,time:"00:37:46,300 --> 00:37:49,640",arabic:"فَإِنْ رَأَيْتُ مِنْكَ جِدًّا وَأَمَانَةً وَحِرْصًا عَلَى الْعَمَلِ",segs:[{ar:"فَإِنْ رَأَيْتُ مِنْكَ",uz:"agar sendan ko'rsam"},{ar:"جِدًّا وَأَمَانَةً",uz:"tirishqoqlik va halollikni"},{ar:"وَحِرْصًا عَلَى الْعَمَلِ",uz:"va ishga e'tiborni"}],full_uz:"Agar sendan tirishqoqlik, halollik va ishga e'tibor ko'rsam...",note:null},
{num:475,time:"00:37:49,640 --> 00:37:51,800",arabic:"وَإِلَّا طَرَحْتُكَ أَرْضًا كَمَا جِئْتَ",segs:[{ar:"وَإِلَّا طَرَحْتُكَ أَرْضًا",uz:"aks holda seni chiqarib yuboraman"},{ar:"كَمَا جِئْتَ",uz:"qanday kelgan bo'lsang, shunday"}],full_uz:"Aks holda seni qanday kelgan bo'lsang, shunday chiqarib yuboraman.",note:null},
{num:476,time:"00:37:51,800 --> 00:37:54,100",arabic:"وَعْدًا عَلَيَّ سَتَجِدُنِي أَفْضَلَ مِمَّا تَظُنُّ",segs:[{ar:"وَعْدًا عَلَيَّ",uz:"va'da beraman"},{ar:"سَتَجِدُنِي أَفْضَلَ مِمَّا تَظُنُّ",uz:"meni o'ylaganingdan ham yaxshiroq deb topasan"}],full_uz:"Va'da beraman, meni o'ylaganingdan ham yaxshiroq deb topasan.",note:null},
{num:477,time:"00:37:54,100 --> 00:37:57,880",arabic:"الْفِعْلُ أَبْقَى مِنْ لَحْنِ الْقَوْلِ يَا فَتَى",segs:[{ar:"الْفِعْلُ أَبْقَى",uz:"amal mustahkamroq"},{ar:"مِنْ لَحْنِ الْقَوْلِ",uz:"gapning ohangidan"},{ar:"يَا فَتَى",uz:"ey yigit"}],full_uz:"Amal gapning chiroyli ohangidan ko'ra mustahkamroq, ey yigit.",note:"لَحْنُ الْقَوْلِ — gapning ohangi, so'zning bezagi."},
{num:478,time:"00:37:57,880 --> 00:38:00,280",arabic:"وَمِنَ الْأَفْضَلِ أَنْ تَكُونَ كَذَلِكَ",segs:[{ar:"وَمِنَ الْأَفْضَلِ",uz:"eng yaxshisi"},{ar:"أَنْ تَكُونَ كَذَلِكَ",uz:"shunday bo'lishing"}],full_uz:"Eng yaxshisi ham shunday bo'lishing.",note:null},
{num:479,time:"00:38:00,280 --> 00:38:04,760",arabic:"هَيَّا شَمِّرْ عَنْ سَاعِدَيْكَ وَاذْهَبْ إِلَى فِرْقَةِ الْفَوَّالِ وَائْتِنَا غَدَاءَنَا",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"شَمِّرْ عَنْ سَاعِدَيْكَ",uz:"yenglaringni shimar"},{ar:"وَاذْهَبْ إِلَى فِرْقَةِ الْفَوَّالِ",uz:"va loviyachi oldiga bor"},{ar:"وَائْتِنَا غَدَاءَنَا",uz:"bizga tushlik olib kel"}],full_uz:"Qani, yenglaringni shimar, loviyachi oldiga bor va bizga tushlik olib kel.",note:"شَمَّرَ عَنْ سَاعِدَيْهِ — ishga jiddiy kirishmoq; الْفَوَّالُ — loviya taomi sotuvchisi."},
{num:480,time:"00:38:08,760 --> 00:38:13,720",arabic:"خُذْ هَذَا رُبْعَ دِرْهَمٍ لِلْفُولِ وَمِثْلَهُ لِلْخُبْزِ وَلَا تَتَأَخَّرْ",segs:[{ar:"خُذْ هَذَا",uz:"mana buni ol"},{ar:"رُبْعَ دِرْهَمٍ لِلْفُولِ",uz:"loviyaga chorak dirham"},{ar:"وَمِثْلَهُ لِلْخُبْزِ",uz:"non uchun ham shuncha"},{ar:"وَلَا تَتَأَخَّرْ",uz:"kechikma"}],full_uz:"Mana buni ol: loviyaga chorak dirham, non uchun ham shuncha. Kechikma.",note:null},
{num:481,time:"00:38:13,720 --> 00:38:15,100",arabic:"عَلَى جَنَاحَيْنِ عَامَّةً",segs:null,full_uz:"Qanot chiqarib uchgudek tez.",note:null},
{num:482,time:"00:38:15,100 --> 00:38:16,240",arabic:"انْتَظِرْ",segs:null,full_uz:"To'xta.",note:null},
{num:483,time:"00:38:16,239 --> 00:38:18,559",arabic:"مَاذَا؟ مَا اسْمُهُ؟",segs:[{ar:"مَاذَا؟",uz:"nima?"},{ar:"مَا اسْمُهُ؟",uz:"uning ismi nima?"}],full_uz:"Nima? Uning ismi nima?",note:null},
{num:484,time:"00:38:18,559 --> 00:38:18,959",arabic:"فَرَجٌ",segs:null,full_uz:"Faraj.",note:null},
{num:485,time:"00:38:18,959 --> 00:38:20,419",arabic:"اسْمِي فَرَجٌ",segs:null,full_uz:"Mening ismim Faraj.",note:null},
{num:486,time:"00:38:20,419 --> 00:38:22,539",arabic:"لَكَ مِنْ اسْمِكَ حَظٌّ وَنَصِيبٌ",segs:[{ar:"لَكَ مِنْ اسْمِكَ",uz:"ismingdan senga"},{ar:"حَظٌّ وَنَصِيبٌ",uz:"omad va nasiba bor"}],full_uz:"Ismingdan senga omad va nasiba bor.",note:"حَظٌّ وَنَصِيبٌ — omad va nasiba."},
{num:487,time:"00:38:22,539 --> 00:38:24,599",arabic:"انْتَظِرْ خُذْ",segs:null,full_uz:"To'xta, ol.",note:null},
{num:488,time:"00:38:24,599 --> 00:38:26,799",arabic:"خُذْ هَذَا الصَّحْنَ مَعَكَ",segs:[{ar:"خُذْ هَذَا الصَّحْنَ",uz:"mana bu likopchani ol"},{ar:"مَعَكَ",uz:"o'zing bilan"}],full_uz:"Mana bu likopchani o'zing bilan ol.",note:null},
{num:489,time:"00:38:26,799 --> 00:38:37,239",arabic:"وَمَاذَا لَوْ أَنَّ الْفَتَى رَاوَدَتْهُ نَفْسُهُ عَلَى سَرِقَةِ الصَّحْنِ وَالنُّقُودِ؟",segs:[{ar:"وَمَاذَا لَوْ",uz:"agar"},{ar:"أَنَّ الْفَتَى رَاوَدَتْهُ نَفْسُهُ",uz:"yigitning ko'ngliga kelib qolsa"},{ar:"عَلَى سَرِقَةِ الصَّحْنِ وَالنُّقُودِ؟",uz:"likopcha va pullarni o'g'irlash"}],full_uz:"Agar yigitning likopcha va pullarni o'g'irlash xayoliga kelib qolsa-chi?",note:"رَاوَدَتْهُ نَفْسُهُ عَلَى — ko'ngliga bir ish kelmoq, xayoliga kelmoq."},
{num:490,time:"00:38:37,239 --> 00:38:47,019",arabic:"مَا كَانَ يَجِبُ أَنْ أَرْضَى بِذَهَابِهِ مَعَ عَمِّهِ إِسْحَاقَ إِلَى الْوَالِي",segs:[{ar:"مَا كَانَ يَجِبُ",uz:"men rozi bo'lmasligim kerak edi"},{ar:"أَنْ أَرْضَى بِذَهَابِهِ مَعَ عَمِّهِ إِسْحَاقَ",uz:"uning amakisi Ishoq bilan borishiga"},{ar:"إِلَى الْوَالِي",uz:"voliy huzuriga"}],full_uz:"Uning amakisi Ishoq bilan voliy huzuriga borishiga rozi bo'lmasligim kerak edi.",note:null},
{num:491,time:"00:38:47,019 --> 00:38:52,099",arabic:"فَلَوْ أَصَابَهُ مَكْرُوهٌ لَنْ أُسَامِحَ نَفْسِي",segs:[{ar:"فَلَوْ أَصَابَهُ مَكْرُوهٌ",uz:"agar unga biror yomonlik yetsa"},{ar:"لَنْ أُسَامِحَ نَفْسِي",uz:"o'zimni kechirmayman"}],full_uz:"Agar unga biror yomonlik yetsa, o'zimni kechirmayman.",note:null},
{num:492,time:"00:38:52,099 --> 00:38:58,219",arabic:"وَلَكِنْ مَا الَّذِي فَعَلَهُ حَتَّى يُعَاقَبَ عَلَيْهِ؟",segs:[{ar:"وَلَكِنْ مَا الَّذِي فَعَلَهُ",uz:"ammo u nima qildi"},{ar:"حَتَّى يُعَاقَبَ عَلَيْهِ؟",uz:"jazolanishga loyiq darajada?"}],full_uz:"Ammo u jazolanishga loyiq darajada nima qildi?",note:null},
{num:493,time:"00:38:58,219 --> 00:39:03,699",arabic:"كُلُّ مَا قَامَ بِهِ أَنْ تَخَلَّصَ مِنْ كِتَابٍ اعْتَقَدَ أَنَّ فِيهِ أَذًى لِلنَّاسِ",segs:[{ar:"كُلُّ مَا قَامَ بِهِ",uz:"u qilgan yagona ish"},{ar:"أَنْ تَخَلَّصَ مِنْ كِتَابٍ",uz:"bir maktubdan qutulish"},{ar:"اعْتَقَدَ أَنَّ فِيهِ أَذًى لِلنَّاسِ",uz:"unda odamlarga zarar bor deb hisoblagan"}],full_uz:"U qilgan yagona ish — odamlarga zarar bor deb hisoblagan maktubdan qutulish.",note:null},
{num:494,time:"00:39:03,699 --> 00:39:06,699",arabic:"أُقْسِمُ إِنْ أَصَابَهُمْ مَكْرُوهٌ",segs:[{ar:"أُقْسِمُ",uz:"qasam ichaman"},{ar:"إِنْ أَصَابَهُمْ مَكْرُوهٌ",uz:"agar ularga biror yomonlik yetsa"}],full_uz:"Qasam ichaman, agar ularga biror yomonlik yetsa...",note:null},
{num:495,time:"00:39:06,699 --> 00:39:09,379",arabic:"فَسَيَرَوْنَ مِنِّي مَا لَا يَتَصَوَّرُونَ",segs:[{ar:"فَسَيَرَوْنَ مِنِّي",uz:"mendan ko'rishadi"},{ar:"مَا لَا يَتَصَوَّرُونَ",uz:"tasavvur ham qilmagan narsalarini"}],full_uz:"Mendan ular tasavvur ham qilmagan narsalarni ko'rishadi.",note:null},
{num:496,time:"00:39:09,379 --> 00:39:11,639",arabic:"سَأَصْبِرُ بَعْضَ الْوَقْتِ",segs:[{ar:"سَأَصْبِرُ",uz:"sabr qilaman"},{ar:"بَعْضَ الْوَقْتِ",uz:"biroz vaqt"}],full_uz:"Biroz vaqt sabr qilaman.",note:null},
{num:497,time:"00:39:11,639 --> 00:39:14,139",arabic:"وَبَعْدَهَا سَأَرَى مَا سَأَفْعَلُ",segs:[{ar:"وَبَعْدَهَا",uz:"shundan keyin"},{ar:"سَأَرَى مَا سَأَفْعَلُ",uz:"nima qilishimni ko'raman"}],full_uz:"Shundan keyin nima qilishimni ko'raman.",note:null},
{num:498,time:"00:39:14,139 --> 00:39:31,399",arabic:"هَيَّا يَا سَيِّدِي",segs:null,full_uz:"Qani, janob.",note:null},
{num:499,time:"00:39:31,399 --> 00:39:32,939",arabic:"إِنَّهُمَا سَاخِنَانِ",segs:null,full_uz:"Ikkalasi ham issiq.",note:null},
{num:500,time:"00:39:32,940 --> 00:39:37,539",arabic:"إِنَّهُمَا سَاخِنَانِ حَقًّا",segs:[{ar:"إِنَّهُمَا سَاخِنَانِ",uz:"ikkalasi ham issiq"},{ar:"حَقًّا",uz:"haqiqatan"}],full_uz:"Ikkalasi ham haqiqatan issiq.",note:null},
{num:501,time:"00:39:37,539 --> 00:39:41,360",arabic:"اجْلِسْ وَشَارِكْ مُعَلِّمَكَ طَعَامَكَ",segs:[{ar:"اجْلِسْ",uz:"o'tir"},{ar:"وَشَارِكْ مُعَلِّمَكَ",uz:"ustozing bilan baham ko'r"},{ar:"طَعَامَكَ",uz:"taomingni"}],full_uz:"O'tir va taomingni ustozing bilan baham ko'r.",note:null},
{num:502,time:"00:39:41,780 --> 00:39:46,760",arabic:"لَقَدْ أَثْبَتَّ لِي يَا فَرَجُ أَنَّكَ أَمِينٌ وَنَشِيطٌ",segs:[{ar:"لَقَدْ أَثْبَتَّ لِي",uz:"menga isbotlading"},{ar:"يَا فَرَجُ",uz:"ey Faraj"},{ar:"أَنَّكَ أَمِينٌ وَنَشِيطٌ",uz:"halol va chaqqon ekaningni"}],full_uz:"Menga halol va chaqqon ekaningni isbotlading, ey Faraj.",note:null},
{num:503,time:"00:39:46,760 --> 00:39:49,539",arabic:"وَسَنَرَى حَمَاسَكَ لِلْعَمَلِ بَعْدَ الطَّعَامِ",segs:[{ar:"وَسَنَرَى",uz:"va ko'ramiz"},{ar:"حَمَاسَكَ لِلْعَمَلِ",uz:"ishga bo'lgan ishtiyoqingni"},{ar:"بَعْدَ الطَّعَامِ",uz:"ovqatdan keyin"}],full_uz:"Ovqatdan keyin ishga bo'lgan ishtiyoqingni ham ko'ramiz.",note:"حَمَاسٌ — ishtiyoq, g'ayrat."},
{num:504,time:"00:39:50,300 --> 00:39:51,039",arabic:"تَفَضَّلْ",segs:null,full_uz:"Marhamat.",note:null},
{num:505,time:"00:39:51,039 --> 00:39:55,860",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:506,time:"00:39:55,860 --> 00:39:57,659",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizlarga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga ham salom va Allohning rahmati.",note:null},
{num:507,time:"00:39:57,659 --> 00:40:01,860",arabic:"مَاذَا جَرَى مَعَكَ عِنْدَ الْوَالِي؟",segs:[{ar:"مَاذَا جَرَى مَعَكَ",uz:"senga nima bo'ldi"},{ar:"عِنْدَ الْوَالِي؟",uz:"voliy huzurida"}],full_uz:"Voliy huzurida senga nima bo'ldi?",note:null},
{num:508,time:"00:40:01,860 --> 00:40:02,780",arabic:"لَمْ يَجْرِ كَثِيرٌ",segs:null,full_uz:"Ko'p narsa bo'lmadi.",note:null},
{num:509,time:"00:40:02,780 --> 00:40:04,780",arabic:"لَقَدْ تَرَكْتُ الْعَمَلَ فِي بَيْتِ الْحُكْمِ",segs:[{ar:"لَقَدْ تَرَكْتُ الْعَمَلَ",uz:"ishni tashladim"},{ar:"فِي بَيْتِ الْحُكْمِ",uz:"Hukm uyidagi"}],full_uz:"Hukm uyidagi ishimni tashladim.",note:null},
{num:510,time:"00:40:04,780 --> 00:40:07,240",arabic:"لَمْ تُخْبِرْنِي",segs:null,full_uz:"Menga aytmading.",note:null},
{num:511,time:"00:40:07,240 --> 00:40:10,960",arabic:"مَا الَّذِي حَدَثَ بَيْنَكَ وَبَيْنَ الْوَالِي؟",segs:[{ar:"مَا الَّذِي حَدَثَ",uz:"nima bo'ldi"},{ar:"بَيْنَكَ وَبَيْنَ الْوَالِي؟",uz:"sen bilan voliy o'rtasida"}],full_uz:"Sen bilan voliy o'rtasida nima bo'ldi?",note:null},
{num:512,time:"00:40:10,960 --> 00:40:12,800",arabic:"لَيْسَ مُهِمًّا مَا حَدَثَ بَيْنَنَا يَا أُمِّي",segs:[{ar:"لَيْسَ مُهِمًّا مَا حَدَثَ بَيْنَنَا",uz:"oramizda nima bo'lgani muhim emas"},{ar:"يَا أُمِّي",uz:"onajon"}],full_uz:"Oramizda nima bo'lgani muhim emas, onajon.",note:null},
{num:513,time:"00:40:12,800 --> 00:40:16,660",arabic:"الْمُهِمُّ أَنَّنِي تَرَكْتُ عَمَلًا كَانَ عَوْنًا لَنَا بَعْدَ اللَّهِ عَزَّ وَجَلَّ",segs:[{ar:"الْمُهِمُّ",uz:"muhimi"},{ar:"أَنَّنِي تَرَكْتُ عَمَلًا",uz:"men bir ishni tashlaganim"},{ar:"كَانَ عَوْنًا لَنَا",uz:"bizga yordam bo'lib kelgan"},{ar:"بَعْدَ اللَّهِ عَزَّ وَجَلَّ",uz:"Alloh azza va jalladan keyin"}],full_uz:"Muhimi, Alloh azza va jalladan keyin bizga yordam bo'lib kelgan ishni tashladim.",note:null},
{num:514,time:"00:40:16,660 --> 00:40:21,980",arabic:"وَالْآنَ يَجِبُ أَنْ أَبْحَثَ عَنْ عَمَلٍ مِنْ جَدِيدٍ",segs:[{ar:"وَالْآنَ",uz:"endi esa"},{ar:"يَجِبُ أَنْ أَبْحَثَ",uz:"izlashim kerak"},{ar:"عَنْ عَمَلٍ مِنْ جَدِيدٍ",uz:"yana ish"}],full_uz:"Endi esa yana ish izlashim kerak.",note:null},
{num:515,time:"00:40:21,980 --> 00:40:24,120",arabic:"أَهَذَا مَا يَجْعَلُكَ جَهْمَ الْوَجْهِ؟",segs:[{ar:"أَهَذَا مَا يَجْعَلُكَ",uz:"seni shunga majbur qilayotgan narsa shu-mi"},{ar:"جَهْمَ الْوَجْهِ؟",uz:"yuzingni tund qilayotgan?"}],full_uz:"Yuzingni tund qilayotgan narsa shu-mi?",note:"جَهْمُ الْوَجْهِ — yuzi tund, qovog'i soliq."},
{num:516,time:"00:40:24,120 --> 00:40:25,920",arabic:"أَوْ أَشَدُّ مِنْ ذَلِكَ يَا أُمِّي",segs:[{ar:"أَوْ أَشَدُّ مِنْ ذَلِكَ",uz:"yoki bundan ham og'irroq"},{ar:"يَا أُمِّي",uz:"onajon"}],full_uz:"Yoki bundan ham og'irroq, onajon.",note:null},
{num:517,time:"00:40:25,920 --> 00:40:29,980",arabic:"أَرْعَبْتِنِي يَا وَلَدِي بِدُخُولِكَ عَلَيَّ وَأَنْتَ عَلَى هَذِهِ الْحَالَةِ",segs:[{ar:"أَرْعَبْتِنِي يَا وَلَدِي",uz:"meni qo'rqitib yubording, bolam"},{ar:"بِدُخُولِكَ عَلَيَّ",uz:"oldimga shu holatda kirib kelib"},{ar:"وَأَنْتَ عَلَى هَذِهِ الْحَالَةِ",uz:"sen shu ahvolda bo'lib"}],full_uz:"Meni qo'rqitib yubording, bolam. Oldimga shu holatda kirib kelishingdan qo'rqdim.",note:null},
{num:518,time:"00:40:29,980 --> 00:40:33,219",arabic:"حَتَّى إِنَّنِي خِلْتُ أَنَّ الْوَالِي قَدْ نَالَكَ بِسُوءٍ",segs:[{ar:"حَتَّى إِنَّنِي خِلْتُ",uz:"hatto shunday deb o'yladim"},{ar:"أَنَّ الْوَالِي قَدْ نَالَكَ بِسُوءٍ",uz:"voliy senga yomonlik qilgan deb"}],full_uz:"Hatto voliy senga yomonlik qilgan deb o'yladim.",note:"نَالَهُ بِسُوءٍ — unga yomonlik yetkazmoq."},
{num:519,time:"00:40:33,219 --> 00:40:36,719",arabic:"مَهْمَا كَانَ مَا تَخْشَاهُ يَا وَلَدِي",segs:[{ar:"مَهْمَا كَانَ",uz:"qanday bo'lmasin"},{ar:"مَا تَخْشَاهُ يَا وَلَدِي",uz:"sen qo'rqayotgan narsa, bolam"}],full_uz:"Sen qo'rqayotgan narsa qanday bo'lmasin, bolam...",note:null},
{num:520,time:"00:40:36,719 --> 00:40:39,800",arabic:"أَهْوَنُ بِكَثِيرٍ مِنْ هَذَا الْقَلَقِ",segs:[{ar:"أَهْوَنُ بِكَثِيرٍ",uz:"bundan ancha yengilroq"},{ar:"مِنْ هَذَا الْقَلَقِ",uz:"bu xavotirdan"}],full_uz:"Bundan ancha yengilroq bu xavotirdan.",note:null},
{num:521,time:"00:40:39,800 --> 00:40:41,519",arabic:"اسْمَعْ يَا بُنَيَّ",segs:[{ar:"اسْمَعْ",uz:"quloq sol"},{ar:"يَا بُنَيَّ",uz:"ey bolam"}],full_uz:"Quloq sol, ey bolam.",note:null},
{num:522,time:"00:40:41,519 --> 00:40:43,940",arabic:"قَدْ عِشْنَا قَبْلَ عَمَلِكَ",segs:[{ar:"قَدْ عِشْنَا",uz:"biz yashaganmiz"},{ar:"قَبْلَ عَمَلِكَ",uz:"sening ishingdan oldin"}],full_uz:"Biz sening ishingdan oldin ham yashaganmiz.",note:null},
{num:523,time:"00:40:43,940 --> 00:40:46,539",arabic:"وَسَوْفَ نَعِيشُ بَعْدَهُ بِإِذْنِ اللَّهِ",segs:[{ar:"وَسَوْفَ نَعِيشُ بَعْدَهُ",uz:"undan keyin ham yashaymiz"},{ar:"بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan"}],full_uz:"Undan keyin ham Allohning izni bilan yashaymiz.",note:null},
{num:524,time:"00:40:46,539 --> 00:40:48,320",arabic:"وَمِنْ أَيْنَ النَّفَقَةُ يَا أُمِّي؟",segs:[{ar:"وَمِنْ أَيْنَ النَّفَقَةُ",uz:"tirikchilik xarajatlari qayerdan bo'ladi"},{ar:"يَا أُمِّي؟",uz:"onajon?"}],full_uz:"Tirikchilik xarajatlari qayerdan bo'ladi, onajon?",note:"النَّفَقَةُ — tirikchilik xarajati, sarf-xarajat."},
{num:525,time:"00:40:48,320 --> 00:40:49,280",arabic:"اسْمَعْ يَا وَلَدِي",segs:[{ar:"اسْمَعْ",uz:"quloq sol"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Quloq sol, ey bolam.",note:null},
{num:526,time:"00:40:49,280 --> 00:40:50,980",arabic:"وَكُنْتَ صَغِيرًا",segs:null,full_uz:"Sen kichkina paytingda.",note:null},
{num:527,time:"00:40:51,659 --> 00:40:53,800",arabic:"وَأَنَا أَحْرِصُ عَلَى أَنْ تَبْلُغَ غَايَتَكَ",segs:[{ar:"وَأَنَا أَحْرِصُ",uz:"men astoydil harakat qilaman"},{ar:"عَلَى أَنْ تَبْلُغَ غَايَتَكَ",uz:"maqsadingga erishishing uchun"}],full_uz:"Men maqsadingga erishishing uchun astoydil harakat qilaman.",note:null},
{num:528,time:"00:40:53,800 --> 00:40:55,980",arabic:"وَتُدْرِكُ حَاجَتَكَ",segs:null,full_uz:"Va ehtiyojingni anglab yetishing uchun.",note:null},
{num:529,time:"00:40:55,980 --> 00:41:00,800",arabic:"وَأَنَا وَأَنْتَ نَعْلَمُ جَيِّدًا بِأَنَّكَ لَنْ تَصِلَ إِلَى مَا تَصْبُو إِلَيْهِ",segs:[{ar:"وَأَنَا وَأَنْتَ نَعْلَمُ جَيِّدًا",uz:"men ham, sen ham yaxshi bilamiz"},{ar:"بِأَنَّكَ لَنْ تَصِلَ",uz:"sen erisha olmasligingni"},{ar:"إِلَى مَا تَصْبُو إِلَيْهِ",uz:"intilayotgan maqsadingga"}],full_uz:"Men ham, sen ham intilayotgan maqsadingga erisha olmasligingni yaxshi bilamiz.",note:null},
{num:530,time:"00:41:00,800 --> 00:41:03,780",arabic:"إِلَّا مِنْ خِلَالِ حِلَقِ دَرْسِكَ عِنْدَ شَيْخِكَ",segs:[{ar:"إِلَّا مِنْ خِلَالِ",uz:"faqat orqali"},{ar:"حِلَقِ دَرْسِكَ",uz:"dars halqalaring"},{ar:"عِنْدَ شَيْخِكَ",uz:"shayxing huzurida"}],full_uz:"Faqat shayxing huzuridagi dars halqalaring orqali.",note:"حِلَقُ الدَّرْسِ — dars halqalari."},
{num:531,time:"00:41:03,780 --> 00:41:05,159",arabic:"فَاعْمَلْ يَا بُنَيَّ",segs:[{ar:"فَاعْمَلْ",uz:"shuning uchun harakat qil"},{ar:"يَا بُنَيَّ",uz:"ey bolam"}],full_uz:"Shuning uchun harakat qil, ey bolam.",note:null},
{num:532,time:"00:41:05,159 --> 00:41:09,699",arabic:"عَلَى أَنْ لَا تَدَعَ شَيْئًا يَصْرِفُكَ عَنْ تَحْقِيقِ حُلْمِكَ",segs:[{ar:"عَلَى أَنْ لَا تَدَعَ شَيْئًا",uz:"hech narsaga yo'l qo'yma"},{ar:"يَصْرِفُكَ عَنْ تَحْقِيقِ حُلْمِكَ",uz:"seni orzuingni amalga oshirishdan chalg'itishiga"}],full_uz:"Hech narsa seni orzuingni amalga oshirishdan chalg'itishiga yo'l qo'yma.",note:null},
{num:533,time:"00:41:09,699 --> 00:41:12,219",arabic:"وَأَنَا لَنْ أَدَّخِرَ جُهْدًا",segs:null,full_uz:"Men ham kuchimni ayamayman.",note:"أَدَّخَرَ جُهْدًا — kuchini ayamoq."},
{num:534,time:"00:41:12,219 --> 00:41:17,199",arabic:"حَتَّى أَرَاكَ عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ",segs:[{ar:"حَتَّى أَرَاكَ",uz:"seni ko'rgunimcha"},{ar:"عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ",uz:"bu ummatning buyuk allomalaridan biri sifatida"}],full_uz:"Seni bu ummatning buyuk allomalaridan biri sifatida ko'rgunimcha.",note:"عَلَمٌ مِنْ أَعْلَامِ — buyuk namoyandalardan biri."},
{num:535,time:"00:41:17,199 --> 00:41:24,799",arabic:"ثُمَّ",segs:null,full_uz:"So'ng...",note:null},
{num:536,time:"00:41:24,799 --> 00:41:30,839",arabic:"لِمَاذَا هَذَا الْقَلَقُ عَلَى نَفَقَةِ مَعِيشَتِنَا؟",segs:[{ar:"لِمَاذَا هَذَا الْقَلَقُ",uz:"nega bu xavotir"},{ar:"عَلَى نَفَقَةِ مَعِيشَتِنَا؟",uz:"tirikchilik xarajatimiz haqida?"}],full_uz:"Nega tirikchilik xarajatimiz haqida bu qadar xavotir?",note:"نَفَقَةُ الْمَعِيشَةِ — tirikchilik xarajatlari."},
{num:537,time:"00:41:30,839 --> 00:41:32,019",arabic:"لَدَيْنَا كِرَاءُ الدُّكَّانِ",segs:[{ar:"لَدَيْنَا",uz:"bizda bor"},{ar:"كِرَاءُ الدُّكَّانِ",uz:"do'kon ijarasi"}],full_uz:"Bizda do'kon ijarasidan daromad bor.",note:"كِرَاءٌ — ijara haqi."},
{num:538,time:"00:41:32,019 --> 00:41:35,799",arabic:"وَهُوَ يَسُدُّ حَاجَتَنَا إِنِ اقْتَصَدْنَا",segs:[{ar:"وَهُوَ يَسُدُّ حَاجَتَنَا",uz:"u ehtiyojimizni qoplaydi"},{ar:"إِنِ اقْتَصَدْنَا",uz:"agar tejamkor bo'lsak"}],full_uz:"Agar tejamkor bo'lsak, u ehtiyojimizni qoplaydi.",note:"اقْتَصَدَ — tejamkor bo'lmoq."},
{num:539,time:"00:41:35,799 --> 00:41:37,519",arabic:"وَلَكِنْ يَا أُمِّي",segs:null,full_uz:"Ammo, onajon.",note:null},
{num:540,time:"00:41:37,519 --> 00:41:39,679",arabic:"كَفَاكَ عِنَادًا أَيُّهَا الْفَتَى الشَّيْخُ",segs:[{ar:"كَفَاكَ عِنَادًا",uz:"qaysarliging bas"},{ar:"أَيُّهَا الْفَتَى الشَّيْخُ",uz:"ey keksa yigit"}],full_uz:"Qaysarliging bas, ey keksa yigit.",note:"كَفَى — kifoya qilmoq, bas qilmoq."},
{num:541,time:"00:41:39,679 --> 00:41:43,519",arabic:"لَنْ تَعُودَ لِلْعَمَلِ مَرَّةً أُخْرَى",segs:[{ar:"لَنْ تَعُودَ لِلْعَمَلِ",uz:"ishga qaytmaysan"},{ar:"مَرَّةً أُخْرَى",uz:"yana"}],full_uz:"Yana ishga qaytmaysan.",note:null},
{num:542,time:"00:41:43,519 --> 00:41:46,219",arabic:"وَسَيَخْلُو ذِرَاعُكَ لِدَرْسِكَ",segs:[{ar:"وَسَيَخْلُو ذِرَاعُكَ",uz:"qo'ling bo'sh bo'ladi"},{ar:"لِدَرْسِكَ",uz:"darsing uchun"}],full_uz:"Qo'ling darsing uchun bo'sh bo'ladi.",note:"خَلَا — bo'sh bo'lmoq; ibora mazmunan vaqt va imkon bo'shashini anglatadi."},
{num:543,time:"00:41:46,219 --> 00:41:51,139",arabic:"وَلَنْ أَعُودَ لِمُنَاقَشَتِكَ فِي هَذَا الْأَمْرِ مَرَّةً ثَانِيَةً",segs:[{ar:"وَلَنْ أَعُودَ لِمُنَاقَشَتِكَ",uz:"sen bilan bu haqda yana bahslashmayman"},{ar:"فِي هَذَا الْأَمْرِ",uz:"bu masalada"},{ar:"مَرَّةً ثَانِيَةً",uz:"ikkinchi marta"}],full_uz:"Bu masalada sen bilan yana bahslashmayman.",note:null},
{num:544,time:"00:41:51,139 --> 00:41:55,039",arabic:"عِلْمُكَ هُوَ الْأَهَمُّ وَالْأَبْقَى",segs:[{ar:"عِلْمُكَ",uz:"ilming"},{ar:"هُوَ الْأَهَمُّ وَالْأَبْقَى",uz:"eng muhim va eng barqaror narsadir"}],full_uz:"Ilming eng muhim va eng barqaror narsadir.",note:null}
];

